// ── Deux hooks distincts ────────────────────────────────────────────────────
// useStorage(key, init)      → synchronisé avec Firestore (données partagées)
// useLocalStorage(key, init) → local uniquement (préférences par appareil)

// Délai avant d'écrire dans Firestore (ms) - évite de spammer à chaque frappe
const FIRESTORE_DEBOUNCE = 1500;

// Hook LOCAL uniquement - jamais synchronisé entre appareils
function useLocalStorage(key, init) {
  const [val, setVal] = useState(() => {
    try { const s = localStorage.getItem(key); return s ? JSON.parse(s) : init; }
    catch { return init; }
  });
  const setter = useCallback((valOrFn) => {
    setVal(prev => {
      const next = typeof valOrFn === "function" ? valOrFn(prev) : valOrFn;
      try { localStorage.setItem(key, JSON.stringify(next)); } catch {}
      return next;
    });
  }, [key]); // eslint-disable-line react-hooks/exhaustive-deps
  return [val, setter];
}

function useStorage(key, init) {
  // Affichage immédiat via cache localStorage
  const [val, setVal] = useState(() => {
    try { const s = localStorage.getItem(key); return s ? JSON.parse(s) : init; }
    catch { return init; }
  });

  const debounceTimer = useRef(null);
  // Vrai si une écriture locale est en cours (ignore les mises à jour Firestore
  // entrantes pendant ce temps pour éviter les conflits)
  const localWritePending = useRef(false);

  // ── Écoute Firestore en temps réel (source de vérité) ──
  useEffect(() => {
    const unsub = onSnapshot(DATA_DOC, (snap) => {
      if (!snap.exists()) return;
      const incoming = snap.data()[key];
      if (incoming === undefined) return;
      // Si l'utilisateur est en train de taper → on ignore la mise à jour
      // entrante pour ne pas écraser sa saisie
      if (localWritePending.current) return;
      setVal(incoming);
      try { localStorage.setItem(key, JSON.stringify(incoming)); } catch {}
    });
    return unsub;
  }, [key]); // eslint-disable-line react-hooks/exhaustive-deps

  // ── Setter : met à jour l'UI immédiatement, écrit Firestore après délai ──
  const setValAndSync = useCallback((valOrFn) => {
    setVal(prev => {
      const next = typeof valOrFn === "function" ? valOrFn(prev) : valOrFn;

      // 1. Mise à jour locale immédiate (UI fluide)
      try { localStorage.setItem(key, JSON.stringify(next)); } catch {}

      // 2. Écriture Firestore différée (debounce)
      localWritePending.current = true;
      if (debounceTimer.current) clearTimeout(debounceTimer.current);
      debounceTimer.current = setTimeout(() => {
        setDoc(DATA_DOC, { [key]: next }, { merge: true })
          .catch(() => {})
          .finally(() => { localWritePending.current = false; });
      }, FIRESTORE_DEBOUNCE);

      return next;
    });
  }, [key]); // eslint-disable-line react-hooks/exhaustive-deps

  return [val, setValAndSync];
}

function numberToWords(n) {
  if (!n || n === 0) return "Zero dirham";
  const ones = ["","un","deux","trois","quatre","cinq","six","sept","huit","neuf","dix","onze","douze","treize","quatorze","quinze","seize","dix-sept","dix-huit","dix-neuf"];
  const tens = ["","","vingt","trente","quarante","cinquante","soixante","soixante","quatre-vingt","quatre-vingt"];
  function below1000(num) {
    if (num === 0) return "";
    if (num < 20) return ones[num];
    if (num < 100) {
      const t = Math.floor(num / 10), o = num % 10;
      if (t === 7) return "soixante" + (o === 1 ? "-et-onze" : o ? "-" + ones[10 + o] : "-dix");
      if (t === 9) return "quatre-vingt" + (o ? "-" + ones[o] : "s");
      return tens[t] + (o === 1 && t !== 8 ? "-et-" : o ? "-" : "") + (o ? ones[o] : "");
    }
    const h = Math.floor(num / 100), r = num % 100;
    return (h === 1 ? "cent" : ones[h] + " cent") + (r ? " " + below1000(r) : h > 1 ? "s" : "");
  }
  const intPart = Math.floor(n);
  const cents = Math.round((n - intPart) * 100);
  let result = "";
  if (intPart >= 1000000) { const m = Math.floor(intPart / 1000000); result += (m === 1 ? "un million" : below1000(m) + " millions") + " "; }
  if (intPart >= 1000) { const k = Math.floor((intPart % 1000000) / 1000); if (k) result += (k === 1 ? "mille" : below1000(k) + " mille") + " "; }
  result += below1000(intPart % 1000);
  result = result.trim() + " dirham" + (intPart > 1 ? "s" : "");
  if (cents > 0) result += " et " + below1000(cents) + " centime" + (cents > 1 ? "s" : "");
  return result.charAt(0).toUpperCase() + result.slice(1);
}

// ── Pagination ───────────────────────────────────────────────────────────────
function Pagination({ total, page, perPage, onChange }) {
  const totalPages = Math.ceil(total / perPage);
  if (totalPages <= 1) return null;
  const pages = [];
  for (let i = 1; i <= totalPages; i++) {
    if (i === 1 || i === totalPages || (i >= page - 1 && i <= page + 1)) pages.push(i);
    else if (pages[pages.length - 1] !== "...") pages.push("...");
  }
  const btn = (label, disabled, onClick, active) => (
    <button key={label + Math.random()} onClick={onClick} disabled={disabled}
      style={{ border: "1px solid " + (active ? GOLD : "#e5e7eb"), background: active ? GOLD : disabled ? "#f9fafb" : "#fff", color: active ? "#fff" : disabled ? "#ccc" : "#374151", borderRadius: 7, padding: "6px 11px", cursor: disabled ? "default" : "pointer", fontWeight: active ? 700 : 500, fontSize: 13, lineHeight: 1 }}>
      {label}
    </button>
  );
  return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: 20, paddingTop: 16, borderTop: "1px solid #e5e7eb" }}>
      <span style={{ fontSize: 13, color: "#6b7280" }}>{(page - 1) * perPage + 1}–{Math.min(page * perPage, total)} sur {total}</span>
      <div style={{ display: "flex", gap: 4 }}>
        {btn("‹", page === 1, () => onChange(page - 1), false)}
        {pages.map((p, i) => p === "..." ? <span key={"d" + i} style={{ padding: "6px 4px", color: "#9ca3af", fontSize: 13 }}>…</span> : btn(p, false, () => onChange(p), p === page))}
        {btn("›", page === totalPages, () => onChange(page + 1), false)}
      </div>
    </div>
  );
}

