// ── TEMPLATE ATEBIX (Profil p4) ─────────────────────────────────────────────
function InvoiceDocP4({ facture, clients, companyInfo }) {
  const ci = companyInfo || {};
  const client = clients?.find(c => c.id === facture.clientId) || {};
  const lignes = facture.lignes || [];
  const totalHT  = lignes.reduce((s, l) => s + l.prixHT * l.qte, 0);
  const totalTVA = lignes.reduce((s, l) => s + l.prixHT * l.qte * (l.tva / 100), 0);
  const totalTTC = totalHT + totalTVA;

  // Montant HT avec séparateur de milliers  (ex: 133.083,33)
  const fmt    = v => (v ?? 0).toLocaleString("fr-MA", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  // Prix unitaire SANS séparateur de milliers (ex: 133083,33)
  const fmtPU  = v => (v ?? 0).toLocaleString("fr-MA", { minimumFractionDigits: 2, maximumFractionDigits: 2, useGrouping: false });
  // Quantité : nombre entier + virgule zéro  (ex: 1,0)
  const fmtQte = v => {
    const n = parseFloat(v) || 0;
    return Number.isInteger(n) ? n + ",0" : n.toLocaleString("fr-MA", { minimumFractionDigits: 1 });
  };

  const dateStr = facture.date ? new Date(facture.date).toLocaleDateString("fr-FR") : "";
  const annee   = facture.date ? new Date(facture.date).getFullYear() : new Date().getFullYear();
  // Numéro : si "2025_00001" → affiche "00001"
  const numStr  = (facture.numero || "").includes("_")
    ? facture.numero.split("_").slice(1).join("_")
    : facture.numero || "";

  const B   = "1px solid #999";          // bordure standard
  const GH  = "#c8c8c8";                 // gris en-tête (CASABLANCA LE / colonnes tableau)
  const GL  = "#d8d8d8";                 // gris labels client
  const NB  = 20;                        // lignes vides minimum
  const emptyRows = Math.max(0, NB - lignes.length);

  const cellL = { // en-têtes tableau articles → titres +1.5 (10→11.5)
    border: B, padding: "5px 8px", fontWeight: 700, fontSize: 11.5,
    background: GH, textAlign: "center", verticalAlign: "middle",
  };
  const tdCol = (extra = {}) => ({  // données lignes → regular +1 (10→11)
    borderLeft: B, borderRight: B,
    padding: "2px 6px", fontSize: 11, verticalAlign: "top", ...extra,
  });

  return (
    <div id="invoice-doc" style={{
      fontFamily: "Calibri, 'Calibri Regular', sans-serif",
      width: "210mm", height: "297mm",
      padding: "24px 32px 20px",
      boxSizing: "border-box",
      display: "flex", flexDirection: "column",
      background: "#fff", color: "#000",
      fontSize: 11,                         // base regular +1 (10→11)
    }}>

      {/* ── HEADER ─────────────────────────────────────────────────────────── */}
      <div style={{ display: "flex", alignItems: "center", marginBottom: 18, flexShrink: 0 }}>

        {/* Logo : 200px, côté gauche */}
        <div style={{ flex: "0 0 62%", display: "flex", alignItems: "center", justifyContent: "flex-start" }}>
          <img src={LOGO_ATX_MAIN_B64} alt="ATEBIX"
            style={{ maxHeight: 200, maxWidth: 380, objectFit: "contain" }} />
        </div>

        {/* Tableau Date + N° facture → titres +1.5 (10.5→12) */}
        <div style={{ flex: "0 0 38%" }}>
          <table style={{ borderCollapse: "collapse", width: "100%" }}>
            <tbody>
              <tr>
                <td style={{ border: B, padding: "9px 12px", background: GH, fontWeight: 700,
                             fontSize: 12, textAlign: "center", whiteSpace: "nowrap" }}>
                  CASABLANCA LE
                </td>
                <td style={{ border: B, padding: "9px 14px", textAlign: "center", background: GH,
                             fontSize: 12, fontWeight: 400, minWidth: 90 }}>
                  {dateStr}
                </td>
              </tr>
              <tr>
                <td style={{ border: B, padding: "9px 12px", background: GH, fontWeight: 700,
                             fontSize: 12, textAlign: "center", whiteSpace: "nowrap" }}>
                  FACTURE {annee} N°
                </td>
                <td style={{ border: B, padding: "9px 14px", textAlign: "center", background: GH,
                             fontSize: 12, fontWeight: 400 }}>
                  {numStr}
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>

      {/* ── CLIENT : labels titres +1.5 (10→11.5), valeurs regular +1 (10.5→11.5) ── */}
      <div style={{ flexShrink: 0, marginBottom: 16 }}>
        <table style={{ borderCollapse: "collapse", width: "100%", tableLayout: "fixed" }}>
          <colgroup>
            <col style={{ width: "50%" }} />
            <col style={{ width: "50%" }} />
          </colgroup>
          <tbody>
            <tr>
              <td style={{ border: B, padding: "6px 10px", background: GL, fontWeight: 700,
                           fontSize: 11.5, textAlign: "center", verticalAlign: "middle" }}>CLIENT</td>
              <td style={{ border: B, padding: "6px 10px", fontSize: 11.5, textAlign: "center",
                           fontWeight: 700, verticalAlign: "middle" }}>{client.nom || ""}</td>
            </tr>
            <tr>
              <td style={{ border: B, padding: "6px 10px", background: GL, fontWeight: 700,
                           fontSize: 11.5, textAlign: "center", verticalAlign: "middle" }}>ICE</td>
              <td style={{ border: B, padding: "6px 10px", fontSize: 11.5, textAlign: "center",
                           verticalAlign: "middle" }}>{client.ice || ""}</td>
            </tr>
            <tr>
              <td style={{ border: B, padding: "6px 10px", background: GL, fontWeight: 700,
                           fontSize: 11.5, textAlign: "center", verticalAlign: "middle" }}>ADRESSE</td>
              <td style={{ border: B, padding: "6px 10px", fontSize: 11.5, textAlign: "center",
                           verticalAlign: "middle" }}>{client.adresse || ""}</td>
            </tr>
          </tbody>
        </table>
      </div>

      {/* ── TABLEAU ARTICLES ────────────────────────────────────────────────── */}
      <div style={{ flex: 1, display: "flex", flexDirection: "column", marginBottom: 10 }}>
        <table style={{
          borderCollapse: "collapse", width: "100%", tableLayout: "fixed",
          border: B, flex: 1,
        }}>
          <colgroup>
            <col style={{ width: "8%" }} />
            <col style={{ width: "47%" }} />
            <col style={{ width: "16%" }} />
            <col style={{ width: "13%" }} />
            <col style={{ width: "16%" }} />
          </colgroup>
          <thead>
            <tr>
              <th style={cellL}>Réf</th>
              <th style={{ ...cellL, textAlign: "left", padding: "5px 8px" }}>Description</th>
              <th style={cellL}>PU HT</th>
              <th style={cellL}>Quantité</th>
              <th style={cellL}>Montant HT</th>
            </tr>
          </thead>
          <tbody>
            {lignes.map((l, i) => (
              <tr key={i} style={{ height: 18 }}>
                <td style={tdCol({ textAlign: "left" })}>{l.ref || ""}</td>
                <td style={tdCol({ padding: "2px 8px" })}>{l.description || ""}</td>
                <td style={tdCol({ textAlign: "right" })}>{fmtPU(l.prixHT)}</td>
                <td style={tdCol({ textAlign: "right" })}>{fmtQte(l.qte)}</td>
                <td style={tdCol({ textAlign: "right" })}>{fmt(l.prixHT * l.qte)}</td>
              </tr>
            ))}
            {[...Array(emptyRows)].map((_, i) => (
              <tr key={"e" + i} style={{ height: 18 }}>
                <td style={{ borderLeft: B, borderRight: B }}></td>
                <td style={{ borderLeft: B, borderRight: B }}></td>
                <td style={{ borderLeft: B, borderRight: B }}></td>
                <td style={{ borderLeft: B, borderRight: B }}></td>
                <td style={{ borderLeft: B, borderRight: B }}></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* ── TOTAUX ──────────────────────────────────────────────────────────── */}
      <div style={{ flexShrink: 0, marginBottom: 12 }}>
        <table style={{ borderCollapse: "collapse", width: "100%" }}>
          <colgroup>
            <col style={{ width: "72%" }} />
            <col style={{ width: "28%" }} />
          </colgroup>
          <tbody>
            <tr>
              {/* Total HT : regular +1 (10→11) */}
              <td style={{ border: B, padding: "5px 12px", textAlign: "center", fontSize: 11 }}>
                Total hors taxe Dirham
              </td>
              <td style={{ border: B, padding: "5px 10px", textAlign: "right", fontSize: 11, fontWeight: 700 }}>
                {fmt(totalHT)}
              </td>
            </tr>
            <tr>
              {/* TVA : regular +1 (10→11) */}
              <td style={{ border: B, padding: "5px 12px", textAlign: "center", fontSize: 11 }}>
                La taxe sur la valeur ajoutée (TVA) Dirham
              </td>
              <td style={{ border: B, padding: "5px 10px", textAlign: "right", fontSize: 11, fontWeight: 700 }}>
                {fmt(totalTVA)}
              </td>
            </tr>
            <tr>
              {/* TTC : titre +1.5 (10→11.5 label, 11→12.5 valeur) */}
              <td style={{ border: B, padding: "5px 12px", textAlign: "center", fontSize: 11.5, fontWeight: 700 }}>
                Toutes taxes comprises Dirham
              </td>
              <td style={{ border: B, padding: "5px 10px", textAlign: "right", fontSize: 12.5, fontWeight: 900 }}>
                {fmt(totalTTC)}
              </td>
            </tr>
          </tbody>
        </table>
      </div>

      {/* ── MONTANT EN LETTRES : titre +1.5 (10.5→12), texte regular +1 (10.5→11.5) ── */}
      <div style={{ flexShrink: 0, marginBottom: 14, paddingLeft: 4 }}>
        <div style={{ fontWeight: 700, textDecoration: "underline", fontSize: 12, marginBottom: 3 }}>
          Arrêtée la présente facture à la somme de :
        </div>
        <div style={{ fontSize: 11.5 }}>
          {numberToWords(Math.round(totalTTC))} dirhams
        </div>
      </div>

      {/* ── PIED DE PAGE : regular +1 (8.5→9.5) ────────────────────────────── */}
      <div style={{ marginTop: "auto", flexShrink: 0, textAlign: "center", paddingTop: 8 }}>
        <img src={LOGO_ATX_BAS_B64} alt="ATEBIX"
          style={{ height: 42, objectFit: "contain", display: "block", margin: "0 auto 5px" }} />
        <div style={{ fontSize: 9.5, color: "#1a5fa0", lineHeight: 1.7 }}>
          Siège social : {ci.adresse || "77 RUE MOHAMED SMIHA ETG 10 N° 57 CASABLANCA"}{" "}
          RC : {ci.rc || "703179"} / IF : {ci.if_ || "68812279"} / TP : {ci.tp || "32109101"} /{" "}
          ICE : {ci.ice || "003842769000026"} / Contact : {ci.email || "ate.bix@outlook.fr"}
        </div>
      </div>

    </div>
  );
}

