// ── UI Helpers ───────────────────────────────────────────────────────────────
function FieldLabel({ text, required }) {
  return (
    <label style={{ display: "block", fontSize: 11, fontWeight: 700, color: "#374151", marginBottom: 5, textTransform: "uppercase", letterSpacing: "0.05em" }}>
      {text}{required && <span style={{ color: "#ef4444", marginLeft: 3 }}>*</span>}
    </label>
  );
}

function TextInput({ label, value, onChange, type = "text", placeholder, required, style }) {
  const [focus, setFocus] = useState(false);
  return (
    <div style={{ marginBottom: 14, ...style }}>
      {label && <FieldLabel text={label} required={required} />}
      <input type={type} value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder}
        onFocus={() => setFocus(true)} onBlur={() => setFocus(false)}
        style={{ width: "100%", border: "1.5px solid " + (focus ? GOLD : "#d1d5db"), borderRadius: 8, padding: "9px 12px", fontSize: 14, outline: "none", boxSizing: "border-box", fontFamily: "inherit", color: "#111", background: "#fff", transition: "border-color .15s" }} />
    </div>
  );
}

function SelectInput({ label, value, onChange, options, placeholder, required }) {
  return (
    <div style={{ marginBottom: 14 }}>
      {label && <FieldLabel text={label} required={required} />}
      <select value={value} onChange={(e) => onChange(e.target.value)}
        style={{ width: "100%", border: "1.5px solid #d1d5db", borderRadius: 8, padding: "9px 12px", fontSize: 14, outline: "none", boxSizing: "border-box", fontFamily: "inherit", color: "#111", background: "#fff", cursor: "pointer" }}>
        {placeholder && <option value="">{placeholder}</option>}
        {options.map((o) => <option key={o.value ?? o} value={o.value ?? o}>{o.label ?? o}</option>)}
      </select>
    </div>
  );
}

function Badge({ text, color = "blue" }) {
  const C = { blue: "#1e40af", green: "#166534", gray: "#4b5563", orange: "#92400e" };
  return <span style={{ background: C[color] + "15", color: C[color], border: "1px solid " + C[color] + "30", borderRadius: 6, padding: "2px 9px", fontSize: 11, fontWeight: 600 }}>{text}</span>;
}

function SmallBtn({ label, bg, color, onClick }) {
  return (
    <button onClick={onClick} style={{ background: bg, color, border: "none", borderRadius: 7, padding: "5px 12px", cursor: "pointer", fontWeight: 600, fontSize: 12, whiteSpace: "nowrap" }}>
      {label}
    </button>
  );
}

function OverlayModal({ title, onClose, children }) {
  return (
    <div style={{ position: "fixed", inset: 0, background: "#00000088", zIndex: 2000, display: "flex", alignItems: "center", justifyContent: "center", padding: 20 }}>
      <div style={{ background: "#fff", borderRadius: 16, width: "100%", maxWidth: 560, maxHeight: "90vh", overflow: "auto", boxShadow: "0 25px 60px #0006" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "20px 24px 16px", borderBottom: "1px solid #e5e7eb" }}>
          <h3 style={{ margin: 0, fontSize: 18, fontWeight: 700, color: "#111" }}>{title}</h3>
          <button onClick={onClose} style={{ border: "none", background: "#f3f4f6", borderRadius: 8, width: 32, height: 32, cursor: "pointer", fontSize: 16, color: "#6b7280" }}>X</button>
        </div>
        <div style={{ padding: "20px 24px" }}>{children}</div>
      </div>
    </div>
  );
}

// ── Shared styles ────────────────────────────────────────────────────────────
const TH = { padding: "11px 14px", textAlign: "left", fontSize: 11, fontWeight: 700, color: "#6b7280", textTransform: "uppercase", letterSpacing: "0.05em", borderBottom: "2px solid #e5e7eb", background: "#f9fafb" };
const TD = { padding: "12px 14px", fontSize: 13, borderBottom: "1px solid #f3f4f6", verticalAlign: "middle" };
const CARD = { background: "#fff", borderRadius: 14, padding: "22px 26px", boxShadow: "0 2px 16px #00000008" };
const SEARCH_INPUT = { border: "1.5px solid #e5e7eb", borderRadius: 10, padding: "9px 14px 9px 38px", fontSize: 14, outline: "none", width: 290, fontFamily: "inherit", color: "#111" };
const BTN_PRIMARY = { background: GOLD, color: "#fff", border: "none", borderRadius: 10, padding: "10px 22px", cursor: "pointer", fontWeight: 700, fontSize: 14, display: "flex", alignItems: "center", gap: 8, whiteSpace: "nowrap" };
const BTN_SECONDARY = { background: "#f3f4f6", color: "#374151", border: "1px solid #e5e7eb", borderRadius: 10, padding: "10px 20px", cursor: "pointer", fontWeight: 600, fontSize: 14 };

// ── Import Excel Modal ────────────────────────────────────────────────────────
const CLIENT_FIELDS = [
  { key: "nom",     label: "Nom / Raison Sociale", required: true,  keywords: ["nom","raison","client","name","societe","entreprise"] },
  { key: "ice",     label: "ICE",                  required: false, keywords: ["ice"] },
  { key: "adresse", label: "Adresse",               required: false, keywords: ["adresse","address","rue"] },
  { key: "ville",   label: "Ville",                 required: false, keywords: ["ville","city","localite"] },
  { key: "type",    label: "Type",                  required: false, keywords: ["type","categorie"] },
  { key: "tel",     label: "Telephone",             required: false, keywords: ["tel","phone","telephone","mobile","portable"] },
  { key: "email",   label: "Email",                 required: false, keywords: ["email","mail","e-mail","courriel"] },
];

const PRODUCT_FIELDS = [
  { key: "description", label: "Description",  required: false, keywords: ["description","produit","service","libelle","designation","article","nom"] },
  { key: "prixHT",      label: "Prix HT (DH)", required: true,  keywords: ["ht","prix","price","montant","tarif","cout","unitaire"] },
  { key: "tva",         label: "Taux TVA (%)", required: false, keywords: ["tva","tax","taxe","taux"] },
  { key: "categorie",   label: "Catégorie",    required: false, keywords: ["categorie","category","cat","famille","type"] },
];

function autoMapColumns(headers, fields) {
  const mapping = {};
  fields.forEach((f) => {
    const found = headers.findIndex((h) =>
      f.keywords.some((kw) => String(h).toLowerCase().replace(/[^a-z]/g, "").includes(kw))
    );
    mapping[f.key] = found >= 0 ? found : "";
  });
  return mapping;
}

function ImportModal({ type, onClose, onImport, existingCount, nextId }) {
  const fields = type === "clients" ? CLIENT_FIELDS : PRODUCT_FIELDS;
  const [step, setStep] = useState("upload"); // upload | map | preview | done
  const [dragOver, setDragOver] = useState(false);
  const [workbook, setWorkbook] = useState(null);
  const [sheets, setSheets] = useState([]);
  const [activeSheet, setActiveSheet] = useState("");
  const [headers, setHeaders] = useState([]);
  const [rows, setRows] = useState([]);
  const [mapping, setMapping] = useState({});
  const [mode, setMode] = useState("append"); // append | replace
  const [parsed, setParsed] = useState([]);
  const [errors, setErrors] = useState([]);
  const fileRef = useRef();

  const processFile = (file) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const wb = XLSX.read(e.target.result, { type: "binary", cellDates: true });
        setWorkbook(wb);
        setSheets(wb.SheetNames);
        selectSheet(wb, wb.SheetNames[0]);
      } catch {
        alert("Impossible de lire ce fichier. Veuillez utiliser un fichier .xlsx ou .xls valide.");
      }
    };
    reader.readAsBinaryString(file);
  };

  const selectSheet = (wb, sheetName) => {
    setActiveSheet(sheetName);
    const ws = wb.Sheets[sheetName];
    const data = XLSX.utils.sheet_to_json(ws, { header: 1, defval: "" });
    // Find first non-empty row as header
    const headerRowIdx = data.findIndex((r) => r.some((c) => c !== ""));
    if (headerRowIdx < 0) { setHeaders([]); setRows([]); return; }
    const hdrs = data[headerRowIdx].map((h) => String(h).trim());
    const dataRows = data.slice(headerRowIdx + 1).filter((r) => r.some((c) => c !== ""));
    setHeaders(hdrs);
    setRows(dataRows);
    setMapping(autoMapColumns(hdrs, fields));
    setStep("map");
  };

  const doParse = () => {
    const errs = [];
    const result = rows.map((row, i) => {
      const obj = {};
      fields.forEach((f) => {
        const col = mapping[f.key];
        obj[f.key] = col !== "" && col !== undefined ? String(row[col] ?? "").trim() : "";
      });
      // Validation
      fields.filter((f) => f.required).forEach((f) => {
        if (!obj[f.key]) errs.push(`Ligne ${i + 2} : "${f.label}" est vide.`);
      });
      // Coerce numbers
      if (type === "products") {
        obj.prixHT = parseFloat(String(obj.prixHT).replace(/[^\d.,-]/g, "").replace(",", ".")) || 0;
        obj.tva = parseFloat(String(obj.tva).replace(/[^\d.]/g, "")) || 20;
      }
      return obj;
    }).filter((o) => fields.filter((f) => f.required).every((f) => o[f.key]));

    setErrors(errs.slice(0, 10));
    setParsed(result);
    setStep("preview");
  };

  const doImport = () => {
    onImport(parsed, mode);
    setStep("done");
  };

  // Drag & drop
  const onDrop = useCallback((e) => {
    e.preventDefault(); setDragOver(false);
    const file = e.dataTransfer.files[0];
    if (file) processFile(file);
  }, []);

  const label = type === "clients" ? "clients" : "produits";
  const icon  = type === "clients" ? "👥" : "📦";

  return (
    <div style={{ position: "fixed", inset: 0, background: "#000000cc", zIndex: 4000, display: "flex", alignItems: "center", justifyContent: "center", padding: 20 }}>
      <div style={{ background: "#fff", borderRadius: 18, width: "100%", maxWidth: 700, maxHeight: "92vh", overflow: "auto", boxShadow: "0 30px 80px #0008" }}>

        {/* Header */}
        <div style={{ display: "flex", alignItems: "center", gap: 14, padding: "20px 26px 16px", borderBottom: "1px solid #e5e7eb" }}>
          <div style={{ background: GOLD + "20", borderRadius: 10, padding: "8px 11px", fontSize: 22 }}>{icon}</div>
          <div style={{ flex: 1 }}>
            <div style={{ fontSize: 18, fontWeight: 800, color: DARK }}>Import Excel — {label}</div>
            <div style={{ fontSize: 12, color: "#6b7280", marginTop: 2 }}>
              {step === "upload" && "Chargez votre fichier .xlsx ou .xls"}
              {step === "map" && "Associez les colonnes Excel a vos champs"}
              {step === "preview" && `${parsed.length} ligne(s) prete(s) a importer`}
              {step === "done" && "Import termine avec succes !"}
            </div>
          </div>
          {/* Steps */}
          <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
            {["upload","map","preview"].map((s, i) => (
              <div key={s} style={{ display: "flex", alignItems: "center", gap: 6 }}>
                <div style={{ width: 26, height: 26, borderRadius: "50%", background: step === s ? GOLD : ["upload","map","preview"].indexOf(step) > i ? "#166534" : "#e5e7eb", color: step === s || ["upload","map","preview"].indexOf(step) > i ? "#fff" : "#9ca3af", fontSize: 11, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center" }}>
                  {["upload","map","preview"].indexOf(step) > i ? "✓" : i + 1}
                </div>
                {i < 2 && <div style={{ width: 20, height: 2, background: ["upload","map","preview"].indexOf(step) > i ? GOLD : "#e5e7eb" }} />}
              </div>
            ))}
          </div>
          <button onClick={onClose} style={{ border: "none", background: "#f3f4f6", borderRadius: 8, width: 32, height: 32, cursor: "pointer", fontSize: 16, color: "#6b7280" }}>✕</button>
        </div>

        <div style={{ padding: "22px 26px" }}>

          {/* ─── STEP 1: UPLOAD ─── */}
          {step === "upload" && (
            <div>
              <div
                onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
                onDragLeave={() => setDragOver(false)}
                onDrop={onDrop}
                onClick={() => fileRef.current?.click()}
                style={{ border: "2px dashed " + (dragOver ? GOLD : "#d1d5db"), borderRadius: 14, padding: "48px 24px", textAlign: "center", cursor: "pointer", background: dragOver ? GOLD + "08" : "#fafaf8", transition: "all .2s" }}>
                <div style={{ fontSize: 44, marginBottom: 12 }}>📂</div>
                <div style={{ fontSize: 16, fontWeight: 700, color: DARK, marginBottom: 6 }}>Glissez votre fichier Excel ici</div>
                <div style={{ fontSize: 13, color: "#6b7280", marginBottom: 16 }}>ou cliquez pour parcourir</div>
                <div style={{ display: "inline-block", background: GOLD, color: "#fff", borderRadius: 8, padding: "8px 22px", fontSize: 13, fontWeight: 700 }}>Choisir un fichier</div>
                <div style={{ fontSize: 11, color: "#9ca3af", marginTop: 14 }}>Formats acceptes : .xlsx, .xls, .csv</div>
              </div>
              <input ref={fileRef} type="file" accept=".xlsx,.xls,.csv" style={{ display: "none" }}
                onChange={(e) => { if (e.target.files[0]) processFile(e.target.files[0]); }} />

              {/* Template download hint */}
              <div style={{ marginTop: 18, background: "#f0f6ff", border: "1px solid #bfdbfe", borderRadius: 10, padding: "12px 16px", fontSize: 12, color: "#1d4ed8" }}>
                <span style={{ fontWeight: 700 }}>Format attendu pour {label} : </span>
                {type === "clients"
                  ? "Colonnes suggérées : Nom, ICE, Adresse, Ville, Telephone, Email, Type"
                  : "Colonnes suggérées : Description, Prix HT, TVA"}
                <span style={{ color: "#6b7280", marginLeft: 6 }}>— le mapping est configurable a l'etape suivante.</span>
              </div>
            </div>
          )}

          {/* ─── STEP 2: MAP ─── */}
          {step === "map" && (
            <div>
              {/* Sheet selector */}
              {sheets.length > 1 && (
                <div style={{ marginBottom: 18 }}>
                  <label style={{ fontSize: 12, fontWeight: 700, color: "#374151", textTransform: "uppercase", letterSpacing: "0.05em", display: "block", marginBottom: 6 }}>Feuille Excel</label>
                  <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                    {sheets.map((s) => (
                      <button key={s} onClick={() => selectSheet(workbook, s)}
                        style={{ border: "1.5px solid " + (s === activeSheet ? GOLD : "#e5e7eb"), background: s === activeSheet ? GOLD + "15" : "#fff", color: s === activeSheet ? GOLD : "#374151", borderRadius: 8, padding: "6px 14px", cursor: "pointer", fontWeight: s === activeSheet ? 700 : 500, fontSize: 13 }}>
                        {s}
                      </button>
                    ))}
                  </div>
                </div>
              )}

              <div style={{ fontSize: 13, color: "#6b7280", marginBottom: 14 }}>
                <b style={{ color: DARK }}>{rows.length} ligne(s)</b> detectee(s) · <b style={{ color: DARK }}>{headers.length} colonnes</b> — Associez chaque champ a la colonne Excel correspondante.
              </div>

              {/* Mapping grid */}
              <div style={{ display: "grid", gap: 10, marginBottom: 20 }}>
                {fields.map((f) => (
                  <div key={f.key} style={{ display: "grid", gridTemplateColumns: "180px 1fr", alignItems: "center", gap: 14, background: "#fafaf8", borderRadius: 9, padding: "10px 14px", border: "1px solid #f0f0f0" }}>
                    <div>
                      <span style={{ fontSize: 13, fontWeight: 700, color: DARK }}>{f.label}</span>
                      {f.required && <span style={{ color: "#ef4444", marginLeft: 4, fontSize: 11 }}>*</span>}
                      <div style={{ fontSize: 10, color: "#9ca3af", marginTop: 2 }}>Champ application</div>
                    </div>
                    <div>
                      <select value={mapping[f.key] ?? ""}
                        onChange={(e) => setMapping({ ...mapping, [f.key]: e.target.value === "" ? "" : parseInt(e.target.value) })}
                        style={{ width: "100%", border: "1.5px solid " + (mapping[f.key] !== "" && mapping[f.key] !== undefined ? GOLD : "#d1d5db"), borderRadius: 8, padding: "8px 12px", fontSize: 13, outline: "none", cursor: "pointer", fontFamily: "inherit", background: "#fff" }}>
                        <option value="">— Ignorer ce champ —</option>
                        {headers.map((h, i) => (
                          <option key={i} value={i}>{h || "(colonne " + (i + 1) + ")"}</option>
                        ))}
                      </select>
                      {mapping[f.key] !== "" && mapping[f.key] !== undefined && rows[0] && (
                        <div style={{ fontSize: 11, color: GOLD, marginTop: 3, fontStyle: "italic" }}>
                          Exemple : {String(rows[0][mapping[f.key]] ?? "").slice(0, 60) || "(vide)"}
                        </div>
                      )}
                    </div>
                  </div>
                ))}
              </div>

              {/* Import mode */}
              <div style={{ background: "#f8f8f6", borderRadius: 10, padding: "14px 16px", marginBottom: 18 }}>
                <div style={{ fontSize: 12, fontWeight: 700, color: "#374151", textTransform: "uppercase", letterSpacing: "0.05em", marginBottom: 10 }}>Mode d'import</div>
                <div style={{ display: "flex", gap: 10 }}>
                  {[
                    { val: "append",  icon: "➕", title: "Ajouter",   desc: "Ajouter aux " + existingCount + " existants" },
                    { val: "replace", icon: "🔄", title: "Remplacer", desc: "Effacer et remplacer tout" },
                  ].map((m) => (
                    <div key={m.val} onClick={() => setMode(m.val)}
                      style={{ flex: 1, border: "2px solid " + (mode === m.val ? GOLD : "#e5e7eb"), borderRadius: 10, padding: "12px 14px", cursor: "pointer", background: mode === m.val ? GOLD + "10" : "#fff" }}>
                      <div style={{ fontSize: 18, marginBottom: 4 }}>{m.icon}</div>
                      <div style={{ fontSize: 13, fontWeight: 700, color: mode === m.val ? GOLD : DARK }}>{m.title}</div>
                      <div style={{ fontSize: 11, color: "#6b7280", marginTop: 2 }}>{m.desc}</div>
                    </div>
                  ))}
                </div>
              </div>

              <div style={{ display: "flex", justifyContent: "space-between", paddingTop: 14, borderTop: "1px solid #e5e7eb" }}>
                <button onClick={() => setStep("upload")} style={BTN_SECONDARY}>← Retour</button>
                <button onClick={doParse}
                  disabled={fields.filter((f) => f.required).some((f) => mapping[f.key] === "" || mapping[f.key] === undefined)}
                  style={{ ...BTN_PRIMARY, opacity: fields.filter((f) => f.required).some((f) => mapping[f.key] === "" || mapping[f.key] === undefined) ? 0.4 : 1 }}>
                  Previsualiser →
                </button>
              </div>
            </div>
          )}

          {/* ─── STEP 3: PREVIEW ─── */}
          {step === "preview" && (
            <div>
              {errors.length > 0 && (
                <div style={{ background: "#fef2f2", border: "1px solid #fecaca", borderRadius: 10, padding: "12px 16px", marginBottom: 16 }}>
                  <div style={{ fontSize: 13, fontWeight: 700, color: "#991b1b", marginBottom: 6 }}>⚠ {errors.length} avertissement(s) — ces lignes seront ignorees :</div>
                  {errors.map((e, i) => <div key={i} style={{ fontSize: 12, color: "#b91c1c", marginTop: 2 }}>• {e}</div>)}
                </div>
              )}

              <div style={{ background: "#f0fdf4", border: "1px solid #86efac", borderRadius: 10, padding: "12px 16px", marginBottom: 16, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <span style={{ fontSize: 14, fontWeight: 700, color: "#166534" }}>{parsed.length} {label}</span>
                  <span style={{ fontSize: 13, color: "#4ade80", marginLeft: 8 }}>pret(s) a importer</span>
                </div>
                <div style={{ fontSize: 12, color: "#166534" }}>
                  Mode : <b>{mode === "append" ? "Ajout aux existants" : "Remplacement complet"}</b>
                </div>
              </div>

              {/* Preview table */}
              <div style={{ maxHeight: 320, overflowY: "auto", border: "1px solid #e5e7eb", borderRadius: 10, marginBottom: 18 }}>
                <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
                  <thead style={{ position: "sticky", top: 0 }}>
                    <tr style={{ background: DARK }}>
                      <th style={{ padding: "8px 12px", textAlign: "left", color: "#fff", fontWeight: 700, fontSize: 11 }}>#</th>
                      {fields.filter((f) => mapping[f.key] !== "" && mapping[f.key] !== undefined).map((f) => (
                        <th key={f.key} style={{ padding: "8px 12px", textAlign: "left", color: "#fff", fontWeight: 700, fontSize: 11 }}>{f.label}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {parsed.slice(0, 50).map((row, i) => (
                      <tr key={i} style={{ borderBottom: "1px solid #f3f4f6", background: i % 2 === 0 ? "#fff" : "#fafaf8" }}>
                        <td style={{ padding: "7px 12px", color: "#9ca3af", fontWeight: 600 }}>{i + 1}</td>
                        {fields.filter((f) => mapping[f.key] !== "" && mapping[f.key] !== undefined).map((f) => (
                          <td key={f.key} style={{ padding: "7px 12px", color: "#374151", maxWidth: 180, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                            {String(row[f.key] ?? "")}
                          </td>
                        ))}
                      </tr>
                    ))}
                  </tbody>
                </table>
                {parsed.length > 50 && <div style={{ padding: "8px 12px", fontSize: 11, color: "#9ca3af", textAlign: "center", borderTop: "1px solid #f3f4f6" }}>... et {parsed.length - 50} autres lignes</div>}
              </div>

              <div style={{ display: "flex", justifyContent: "space-between", paddingTop: 14, borderTop: "1px solid #e5e7eb" }}>
                <button onClick={() => setStep("map")} style={BTN_SECONDARY}>← Retour</button>
                <button onClick={doImport} style={{ ...BTN_PRIMARY, background: "#166534" }} disabled={parsed.length === 0}>
                  ✓ Importer {parsed.length} {label}
                </button>
              </div>
            </div>
          )}

          {/* ─── STEP DONE ─── */}
          {step === "done" && (
            <div style={{ textAlign: "center", padding: "32px 0" }}>
              <div style={{ fontSize: 56, marginBottom: 14 }}>🎉</div>
              <div style={{ fontSize: 20, fontWeight: 900, color: DARK, marginBottom: 8 }}>Import reussi !</div>
              <div style={{ fontSize: 14, color: "#6b7280", marginBottom: 24 }}>
                <b style={{ color: "#166534" }}>{parsed.length} {label}</b> ont ete importes avec succes.
              </div>
              <button onClick={onClose} style={BTN_PRIMARY}>Fermer</button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

// ── Declaration Page Component ────────────────────────────────────────────────

function DeclarationPage({ factures, clients, customRowTags, setCustomRowTags }) {
  const [declDateDeb, setDeclDateDeb] = useState(() => { const d = new Date(); d.setDate(1); return d.toISOString().split("T")[0]; });
  const [declDateFin, setDeclDateFin] = useState(todayStr());
  const [declPeriode, setDeclPeriode] = useState("mois");
  const [rowTags, setRowTags]         = useState({});
  const [tagOpen, setTagOpen]         = useState(null);
  const [colWidths, setColWidths]     = useState({ ttc: 180, num: 180, tva: 150, date: 150, tag: 140 });
  const resizingCol  = useRef(null);
  const resizeStartX = useRef(0);
  const resizeStartW = useRef(0);

  // ── Close tag picker on outside click ────────────────────────────────────────
  useEffect(() => {
    const h = () => setTagOpen(null);
    document.addEventListener("mousedown", h);
    return () => document.removeEventListener("mousedown", h);
  }, []);

  // ── Column resize handlers ────────────────────────────────────────────────────
  const onResizeStart = useCallback((col, e) => {
    e.preventDefault();
    resizingCol.current  = col;
    resizeStartX.current = e.clientX;
    resizeStartW.current = colWidths[col];
    const onMove = (ev) => {
      const delta = ev.clientX - resizeStartX.current;
      setColWidths((prev) => ({ ...prev, [resizingCol.current]: Math.max(80, resizeStartW.current + delta) }));
    };
    const onUp = () => {
      resizingCol.current = null;
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseup", onUp);
    };
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onUp);
  }, [colWidths]);

  // ── Period shortcuts ──────────────────────────────────────────────────────────
  const applyPeriode = (p) => {
    const now = new Date();
    let deb, fin;
    if (p === "mois") {
      deb = new Date(now.getFullYear(), now.getMonth(), 1);
      fin = new Date(now.getFullYear(), now.getMonth() + 1, 0);
    } else if (p === "trim") {
      const q = Math.floor(now.getMonth() / 3);
      deb = new Date(now.getFullYear(), q * 3, 1);
      fin = new Date(now.getFullYear(), q * 3 + 3, 0);
    } else if (p === "annee") {
      deb = new Date(now.getFullYear(), 0, 1);
      fin = new Date(now.getFullYear(), 11, 31);
    } else if (p === "mois_prec") {
      deb = new Date(now.getFullYear(), now.getMonth() - 1, 1);
      fin = new Date(now.getFullYear(), now.getMonth(), 0);
    } else if (p === "trim_prec") {
      const q = Math.floor(now.getMonth() / 3) - 1;
      const yr = q < 0 ? now.getFullYear() - 1 : now.getFullYear();
      const qq = ((q % 4) + 4) % 4;
      deb = new Date(yr, qq * 3, 1);
      fin = new Date(yr, qq * 3 + 3, 0);
    } else { setDeclPeriode("custom"); return; }
    setDeclPeriode(p);
    setDeclDateDeb(deb.toISOString().split("T")[0]);
    setDeclDateFin(fin.toISOString().split("T")[0]);
  };

  const declFacts = factures.filter((f) => f.date >= declDateDeb && f.date <= declDateFin)
    .sort((a, b) => a.date.localeCompare(b.date));

  const totalHT  = declFacts.reduce((s, f) => s + f.lignes.reduce((ss, l) => ss + l.prixHT * l.qte, 0), 0);
  const totalTVA = declFacts.reduce((s, f) => s + f.lignes.reduce((ss, l) => ss + l.prixHT * l.qte * l.tva / 100, 0), 0);
  const totalTTC = totalHT + totalTVA;

  const tvaByRate = {};
  declFacts.forEach((f) => {
    f.lignes.forEach((l) => {
      const base = l.prixHT * l.qte;
      const tva  = base * l.tva / 100;
      if (!tvaByRate[l.tva]) tvaByRate[l.tva] = { base: 0, tva: 0 };
      tvaByRate[l.tva].base += base;
      tvaByRate[l.tva].tva  += tva;
    });
  });
  const tvaRates = Object.keys(tvaByRate).map(Number).sort((a, b) => b - a);

  const exportExcel = () => {
    const rows = declFacts.map((f, i) => {
      const cl  = clients.find((c) => c.id === f.clientId);
      const ht  = f.lignes.reduce((s, l) => s + l.prixHT * l.qte, 0);
      const tva = f.lignes.reduce((s, l) => s + l.prixHT * l.qte * l.tva / 100, 0);
      const tag = customRowTags.find((t) => t.id === rowTags[f.id]);
      return {
        "N°": i + 1,
        "N° Facture": f.numero,
        "Date": new Date(f.date).toLocaleDateString("fr-MA"),
        "Client": cl?.nom || "—",
        "ICE": cl?.ice || "",
        "Base HT (DH)": +ht.toFixed(2),
        "TVA (DH)": +tva.toFixed(2),
        "Total TTC (DH)": +(ht + tva).toFixed(2),
        "Règlement": f.reglement,
        "Tag": tag ? tag.label : "",
      };
    });
    rows.push({ "N°": "", "N° Facture": "TOTAUX", "Date": "", "Client": "", "ICE": "",
      "Base HT (DH)": +totalHT.toFixed(2), "TVA (DH)": +totalTVA.toFixed(2),
      "Total TTC (DH)": +totalTTC.toFixed(2), "Règlement": "", "Tag": "" });
    const ws1 = XLSX.utils.json_to_sheet(rows);
    ws1["!cols"] = [4, 16, 12, 28, 18, 16, 14, 16, 14, 14].map(w => ({ wch: w }));

    const rows2 = tvaRates.map((r) => ({
      "Taux TVA": r + "%",
      "Base HT (DH)": +tvaByRate[r].base.toFixed(2),
      "Montant TVA (DH)": +tvaByRate[r].tva.toFixed(2),
      "Total TTC (DH)": +(tvaByRate[r].base + tvaByRate[r].tva).toFixed(2),
    }));
    rows2.push({ "Taux TVA": "TOTAL", "Base HT (DH)": +totalHT.toFixed(2),
      "Montant TVA (DH)": +totalTVA.toFixed(2), "Total TTC (DH)": +totalTTC.toFixed(2) });
    const ws2 = XLSX.utils.json_to_sheet(rows2);
    ws2["!cols"] = [12, 18, 20, 18].map(w => ({ wch: w }));

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws1, "Détail Factures");
    XLSX.utils.book_append_sheet(wb, ws2, "Ventilation TVA");
    const label = declDateDeb.replace(/-/g, "") + "_" + declDateFin.replace(/-/g, "");
    XLSX.writeFile(wb, "Declaration_TVA_" + label + ".xlsx");
  };

  const PERIODES = [
    { val: "mois",      label: "Mois en cours" },
    { val: "mois_prec", label: "Mois précédent" },
    { val: "trim",      label: "Trimestre en cours" },
    { val: "trim_prec", label: "Trimestre précédent" },
    { val: "annee",     label: "Année en cours" },
    { val: "custom",    label: "Personnalisé" },
  ];

  const LABEL_STYLE    = { display: "block", fontSize: 11, fontWeight: 700, color: "#374151", marginBottom: 6, textTransform: "uppercase", letterSpacing: "0.06em" };
  const DATE_INPUT_STY = { width: "100%", border: "2px solid " + GOLD + "55", borderRadius: 9, padding: "11px 14px", fontSize: 15, outline: "none", boxSizing: "border-box", fontFamily: "inherit", fontWeight: 700, color: DARK, background: "#fffdf5" };

  // Resize handle style
  const HANDLE = {
    position: "absolute", right: 0, top: 0, bottom: 0, width: 5,
    cursor: "col-resize", userSelect: "none",
    background: "transparent",
    borderRight: "2px solid #ffffff22",
  };

  const COLS = [
    { key: "ttc",  label: "Total TTC (DH)", align: "right" },
    { key: "num",  label: "N° Facture",      align: "left"  },
    { key: "tva",  label: "TVA (DH)",         align: "right" },
    { key: "date", label: "Date",             align: "left"  },
    { key: "tag",  label: "Tag",              align: "center" },
  ];

  return (
    <>
      {/* ── En-tête ── */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 24 }}>
        <div>
          <h1 style={{ margin: 0, fontSize: 26, fontWeight: 900, color: DARK }}>Déclaration TVA</h1>
          <div style={{ color: "#6b7280", fontSize: 14, marginTop: 4 }}>Saisissez la plage de dates pour générer votre déclaration</div>
        </div>
        <button style={{ ...BTN_PRIMARY, background: "#166534", opacity: declFacts.length === 0 ? 0.45 : 1 }}
          onClick={exportExcel} disabled={declFacts.length === 0}>
          📥 Exporter Excel
        </button>
      </div>

      {/* ── Éditeur de tags ── */}
      <details style={{ ...CARD, marginBottom: 16, cursor: "pointer" }}>
        <summary style={{ display: "flex", alignItems: "center", gap: 10, fontSize: 14, fontWeight: 700, color: DARK, listStyle: "none", userSelect: "none" }}>
          <span style={{ background: GOLD + "20", borderRadius: 8, padding: "5px 9px", fontSize: 16 }}>🏷️</span>
          Personnaliser les tags de la déclaration
          <span style={{ marginLeft: "auto", fontSize: 12, color: "#9ca3af", fontWeight: 400 }}>Cliquer pour dérouler</span>
        </summary>
        <div style={{ marginTop: 14, display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(160px, 1fr))", gap: 10 }}>
          {customRowTags.map((t, idx) => (
            <div key={t.id} style={{ background: t.bg, border: "1.5px solid " + t.border, borderRadius: 10, padding: "10px 12px", display: "flex", alignItems: "center", gap: 8 }}>
              <div style={{ width: 10, height: 10, borderRadius: "50%", background: t.dot, flexShrink: 0 }} />
              <input
                value={t.label}
                onChange={(e) => {
                  const updated = [...customRowTags];
                  updated[idx] = { ...t, label: e.target.value };
                  setCustomRowTags(updated);
                }}
                style={{ flex: 1, border: "none", background: "transparent", color: t.text, fontWeight: 700, fontSize: 12, outline: "none", fontFamily: "inherit" }}
                maxLength={20}
              />
            </div>
          ))}
          <button onClick={() => setCustomRowTags([...customRowTags].map((t,i) => ({ ...t, label: DEFAULT_ROW_TAGS[i]?.label || t.label })))}
            style={{ background: "#f3f4f6", border: "1.5px solid #e5e7eb", borderRadius: 10, padding: "10px 12px", cursor: "pointer", fontSize: 12, fontWeight: 600, color: "#6b7280" }}>
            ↺ Réinitialiser
          </button>
        </div>
      </details>

      {/* ── Bloc sélection période ── */}
      <div style={{ ...CARD, marginBottom: 24, border: "2px solid " + GOLD + "30" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 18 }}>
          <div style={{ background: GOLD + "20", borderRadius: 8, padding: "7px 10px", fontSize: 20 }}>📅</div>
          <h3 style={{ margin: 0, fontSize: 16, fontWeight: 900, color: DARK }}>Plage de dates</h3>
          <div style={{ marginLeft: "auto", background: GOLD + "18", border: "1.5px solid " + GOLD + "60", borderRadius: 10, padding: "6px 18px", display: "flex", alignItems: "center", gap: 10 }}>
            <span style={{ fontSize: 11, color: GOLD, fontWeight: 700 }}>FACTURES</span>
            <span style={{ fontSize: 22, fontWeight: 900, color: DARK }}>{declFacts.length}</span>
          </div>
        </div>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 20 }}>
          {PERIODES.map((p) => (
            <button key={p.val} onClick={() => applyPeriode(p.val)}
              style={{ border: "1.5px solid " + (declPeriode === p.val ? GOLD : "#e5e7eb"), background: declPeriode === p.val ? GOLD : "#fff", color: declPeriode === p.val ? "#fff" : "#374151", borderRadius: 8, padding: "7px 16px", cursor: "pointer", fontWeight: declPeriode === p.val ? 700 : 500, fontSize: 13, transition: "all .15s" }}>
              {p.label}
            </button>
          ))}
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 20 }}>
          <div>
            <label style={LABEL_STYLE}>📅 Date de début</label>
            <input type="date" value={declDateDeb}
              onChange={(e) => { setDeclDateDeb(e.target.value); setDeclPeriode("custom"); }}
              style={DATE_INPUT_STY} />
          </div>
          <div>
            <label style={LABEL_STYLE}>📅 Date de fin</label>
            <input type="date" value={declDateFin}
              onChange={(e) => { setDeclDateFin(e.target.value); setDeclPeriode("custom"); }}
              style={DATE_INPUT_STY} />
          </div>
        </div>
        {declDateDeb && declDateFin && (
          <div style={{ marginTop: 16, background: DARK, borderRadius: 10, padding: "12px 18px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <div style={{ fontSize: 13, color: "#8888bb" }}>Période sélectionnée</div>
            <div style={{ fontSize: 15, fontWeight: 800, color: GOLD, fontFamily: "monospace" }}>
              {new Date(declDateDeb).toLocaleDateString("fr-MA")} &nbsp;→&nbsp; {new Date(declDateFin).toLocaleDateString("fr-MA")}
            </div>
            <div style={{ fontSize: 12, color: "#5555aa" }}>Généré le {new Date().toLocaleDateString("fr-MA")}</div>
          </div>
        )}
      </div>

      {/* ── Cartes résumé ── */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 16, marginBottom: 24 }}>
        {[
          { icon: "💰", label: "Total Base HT",  val: fmt(totalHT)  + " DH", color: "#1e40af", bg: "#eff6ff" },
          { icon: "🏦", label: "TVA Collectée",  val: fmt(totalTVA) + " DH", color: "#92400e", bg: "#fffbeb" },
          { icon: "✅", label: "Total TTC",       val: fmt(totalTTC) + " DH", color: "#166534", bg: "#f0fdf4" },
        ].map((s) => (
          <div key={s.label} style={{ background: s.bg, borderRadius: 14, padding: "20px 24px", display: "flex", alignItems: "center", gap: 16, border: "1.5px solid " + s.color + "30" }}>
            <div style={{ fontSize: 32 }}>{s.icon}</div>
            <div>
              <div style={{ fontSize: 22, fontWeight: 900, color: s.color }}>{s.val}</div>
              <div style={{ fontSize: 12, color: "#6b7280", marginTop: 3, fontWeight: 600 }}>{s.label}</div>
            </div>
          </div>
        ))}
      </div>

      {/* ── Ventilation TVA ── */}
      {tvaRates.length > 1 && declFacts.length > 0 && (
        <div style={{ ...CARD, marginBottom: 24 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16 }}>
            <div style={{ background: GOLD + "20", borderRadius: 8, padding: "6px 10px", fontSize: 18 }}>🏦</div>
            <h3 style={{ margin: 0, fontSize: 15, fontWeight: 800, color: DARK }}>Ventilation par taux de TVA</h3>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: 12 }}>
            {tvaRates.map((r) => (
              <div key={r} style={{ background: "#fafaf8", border: "1.5px solid #e5e7eb", borderRadius: 10, padding: "14px 18px" }}>
                <div style={{ fontSize: 20, fontWeight: 900, color: GOLD, marginBottom: 8 }}>TVA {r}%</div>
                <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12, marginBottom: 4 }}>
                  <span style={{ color: "#6b7280" }}>Base HT</span>
                  <span style={{ fontWeight: 700, color: "#1e40af" }}>{fmt(tvaByRate[r].base)} DH</span>
                </div>
                <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12, marginBottom: 4 }}>
                  <span style={{ color: "#6b7280" }}>Montant TVA</span>
                  <span style={{ fontWeight: 700, color: "#92400e" }}>{fmt(tvaByRate[r].tva)} DH</span>
                </div>
                <div style={{ borderTop: "1px solid #e5e7eb", marginTop: 8, paddingTop: 8, display: "flex", justifyContent: "space-between", fontSize: 13 }}>
                  <span style={{ fontWeight: 600, color: "#374151" }}>TTC</span>
                  <span style={{ fontWeight: 900, color: "#166534" }}>{fmt(tvaByRate[r].base + tvaByRate[r].tva)} DH</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ── Tableau principal ── */}
      <div style={CARD}>
        {declFacts.length === 0 ? (
          <div style={{ textAlign: "center", padding: "70px 0", color: "#9ca3af" }}>
            <div style={{ fontSize: 52, marginBottom: 16 }}>📋</div>
            <div style={{ fontSize: 17, fontWeight: 700, marginBottom: 8, color: "#6b7280" }}>Aucune facture sur cette période</div>
            <div style={{ fontSize: 13 }}>Modifiez la plage de dates ci-dessus</div>
          </div>
        ) : (
          <>
            {/* Header tableau */}
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14, paddingBottom: 14, borderBottom: "2px solid #f0f0f0" }}>
              <div>
                <div style={{ fontSize: 15, fontWeight: 900, color: DARK }}>
                  Relevé de factures —&nbsp;
                  <span style={{ color: GOLD }}>{new Date(declDateDeb).toLocaleDateString("fr-MA")} → {new Date(declDateFin).toLocaleDateString("fr-MA")}</span>
                </div>
                <div style={{ fontSize: 12, color: "#6b7280", marginTop: 4 }}>
                  {declFacts.length} facture(s) &nbsp;·&nbsp; TVA à reverser :&nbsp;
                  <b style={{ color: "#92400e" }}>{fmt(totalTVA)} DH</b>
                  &nbsp;·&nbsp;
                  <span style={{ color: "#9ca3af", fontSize: 11 }}>↔ Glissez les séparateurs de colonnes pour redimensionner</span>
                </div>
              </div>
              {/* Légende tags */}
              <div style={{ display: "flex", gap: 6, flexWrap: "wrap", maxWidth: 340 }}>
                {customRowTags.map((t) => (
                  <div key={t.id} style={{ display: "flex", alignItems: "center", gap: 4, background: t.bg, border: "1px solid " + t.border, borderRadius: 20, padding: "2px 8px" }}>
                    <div style={{ width: 7, height: 7, borderRadius: "50%", background: t.dot }} />
                    <span style={{ fontSize: 10, fontWeight: 700, color: t.text }}>{t.label}</span>
                  </div>
                ))}
              </div>
            </div>

            {/* Table avec colonnes redimensionnables */}
            <div style={{ overflowX: "auto" }}>
              <table style={{ borderCollapse: "collapse", tableLayout: "fixed", width: COLS.reduce((s, c) => s + colWidths[c.key], 0) }}>
                <colgroup>
                  {COLS.map((c) => <col key={c.key} style={{ width: colWidths[c.key] }} />)}
                </colgroup>
                <thead>
                  <tr style={{ background: DARK }}>
                    {COLS.map((c) => (
                      <th key={c.key} style={{ position: "relative", padding: "11px 16px", textAlign: c.align, fontSize: 11, fontWeight: 700, color: "#ccc", textTransform: "uppercase", letterSpacing: "0.05em", borderRight: "1px solid #ffffff10", userSelect: "none", whiteSpace: "nowrap", overflow: "hidden" }}>
                        {c.label}
                        {/* Drag handle */}
                        <div style={HANDLE} onMouseDown={(e) => onResizeStart(c.key, e)} />
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {declFacts.map((f, i) => {
                    const ht  = f.lignes.reduce((s, l) => s + l.prixHT * l.qte, 0);
                    const tva = f.lignes.reduce((s, l) => s + l.prixHT * l.qte * l.tva / 100, 0);
                    const ttc = ht + tva;
                    const currentTag = customRowTags.find((t) => t.id === rowTags[f.id]);
                    const rowBg = currentTag ? currentTag.bg : (i % 2 === 0 ? "#fff" : "#fafaf8");
                    const rowBorder = currentTag ? "1.5px solid " + currentTag.border : "1px solid #f3f4f6";

                    return (
                      <tr key={f.id} style={{ background: rowBg, borderBottom: rowBorder, transition: "background .1s" }}
                        onMouseEnter={(e) => { if (!currentTag) e.currentTarget.style.background = GOLD + "0d"; }}
                        onMouseLeave={(e) => { if (!currentTag) e.currentTarget.style.background = rowBg; }}>

                        {/* Total TTC */}
                        <td style={{ padding: "12px 16px", textAlign: "right", fontWeight: 900, color: currentTag ? currentTag.text : "#166534", fontSize: 14, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                          {fmt(ttc)}
                        </td>

                        {/* N° Facture */}
                        <td style={{ padding: "12px 16px", fontWeight: 900, color: GOLD, fontFamily: "monospace", fontSize: 13, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                          {f.numero}
                        </td>

                        {/* TVA */}
                        <td style={{ padding: "12px 16px", textAlign: "right", fontWeight: 700, color: "#92400e", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                          {fmt(tva)}
                          {(() => {
                            const rates = [...new Set(f.lignes.map(l => l.tva))];
                            return rates.length > 0 ? <span style={{ fontSize: 10, color: "#b45309", marginLeft: 4, fontWeight: 600 }}>({rates.map(r => r + "%").join(", ")})</span> : null;
                          })()}
                        </td>

                        {/* Date */}
                        <td style={{ padding: "12px 16px", fontSize: 13, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                          {new Date(f.date).toLocaleDateString("fr-MA")}
                        </td>

                        {/* Tag */}
                        <td style={{ padding: "8px 10px", textAlign: "center", position: "relative" }}>
                          <div style={{ position: "relative", display: "inline-block" }}
                            onMouseDown={(e) => e.stopPropagation()}>
                            <button
                              onClick={(e) => { e.stopPropagation(); setTagOpen(tagOpen === f.id ? null : f.id); }}
                              style={{ display: "flex", alignItems: "center", gap: 5, padding: "4px 10px", borderRadius: 20, border: "1.5px solid " + (currentTag ? currentTag.border : "#d1d5db"), background: currentTag ? currentTag.bg : "#f9fafb", cursor: "pointer", fontSize: 11, fontWeight: 700, color: currentTag ? currentTag.text : "#6b7280", whiteSpace: "nowrap", transition: "all .15s" }}>
                              {currentTag
                                ? <><div style={{ width: 7, height: 7, borderRadius: "50%", background: currentTag.dot }} />{currentTag.label}</>
                                : <><span style={{ fontSize: 13 }}>＋</span> Tag</>
                              }
                            </button>

                            {/* Dropdown tag picker */}
                            {tagOpen === f.id && (
                              <div style={{ position: "absolute", top: "110%", left: "50%", transform: "translateX(-50%)", zIndex: 500, background: "#fff", border: "1px solid #e5e7eb", borderRadius: 12, boxShadow: "0 10px 30px #0003", padding: 8, minWidth: 150 }}>
                                {customRowTags.map((t) => (
                                  <div key={t.id}
                                    onClick={(e) => { e.stopPropagation(); setRowTags((prev) => ({ ...prev, [f.id]: t.id })); setTagOpen(null); }}
                                    style={{ display: "flex", alignItems: "center", gap: 8, padding: "7px 10px", borderRadius: 8, cursor: "pointer", background: rowTags[f.id] === t.id ? t.bg : "transparent", marginBottom: 2, transition: "background .1s" }}
                                    onMouseEnter={(e) => { if (rowTags[f.id] !== t.id) e.currentTarget.style.background = "#f3f4f6"; }}
                                    onMouseLeave={(e) => { e.currentTarget.style.background = rowTags[f.id] === t.id ? t.bg : "transparent"; }}>
                                    <div style={{ width: 10, height: 10, borderRadius: "50%", background: t.dot, flexShrink: 0 }} />
                                    <span style={{ fontSize: 12, fontWeight: 600, color: t.text }}>{t.label}</span>
                                    {rowTags[f.id] === t.id && <span style={{ marginLeft: "auto", fontSize: 11, color: t.text }}>✓</span>}
                                  </div>
                                ))}
                                {/* Supprimer le tag */}
                                {rowTags[f.id] && (
                                  <div
                                    onClick={(e) => { e.stopPropagation(); setRowTags((prev) => { const n = { ...prev }; delete n[f.id]; return n; }); setTagOpen(null); }}
                                    style={{ display: "flex", alignItems: "center", gap: 8, padding: "7px 10px", borderRadius: 8, cursor: "pointer", marginTop: 4, borderTop: "1px solid #f0f0f0", paddingTop: 8 }}
                                    onMouseEnter={(e) => e.currentTarget.style.background = "#fee2e2"}
                                    onMouseLeave={(e) => e.currentTarget.style.background = "transparent"}>
                                    <span style={{ fontSize: 12 }}>✕</span>
                                    <span style={{ fontSize: 12, fontWeight: 600, color: "#991b1b" }}>Retirer le tag</span>
                                  </div>
                                )}
                              </div>
                            )}
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </>
        )}
      </div>
    </>
  );
}

// ── Settings Page Component ───────────────────────────────────────────────────
function SettingsPage({ config, setConfig, factures, clients, logoUrl, setLogoUrl, logoRef, handleLogo, nextFNum, setPreviewFact, companyInfo, setCompanyInfo, dlDirHandle, chooseDlFolder, customCategories, setCustomCategories, allCategories }) {
  const [cfgDraft, setCfgDraft] = useState({ ...config });
  const [cfgSaved, setCfgSaved] = useState(false);
  const [numSearch, setNumSearch] = useState("");
  const [newCat, setNewCat] = useState("");

  const sep = cfgDraft.separateur !== undefined ? cfgDraft.separateur : "_";
  const previewNum = cfgDraft.prefixe + sep + padNum(cfgDraft.compteurDepart || 1, cfgDraft.digits || 5);
  const allNums = [...factures].sort((a, b) => (b.numero || "").localeCompare(a.numero || ""));
  const filteredNums = allNums.filter((f) =>
    !numSearch ||
    normalise(f.numero).includes(normalise(numSearch)) ||
    normalise(clients.find((c) => c.id === f.clientId)?.nom).includes(normalise(numSearch))
  );

  const saveConfig = () => {
    setConfig({ ...cfgDraft, digits: parseInt(cfgDraft.digits) || 5, compteurDepart: parseInt(cfgDraft.compteurDepart) || 1 });
    setCfgSaved(true);
    setTimeout(() => setCfgSaved(false), 2200);
  };

  return (
    <>
      <h1 style={{ margin: "0 0 28px", fontSize: 26, fontWeight: 900, color: DARK }}>Parametres</h1>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 24, alignItems: "start" }}>

        {/* ── Left column ── */}
        <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>

          {/* Logo */}
          <div style={CARD}>
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16, paddingBottom: 12, borderBottom: "1px solid #f0f0f0" }}>
              <div style={{ background: GOLD + "20", borderRadius: 8, padding: "7px 9px", fontSize: 18 }}>🖼</div>
              <h3 style={{ margin: 0, fontSize: 15, fontWeight: 800, color: DARK }}>Logo de l'entreprise</h3>
            </div>
            {logoUrl && (
              <div style={{ background: "#f8f6f0", border: "1px solid #e8dfc5", borderRadius: 10, padding: 16, marginBottom: 14, textAlign: "center" }}>
                <img src={logoUrl} alt="Logo" style={{ maxHeight: 90, maxWidth: 260, objectFit: "contain" }} />
              </div>
            )}
            <input ref={logoRef} type="file" accept="image/*" style={{ display: "none" }} onChange={handleLogo} />
            <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
              <button style={BTN_PRIMARY} onClick={() => logoRef.current?.click()}>
                {logoUrl ? "Changer le logo" : "Ajouter le logo"}
              </button>
              {logoUrl && <SmallBtn label="Supprimer" bg="#fee2e2" color="#991b1b" onClick={() => setLogoUrl(null)} />}
            </div>
            <p style={{ fontSize: 12, color: "#9ca3af", marginTop: 10, marginBottom: 0 }}>Apparait sur toutes vos factures imprimees.</p>
          </div>

          {/* ── Dossier de téléchargement PDF ── */}
          <div style={CARD}>
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16, paddingBottom: 12, borderBottom: "1px solid #f0f0f0" }}>
              <div style={{ background: GOLD + "20", borderRadius: 8, padding: "7px 9px", fontSize: 18 }}>📁</div>
              <h3 style={{ margin: 0, fontSize: 15, fontWeight: 800, color: DARK }}>Dossier de téléchargement PDF</h3>
            </div>

            {/* Dossier sélectionné */}
            <div style={{ background: dlDirHandle ? "#f0fdf4" : "#f8f8f6", border: "1px solid " + (dlDirHandle ? "#86efac" : "#e5e7eb"), borderRadius: 10, padding: "12px 16px", marginBottom: 14, display: "flex", alignItems: "center", gap: 12 }}>
              <span style={{ fontSize: 22 }}>{dlDirHandle ? "✅" : "📂"}</span>
              <div style={{ flex: 1 }}>
                <div style={{ fontSize: 12, fontWeight: 700, color: dlDirHandle ? "#166534" : "#6b7280", marginBottom: 2 }}>
                  {dlDirHandle ? "Dossier sélectionné" : "Aucun dossier défini"}
                </div>
                <div style={{ fontSize: 13, fontFamily: "monospace", color: dlDirHandle ? "#166534" : "#9ca3af", fontWeight: dlDirHandle ? 700 : 400 }}>
                  {dlDirHandle || "Cliquez pour choisir un dossier"}
                </div>
              </div>
            </div>

            <div style={{ display: "flex", gap: 10 }}>
              <button style={BTN_PRIMARY} onClick={chooseDlFolder}>
                📁 {dlDirHandle ? "Changer le dossier" : "Choisir le dossier"}
              </button>
            </div>

            <div style={{ marginTop: 12, background: "#fffbeb", border: "1px solid #fde68a", borderRadius: 8, padding: "10px 14px", fontSize: 11, color: "#92400e", lineHeight: 1.6 }}>
              <b>ℹ Note :</b> La sélection du dossier utilise l'API File System Access (Chrome/Edge).
              À chaque redémarrage de l'application, vous devrez re-confirmer l'accès au dossier en cliquant à nouveau.
              Si le dossier n'est pas sélectionné, les PDF seront téléchargés dans le dossier Téléchargements par défaut du navigateur.
            </div>
          </div>

          {/* Infos Societe */}
          <div style={CARD}>
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16, paddingBottom: 12, borderBottom: "1px solid #f0f0f0" }}>
              <div style={{ background: GOLD + "20", borderRadius: 8, padding: "7px 9px", fontSize: 18 }}>🏢</div>
              <h3 style={{ margin: 0, fontSize: 15, fontWeight: 800, color: DARK }}>Informations de l'entreprise</h3>
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0 14px" }}>
              {[
                { key: "nom",     label: "Nom / Raison Sociale", full: true  },
                { key: "adresse", label: "Adresse (pied de page)", full: true  },
                { key: "rc",      label: "RC",     full: false },
                { key: "if_",     label: "IF",     full: false },
                { key: "tp",      label: "TP",     full: false },
                { key: "ice",     label: "ICE",    full: false },
                { key: "email",   label: "Email",  full: true  },
              ].map((f) => (
                <div key={f.key} style={{ marginBottom: 12, gridColumn: f.full ? "1 / -1" : "auto" }}>
                  <label style={{ display: "block", fontSize: 11, fontWeight: 700, color: "#374151", marginBottom: 5, textTransform: "uppercase", letterSpacing: "0.05em" }}>{f.label}</label>
                  <input
                    value={companyInfo[f.key] || ""}
                    onChange={(e) => setCompanyInfo({ ...companyInfo, [f.key]: e.target.value })}
                    style={{ width: "100%", border: "1.5px solid #d1d5db", borderRadius: 8, padding: "8px 11px", fontSize: 13, outline: "none", boxSizing: "border-box", fontFamily: "inherit" }}
                  />
                </div>
              ))}
            </div>
            {/* Footer preview */}
            <div style={{ background: "#f8f6f0", border: "1px solid #e8dfc5", borderRadius: 8, padding: "9px 13px", fontSize: 10, color: "#555", textAlign: "center", lineHeight: 1.6, marginTop: 4 }}>
              <span style={{ fontWeight: 700, color: GOLD, fontSize: 10 }}>Apercu pied de page : </span>
              Siege : {companyInfo.adresse || "..."} – RC : {companyInfo.rc || "..."} – IF : {companyInfo.if_ || "..."} – TP : {companyInfo.tp || "..."} – ICE : {companyInfo.ice || "..."} – {companyInfo.email || "..."}
            </div>
          </div>

          {/* Numerotation Config */}
          <div style={CARD}>
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16, paddingBottom: 12, borderBottom: "1px solid #f0f0f0" }}>
              <div style={{ background: GOLD + "20", borderRadius: 8, padding: "7px 9px", fontSize: 18 }}>🔢</div>
              <h3 style={{ margin: 0, fontSize: 15, fontWeight: 800, color: DARK }}>Numerotation des factures</h3>
            </div>

            {/* Live preview */}
            <div style={{ background: DARK, borderRadius: 10, padding: "14px 18px", marginBottom: 18, display: "flex", alignItems: "center", justifyContent: "space-between" }}>
              <div>
                <div style={{ fontSize: 10, color: "#6666aa", textTransform: "uppercase", letterSpacing: 1, marginBottom: 4 }}>Apercu prochain numero</div>
                <div style={{ fontSize: 20, fontWeight: 900, color: GOLD, fontFamily: "monospace", letterSpacing: 2 }}>{previewNum}</div>
              </div>
              <div style={{ fontSize: 28 }}>🧾</div>
            </div>

            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0 16px" }}>
              <div style={{ marginBottom: 14 }}>
                <FieldLabel text="Prefixe" />
                <input value={cfgDraft.prefixe} onChange={(e) => setCfgDraft({ ...cfgDraft, prefixe: e.target.value })}
                  placeholder={"ex: " + CUR_YEAR + " ou FAC"}
                  style={{ width: "100%", border: "1.5px solid #d1d5db", borderRadius: 8, padding: "9px 12px", fontSize: 14, outline: "none", boxSizing: "border-box", fontFamily: "monospace", fontWeight: 700 }} />
                <div style={{ fontSize: 11, color: "#9ca3af", marginTop: 4 }}>Annee, code societe, etc.</div>
              </div>
              <div style={{ marginBottom: 14 }}>
                <FieldLabel text="Separateur" />
                <select value={cfgDraft.separateur} onChange={(e) => setCfgDraft({ ...cfgDraft, separateur: e.target.value })}
                  style={{ width: "100%", border: "1.5px solid #d1d5db", borderRadius: 8, padding: "9px 12px", fontSize: 14, outline: "none", boxSizing: "border-box", fontFamily: "monospace", fontWeight: 700, cursor: "pointer" }}>
                  <option value="_">Tiret bas  ( _ )</option>
                  <option value="-">Tiret      ( - )</option>
                  <option value="/">Slash      ( / )</option>
                  <option value="">Aucun</option>
                </select>
              </div>
              <div style={{ marginBottom: 14 }}>
                <FieldLabel text="Nb. de chiffres" />
                <select value={String(cfgDraft.digits)} onChange={(e) => setCfgDraft({ ...cfgDraft, digits: parseInt(e.target.value) })}
                  style={{ width: "100%", border: "1.5px solid #d1d5db", borderRadius: 8, padding: "9px 12px", fontSize: 14, outline: "none", boxSizing: "border-box", cursor: "pointer" }}>
                  {[3, 4, 5, 6].map((d) => <option key={d} value={d}>{d} chiffres — ex: {padNum(1, d)}</option>)}
                </select>
              </div>
              <div style={{ marginBottom: 14 }}>
                <FieldLabel text="Compteur de depart" />
                <input type="number" min="1" value={cfgDraft.compteurDepart}
                  onChange={(e) => setCfgDraft({ ...cfgDraft, compteurDepart: e.target.value })}
                  style={{ width: "100%", border: "1.5px solid #d1d5db", borderRadius: 8, padding: "9px 12px", fontSize: 14, outline: "none", boxSizing: "border-box" }} />
                <div style={{ fontSize: 11, color: "#9ca3af", marginTop: 4 }}>Si aucune facture existante.</div>
              </div>
            </div>

            {/* Format legend */}
            <div style={{ background: "#f8f6f0", border: "1px solid #e8dfc5", borderRadius: 8, padding: "10px 14px", marginBottom: 14, fontSize: 12 }}>
              <span style={{ color: GOLD, fontWeight: 700 }}>Format : </span>
              <span style={{ fontFamily: "monospace", color: "#1e40af", fontWeight: 700 }}>[PREFIXE]</span>
              <span style={{ color: "#6b7280" }}>{sep}</span>
              <span style={{ fontFamily: "monospace", color: "#166534", fontWeight: 700 }}>{"0".repeat(parseInt(cfgDraft.digits) || 5)}</span>
              <span style={{ color: "#9ca3af", marginLeft: 10 }}>→ {previewNum}</span>
            </div>

            <button onClick={saveConfig}
              style={{ ...BTN_PRIMARY, background: cfgSaved ? "#166534" : GOLD, transition: "background .3s", width: "100%", justifyContent: "center" }}>
              {cfgSaved ? "✓ Configuration sauvegardee !" : "Sauvegarder la configuration"}
            </button>
          </div>
        </div>

        {/* ── Right column : Registre ── */}
        <div style={CARD}>
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16, paddingBottom: 12, borderBottom: "1px solid #f0f0f0" }}>
            <div style={{ background: GOLD + "20", borderRadius: 8, padding: "7px 9px", fontSize: 18 }}>📋</div>
            <div style={{ flex: 1 }}>
              <h3 style={{ margin: 0, fontSize: 15, fontWeight: 800, color: DARK }}>Registre des numeros</h3>
              <div style={{ fontSize: 12, color: "#6b7280", marginTop: 2 }}>{factures.length} facture(s)</div>
            </div>
            <div style={{ background: GOLD, color: "#fff", borderRadius: 8, padding: "4px 12px", fontSize: 12, fontWeight: 700 }}>
              Prochain : {nextFNum()}
            </div>
          </div>

          <div style={{ position: "relative", marginBottom: 14 }}>
            <span style={{ position: "absolute", left: 11, top: "50%", transform: "translateY(-50%)", color: "#9ca3af", fontSize: 13 }}>🔍</span>
            <input value={numSearch} onChange={(e) => setNumSearch(e.target.value)}
              placeholder="Rechercher un numero ou client..."
              style={{ width: "100%", border: "1.5px solid #e5e7eb", borderRadius: 9, padding: "8px 12px 8px 34px", fontSize: 13, outline: "none", boxSizing: "border-box", fontFamily: "inherit" }} />
          </div>

          {factures.length === 0 ? (
            <div style={{ textAlign: "center", padding: "40px 0", color: "#9ca3af" }}>
              <div style={{ fontSize: 36, marginBottom: 10 }}>🧾</div>
              <div style={{ fontSize: 14 }}>Aucune facture creee</div>
              <div style={{ fontSize: 12, marginTop: 4 }}>Les numeros apparaitront ici</div>
            </div>
          ) : (
            <div style={{ maxHeight: 480, overflowY: "auto" }}>
              <div style={{ display: "grid", gridTemplateColumns: "auto 1fr auto", gap: "8px 12px", background: "#f9f9f7", borderRadius: 8, padding: "8px 12px", marginBottom: 8, fontSize: 11, fontWeight: 700, color: "#6b7280", textTransform: "uppercase", letterSpacing: "0.05em" }}>
                <span>N° Facture</span><span>Client</span><span>Total TTC</span>
              </div>
              {filteredNums.map((f, idx) => {
                const cl = clients.find((c) => c.id === f.clientId);
                const ttc = f.lignes.reduce((s, l) => s + l.prixHT * l.qte * (1 + l.tva / 100), 0);
                const isLast = idx === 0;
                return (
                  <div key={f.id}
                    style={{ display: "grid", gridTemplateColumns: "auto 1fr auto", gap: "6px 12px", alignItems: "center", padding: "9px 12px", borderRadius: 8, marginBottom: 4, background: isLast ? GOLD + "12" : "#fff", border: "1px solid " + (isLast ? GOLD + "40" : "#f0f0f0"), cursor: "pointer" }}
                    onMouseEnter={(e) => { if (!isLast) e.currentTarget.style.background = "#f9f9f7"; }}
                    onMouseLeave={(e) => { e.currentTarget.style.background = isLast ? GOLD + "12" : "#fff"; }}
                    onClick={() => setPreviewFact(f)}>
                    <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                      {isLast && <span style={{ fontSize: 9, background: GOLD, color: "#fff", borderRadius: 4, padding: "1px 5px", fontWeight: 700 }}>DERNIER</span>}
                      <span style={{ fontFamily: "monospace", fontWeight: 800, color: isLast ? GOLD : "#374151", fontSize: 13 }}>{f.numero}</span>
                    </div>
                    <div>
                      <div style={{ fontSize: 12, fontWeight: 600, color: "#374151" }}>{cl?.nom || "—"}</div>
                      <div style={{ fontSize: 10, color: "#9ca3af" }}>{new Date(f.date).toLocaleDateString("fr-MA")} · {cl?.id}</div>
                    </div>
                    <div style={{ textAlign: "right" }}>
                      <div style={{ fontSize: 12, fontWeight: 800, color: "#166534" }}>{fmt(ttc)} DH</div>
                      <div style={{ fontSize: 10, color: "#9ca3af" }}>TTC</div>
                    </div>
                  </div>
                );
              })}
              {filteredNums.length === 0 && <div style={{ textAlign: "center", padding: "20px 0", color: "#9ca3af", fontSize: 13 }}>Aucun resultat.</div>}
            </div>
          )}

          {factures.length > 0 && (
            <div style={{ marginTop: 14, paddingTop: 14, borderTop: "1px solid #f0f0f0", display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
              {[
                ["Premier numero", [...factures].sort((a, b) => (a.numero || "").localeCompare(b.numero || ""))[0]?.numero || "—"],
                ["Dernier numero", [...factures].sort((a, b) => (b.numero || "").localeCompare(a.numero || ""))[0]?.numero || "—"],
              ].map(([l, v]) => (
                <div key={l} style={{ background: "#f8f8f6", borderRadius: 8, padding: "8px 12px" }}>
                  <div style={{ fontSize: 10, color: "#9ca3af", marginBottom: 2 }}>{l}</div>
                  <div style={{ fontFamily: "monospace", fontWeight: 800, color: DARK, fontSize: 13 }}>{v}</div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* ── Catégories produits ── */}
      <div style={{ ...CARD, marginTop: 24 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 18, paddingBottom: 12, borderBottom: "1px solid #f0f0f0" }}>
          <div style={{ background: GOLD + "20", borderRadius: 8, padding: "7px 9px", fontSize: 18 }}>🏷️</div>
          <div style={{ flex: 1 }}>
            <h3 style={{ margin: 0, fontSize: 15, fontWeight: 800, color: DARK }}>Catégories de produits</h3>
            <div style={{ fontSize: 12, color: "#6b7280", marginTop: 2 }}>Gérez toutes les catégories disponibles lors de la création d'un produit</div>
          </div>
          <div style={{ background: GOLD + "18", border: "1.5px solid " + GOLD + "60", borderRadius: 10, padding: "5px 14px", fontSize: 12, fontWeight: 700, color: GOLD }}>
            {customCategories.length} catégorie(s)
          </div>
        </div>

        {/* All categories — all editable */}
        <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginBottom: 16 }}>
          {customCategories.length === 0 && (
            <div style={{ color: "#9ca3af", fontSize: 13, fontStyle: "italic" }}>Aucune catégorie. Ajoutez-en ci-dessous.</div>
          )}
          {customCategories.map((cat, idx) => {
            const cs = catStyle(cat);
            return (
              <span key={idx} style={{ display: "inline-flex", alignItems: "center", gap: 6, background: cs.bg, color: cs.color, borderRadius: 20, padding: "5px 10px 5px 14px", fontSize: 12, fontWeight: 700, border: "1.5px solid " + cs.color + "40" }}>
                {cat}
                <button
                  onClick={() => {
                    if (window.confirm(`Supprimer la catégorie "${cat}" ?`))
                      setCustomCategories(customCategories.filter((_, i) => i !== idx));
                  }}
                  title="Supprimer"
                  style={{ border: "none", background: cs.color + "22", color: cs.color, borderRadius: "50%", width: 18, height: 18, cursor: "pointer", fontSize: 11, display: "flex", alignItems: "center", justifyContent: "center", padding: 0, lineHeight: 1 }}>
                  ✕
                </button>
              </span>
            );
          })}
        </div>

        {/* Restore defaults button */}
        {customCategories.length === 0 && (
          <div style={{ marginBottom: 14 }}>
            <button
              onClick={() => setCustomCategories([...INITIAL_CATEGORIES])}
              style={{ ...BTN_SECONDARY, fontSize: 13 }}>
              ↩ Restaurer les catégories par défaut
            </button>
          </div>
        )}

        {/* Add new category */}
        <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
          <input
            value={newCat}
            onChange={(e) => setNewCat(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter" && newCat.trim()) {
                const trimmed = newCat.trim();
                if (customCategories.some((c) => c.toLowerCase() === trimmed.toLowerCase())) {
                  alert("Cette catégorie existe déjà."); return;
                }
                setCustomCategories([...customCategories, trimmed]);
                setNewCat("");
              }
            }}
            placeholder="Nouvelle catégorie... (ex: Matériaux, Location longue durée)"
            style={{ flex: 1, border: "1.5px solid #d1d5db", borderRadius: 8, padding: "9px 14px", fontSize: 13, outline: "none", fontFamily: "inherit" }}
          />
          <button
            onClick={() => {
              const trimmed = newCat.trim();
              if (!trimmed) return;
              if (customCategories.some((c) => c.toLowerCase() === trimmed.toLowerCase())) {
                alert("Cette catégorie existe déjà."); return;
              }
              setCustomCategories([...customCategories, trimmed]);
              setNewCat("");
            }}
            style={BTN_PRIMARY}>
            + Ajouter
          </button>
        </div>
        <div style={{ fontSize: 11, color: "#9ca3af", marginTop: 6 }}>Appuyez sur Entrée ou cliquez sur Ajouter pour créer une nouvelle catégorie. Cliquez sur ✕ pour supprimer une catégorie.</div>
      </div>

      {/* ── Backup / Restore ── */}
      <div style={{ ...CARD, marginTop: 24 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 18, paddingBottom: 12, borderBottom: "1px solid #f0f0f0" }}>
          <div style={{ background: GOLD + "20", borderRadius: 8, padding: "7px 9px", fontSize: 18 }}>💾</div>
          <div>
            <h3 style={{ margin: 0, fontSize: 15, fontWeight: 800, color: DARK }}>Sauvegarde et Restauration</h3>
            <div style={{ fontSize: 12, color: "#6b7280", marginTop: 2 }}>Exportez toutes vos données ou restaurez depuis un fichier de sauvegarde</div>
          </div>
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16 }}>
          <div style={{ background: "#f0fdf4", border: "1.5px solid #86efac", borderRadius: 12, padding: "18px 20px" }}>
            <div style={{ fontSize: 14, fontWeight: 800, color: "#166534", marginBottom: 8 }}>📤 Exporter les données</div>
            <div style={{ fontSize: 12, color: "#6b7280", marginBottom: 14 }}>
              Télécharge un fichier JSON contenant tous vos clients, produits et factures.
            </div>
            <button
              style={{ ...BTN_PRIMARY, background: "#166534", width: "100%", justifyContent: "center" }}
              onClick={() => {
                const data = {
                  exportDate: new Date().toISOString(),
                  version: "2.0",
                  clients: JSON.parse(localStorage.getItem("zkm_cl3") || "[]"),
                  products: JSON.parse(localStorage.getItem("zkm_pr3") || "[]"),
                  profils: JSON.parse(localStorage.getItem("zkm_profils") || "[]"),
                  allFactures: JSON.parse(localStorage.getItem("zkm_fa4_all") || "{}"),
                  profilActifId: JSON.parse(localStorage.getItem("zkm_profil_actif") || '"p1"'),
                };
                const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
                const url = URL.createObjectURL(blob);
                const a = document.createElement("a");
                a.href = url;
                a.download = "zkmaroc_backup_" + new Date().toISOString().split("T")[0] + ".json";
                a.click();
                URL.revokeObjectURL(url);
              }}>
              💾 Télécharger la sauvegarde
            </button>
          </div>
          <div style={{ background: "#eff6ff", border: "1.5px solid #93c5fd", borderRadius: 12, padding: "18px 20px" }}>
            <div style={{ fontSize: 14, fontWeight: 800, color: "#1e40af", marginBottom: 8 }}>📥 Restaurer les données</div>
            <div style={{ fontSize: 12, color: "#6b7280", marginBottom: 14 }}>
              ⚠️ Attention : la restauration remplacera toutes vos données actuelles.
            </div>
            <label style={{ ...BTN_PRIMARY, background: "#1d4ed8", width: "100%", justifyContent: "center", display: "flex", cursor: "pointer" }}>
              📂 Choisir un fichier .json
              <input type="file" accept=".json" style={{ display: "none" }}
                onChange={(e) => {
                  const file = e.target.files[0];
                  if (!file) return;
                  const reader = new FileReader();
                  reader.onload = (ev) => {
                    try {
                      const data = JSON.parse(ev.target.result);
                      if (!data.clients || !data.products) { alert("Fichier de sauvegarde invalide"); return; }
                      if (!window.confirm("Restaurer depuis ce fichier ? Toutes les données actuelles seront remplacées.")) return;
                      if (data.clients) localStorage.setItem("zkm_cl3", JSON.stringify(data.clients));
                      if (data.products) localStorage.setItem("zkm_pr3", JSON.stringify(data.products));
                      if (data.profils) localStorage.setItem("zkm_profils", JSON.stringify(data.profils));
                      if (data.allFactures) localStorage.setItem("zkm_fa4_all", JSON.stringify(data.allFactures));
                      if (data.profilActifId) localStorage.setItem("zkm_profil_actif", JSON.stringify(data.profilActifId));
                      alert("✅ Restauration réussie ! La page va se recharger.");
                      window.location.reload();
                    } catch { alert("Erreur lors de la lecture du fichier"); }
                  };
                  reader.readAsText(file);
                  e.target.value = "";
                }} />
            </label>
          </div>
        </div>
      </div>
    </>
  );
}

// ── Main App ─────────────────────────────────────────────────────────────────

// ── Calcul / Simulateur de Facture ──────────────────────────────────────────
function CalculPage({ products, onCreateFacture }) {
  const [targetTTC, setTargetTTC]    = useState("");
  const [search,    setSearch]       = useState("");
  const [catFilter, setCatFilter]    = useState("Tous");
  const [lines,     setLines]        = useState([]);
  const [showCatalog, setShowCatalog] = useState(false);
  const [pendingIds, setPendingIds]  = useState(new Set()); // multi-select
  const [created,   setCreated]      = useState(false);

  const cats = ["Tous", ...Array.from(new Set(products.map(p => p.categorie).filter(Boolean)))];

  const filteredProds = products.filter(p => {
    const ms = !search || normalise(p.description).includes(normalise(search)) || p.id.includes(search);
    const mc = catFilter === "Tous" || (p.categorie || "") === catFilter;
    return ms && mc;
  });

  const togglePending = (p) => {
    setPendingIds(prev => {
      const next = new Set(prev);
      if (next.has(p.id)) next.delete(p.id); else next.add(p.id);
      return next;
    });
  };

  const confirmSelection = () => {
    const toAdd = products.filter(p => pendingIds.has(p.id));
    setLines(prev => {
      let updated = [...prev];
      toAdd.forEach(p => {
        const idx = updated.findIndex(l => l.prod.id === p.id);
        if (idx >= 0) {
          updated[idx] = { ...updated[idx], qte: (parseFloat(updated[idx].qte) || 0) + 1 };
        } else {
          const ttc = p.prixHT * (1 + p.tva / 100);
          updated.push({ prod: p, qte: 1, prixHT: p.prixHT, inputMode: "HT", ttcInput: ttc.toFixed(4) });
        }
      });
      return updated;
    });
    setPendingIds(new Set());
    setShowCatalog(false);
    setSearch("");
  };

  const removeLine = (i) => setLines(prev => prev.filter((_, idx) => idx !== i));

  const updateLine = (i, field, val) => {
    setLines(prev => {
      const u = [...prev];
      if (field === "prixHT") {
        const ht = parseFloat(val) || 0;
        const ttc = ht * (1 + (u[i].prod.tva || 0) / 100);
        u[i] = { ...u[i], prixHT: val, ttcInput: ttc.toFixed(4) };
      } else if (field === "ttcInput") {
        const ttc = parseFloat(val) || 0;
        const ht  = u[i].prod.tva ? ttc / (1 + (u[i].prod.tva || 0) / 100) : ttc;
        u[i] = { ...u[i], ttcInput: val, prixHT: ht.toFixed(4) };
      } else {
        u[i] = { ...u[i], [field]: val };
      }
      return u;
    });
  };

  const toggleMode = (i) => {
    setLines(prev => {
      const u = [...prev];
      u[i] = { ...u[i], inputMode: u[i].inputMode === "HT" ? "TTC" : "HT" };
      return u;
    });
  };

  const totalHT  = lines.reduce((s, l) => s + (parseFloat(l.prixHT) || 0) * (parseFloat(l.qte) || 0), 0);
  const totalTVA = lines.reduce((s, l) => s + (parseFloat(l.prixHT) || 0) * (parseFloat(l.qte) || 0) * ((l.prod.tva || 0) / 100), 0);
  const totalTTC = totalHT + totalTVA;
  const target   = parseFloat(targetTTC) || 0;

  // ── FIX: compare rounded to 2 decimal places ──
  const totalTTCr = Math.round(totalTTC * 100) / 100;
  const targetR   = Math.round(target * 100) / 100;
  const diff      = target ? totalTTCr - targetR : null;
  const pct       = target ? Math.min((totalTTC / target) * 100, 100) : 0;
  const isExact   = diff !== null && diff === 0;

  const reset = () => { setLines([]); setTargetTTC(""); setCreated(false); };

  const barColor = diff === null ? GOLD : isExact ? "#16a34a" : diff > 0 ? "#dc2626" : GOLD;

  const handleCreateFacture = () => {
    if (!lines.length) return;
    const lignes = lines.map(l => ({
      ref: l.prod.id,
      description: l.prod.description,
      prixHT: parseFloat(l.prixHT) || 0,
      tva: l.prod.tva,
      qte: parseFloat(l.qte) || 1,
    }));
    onCreateFacture(lignes);
    setCreated(true);
    setTimeout(() => setCreated(false), 3000);
  };

  return (
    <>
      {/* Header */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 24 }}>
        <div>
          <h1 style={{ margin: 0, fontSize: 26, fontWeight: 900, color: DARK }}>🧮 Simulateur de Facture</h1>
          <div style={{ color: "#6b7280", fontSize: 14, marginTop: 4 }}>Composez vos produits et atteignez un total TTC précis</div>
        </div>
        <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
          {lines.length > 0 && (
            <button onClick={reset} style={BTN_SECONDARY}>🗑 Réinitialiser</button>
          )}
          <button onClick={() => { setShowCatalog(true); setPendingIds(new Set()); }} style={BTN_PRIMARY}>
            + Ajouter des produits
          </button>
        </div>
      </div>

      {/* Objectif + totaux */}
      <div style={{ ...CARD, marginBottom: 20, background: "linear-gradient(135deg, " + DARK + " 0%, #1e1e40 100%)", border: "none", padding: "22px 28px" }}>
        <div style={{ display: "flex", alignItems: "stretch", gap: 24, flexWrap: "wrap" }}>

          {/* Objectif */}
          <div style={{ flex: "0 0 260px" }}>
            <div style={{ fontSize: 11, fontWeight: 700, color: "#8888cc", textTransform: "uppercase", letterSpacing: "0.08em", marginBottom: 8 }}>🎯 Objectif Total TTC</div>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <input
                type="number"
                value={targetTTC}
                onChange={e => setTargetTTC(e.target.value)}
                placeholder="Ex: 100 000"
                style={{ flex: 1, background: "#ffffff14", border: "1.5px solid " + (target ? GOLD : "#ffffff22"), borderRadius: 10, padding: "11px 14px", fontSize: 17, fontWeight: 700, color: "#fff", outline: "none", fontFamily: "inherit" }}
              />
              <span style={{ color: "#8888cc", fontWeight: 700 }}>DH</span>
            </div>
          </div>

          <div style={{ width: 1, background: "#ffffff14", alignSelf: "stretch" }} />

          {/* Total actuel */}
          <div style={{ flex: 1, minWidth: 180 }}>
            <div style={{ fontSize: 11, fontWeight: 700, color: "#8888cc", textTransform: "uppercase", letterSpacing: "0.08em", marginBottom: 8 }}>💰 Total TTC Actuel</div>
            <div style={{ fontSize: 30, fontWeight: 900, color: barColor, letterSpacing: -1 }}>
              {fmt(totalTTC)} <span style={{ fontSize: 14, fontWeight: 600 }}>DH</span>
            </div>
            <div style={{ fontSize: 12, color: "#6688aa", marginTop: 4 }}>
              HT : {fmt(totalHT)} DH &nbsp;|&nbsp; TVA : {fmt(totalTVA)} DH
            </div>
          </div>

          {target > 0 && <div style={{ width: 1, background: "#ffffff14", alignSelf: "stretch" }} />}

          {/* Ecart */}
          {target > 0 && (
            <div style={{ flex: 1, minWidth: 180 }}>
              <div style={{ fontSize: 11, fontWeight: 700, color: "#8888cc", textTransform: "uppercase", letterSpacing: "0.08em", marginBottom: 8 }}>
                {isExact ? "✅ Objectif atteint !" : diff > 0 ? "⬆ Dépassement" : "⬇ Manque"}
              </div>
              <div style={{ fontSize: 26, fontWeight: 900, color: barColor }}>
                {isExact ? "Parfait !" : (diff > 0 ? "+" : "") + fmt(diff) + " DH"}
              </div>
              <div style={{ marginTop: 8, background: "#ffffff14", borderRadius: 6, height: 6, overflow: "hidden" }}>
                <div style={{ width: pct + "%", height: "100%", background: barColor, borderRadius: 6, transition: "width .4s ease" }} />
              </div>
              <div style={{ color: "#8888cc", fontSize: 11, marginTop: 4 }}>{pct.toFixed(1)}% de l'objectif</div>
            </div>
          )}
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 300px", gap: 20, alignItems: "start" }}>

        {/* ── Table des lignes ── */}
        <div style={CARD}>
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16, paddingBottom: 12, borderBottom: "1px solid #f0f0f0" }}>
            <span style={{ fontSize: 15, fontWeight: 800, color: DARK }}>📋 Liste des produits</span>
            <span style={{ marginLeft: "auto", background: GOLD + "20", color: GOLD, borderRadius: 20, padding: "2px 10px", fontSize: 12, fontWeight: 700 }}>{lines.length} produit(s)</span>
          </div>

          {lines.length === 0 ? (
            <div style={{ textAlign: "center", padding: "48px 24px", color: "#9ca3af" }}>
              <div style={{ fontSize: 48, marginBottom: 12 }}>🧮</div>
              <div style={{ fontSize: 14, fontWeight: 600, marginBottom: 6, color: "#6b7280" }}>Aucun produit ajouté</div>
              <div style={{ fontSize: 13, marginBottom: 18 }}>Cliquez ci-dessous pour ajouter des produits depuis votre stock</div>
              <button onClick={() => { setShowCatalog(true); setPendingIds(new Set()); }} style={BTN_PRIMARY}>+ Ajouter des produits</button>
            </div>
          ) : (
            <div style={{ overflowX: "auto" }}>
              <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
                <thead>
                  <tr style={{ background: "#f9f9f7" }}>
                    {["Réf", "Description", "TVA", "Prix unitaire", "Qté", "Montant HT", "Total TTC", ""].map((h, i) => (
                      <th key={i} style={{ padding: "9px 10px", textAlign: i >= 3 ? "right" : "left", fontSize: 10, fontWeight: 700, color: "#6b7280", textTransform: "uppercase", letterSpacing: "0.05em", whiteSpace: "nowrap", borderBottom: "1px solid #f0f0f0" }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {lines.map((l, i) => {
                    const ht  = (parseFloat(l.prixHT) || 0) * (parseFloat(l.qte) || 0);
                    const ttc = ht * (1 + (l.prod.tva || 0) / 100);
                    const isHT = l.inputMode === "HT";
                    return (
                      <tr key={i} style={{ borderBottom: "1px solid #f5f5f3" }}>
                        <td style={{ padding: "10px", color: "#9ca3af", fontFamily: "monospace", fontSize: 11, whiteSpace: "nowrap" }}>{l.prod.id}</td>
                        <td style={{ padding: "10px", fontWeight: 600, color: DARK, maxWidth: 180, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{l.prod.description}</td>
                        <td style={{ padding: "10px", color: "#6b7280", whiteSpace: "nowrap" }}>{l.prod.tva}%</td>
                        <td style={{ padding: "10px", textAlign: "right" }}>
                          <div style={{ display: "flex", flexDirection: "column", gap: 4, alignItems: "flex-end" }}>
                            <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                              <button onClick={() => toggleMode(i)}
                                style={{ fontSize: 10, fontWeight: 700, padding: "2px 7px", borderRadius: 20, border: "1.5px solid " + (isHT ? "#d1d5db" : "#86efac"), background: isHT ? "#f3f4f6" : "#f0fdf4", color: isHT ? "#6b7280" : "#166534", cursor: "pointer" }}>
                                {isHT ? "HT" : "TTC"}
                              </button>
                              <input
                                type="number"
                                value={isHT ? l.prixHT : l.ttcInput}
                                onChange={e => updateLine(i, isHT ? "prixHT" : "ttcInput", e.target.value)}
                                style={{ width: 100, textAlign: "right", border: "1.5px solid " + (isHT ? "#e5e7eb" : "#86efac"), borderRadius: 7, padding: "5px 8px", fontSize: 13, fontFamily: "inherit", outline: "none", background: isHT ? "#fff" : "#f0fdf4" }}
                              />
                            </div>
                            <div style={{ fontSize: 10, color: "#9ca3af" }}>
                              {isHT ? ("→ TTC: " + fmt(parseFloat(l.prixHT || 0) * (1 + l.prod.tva / 100)) + " DH") : ("→ HT: " + fmt(parseFloat(l.prixHT || 0)) + " DH")}
                            </div>
                          </div>
                        </td>
                        <td style={{ padding: "10px", textAlign: "right" }}>
                          <div style={{ display: "flex", alignItems: "center", justifyContent: "flex-end", gap: 3 }}>
                            <button onClick={() => updateLine(i, "qte", Math.max(0.01, (parseFloat(l.qte) || 1) - 1))}
                              style={{ width: 24, height: 24, border: "1.5px solid #e5e7eb", borderRadius: 5, background: "#f9fafb", cursor: "pointer", fontWeight: 700, color: DARK, fontSize: 13, lineHeight: 1 }}>−</button>
                            <input
                              type="number"
                              value={l.qte}
                              onChange={e => updateLine(i, "qte", e.target.value)}
                              style={{ width: 55, textAlign: "center", border: "1.5px solid #e5e7eb", borderRadius: 6, padding: "4px", fontSize: 13, fontFamily: "inherit", outline: "none" }}
                            />
                            <button onClick={() => updateLine(i, "qte", (parseFloat(l.qte) || 0) + 1)}
                              style={{ width: 24, height: 24, border: "1.5px solid #e5e7eb", borderRadius: 5, background: "#f9fafb", cursor: "pointer", fontWeight: 700, color: DARK, fontSize: 13, lineHeight: 1 }}>+</button>
                          </div>
                        </td>
                        <td style={{ padding: "10px", textAlign: "right", fontWeight: 600, color: DARK }}>{fmt(ht)}</td>
                        <td style={{ padding: "10px", textAlign: "right", fontWeight: 800, color: "#166534", fontSize: 14 }}>{fmt(ttc)}</td>
                        <td style={{ padding: "10px 8px" }}>
                          <button onClick={() => removeLine(i)}
                            style={{ background: "#fee2e2", border: "none", borderRadius: 6, width: 26, height: 26, cursor: "pointer", color: "#991b1b", fontWeight: 700, fontSize: 15, lineHeight: 1 }}>×</button>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>

              {lines.length > 0 && (
                <div style={{ marginTop: 16, paddingTop: 14, borderTop: "1px solid #f0f0f0", display: "flex", justifyContent: "flex-end", gap: 10 }}>
                  {created && (
                    <div style={{ display: "flex", alignItems: "center", gap: 6, color: "#166534", fontSize: 13, fontWeight: 600 }}>
                      ✅ Lignes chargées dans le formulaire !
                    </div>
                  )}
                  <button onClick={handleCreateFacture}
                    style={{ ...BTN_PRIMARY, background: "#166534", display: "flex", alignItems: "center", gap: 8 }}>
                    🧾 Créer une facture depuis ce calcul
                  </button>
                </div>
              )}
            </div>
          )}
        </div>

        {/* ── Récap ── */}
        <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
          <div style={CARD}>
            <div style={{ fontSize: 14, fontWeight: 800, color: DARK, marginBottom: 14, paddingBottom: 10, borderBottom: "1px solid #f0f0f0" }}>📊 Récapitulatif</div>
            {[
              { label: "Total HT",  val: fmt(totalHT)  + " DH", color: DARK,      sz: 14, fw: 600 },
              { label: "TVA",       val: fmt(totalTVA) + " DH", color: "#92400e", sz: 14, fw: 600 },
              { label: "Total TTC", val: fmt(totalTTC) + " DH", color: "#166534", sz: 18, fw: 900 },
            ].map(({ label, val, color, sz, fw }) => (
              <div key={label} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "8px 0", borderBottom: "1px solid #f5f5f3" }}>
                <span style={{ fontSize: 13, color: "#6b7280", fontWeight: 500 }}>{label}</span>
                <span style={{ fontSize: sz, fontWeight: fw, color }}>{val}</span>
              </div>
            ))}

            {target > 0 && (
              <div style={{ marginTop: 14, background: isExact ? "#f0fdf4" : diff > 0 ? "#fef2f2" : "#fffbeb", border: "1.5px solid " + (isExact ? "#86efac" : diff > 0 ? "#fca5a5" : "#fcd34d"), borderRadius: 10, padding: "12px 14px" }}>
                <div style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.06em", color: "#6b7280", marginBottom: 6 }}>
                  vs. Objectif {fmt(target)} DH
                </div>
                <div style={{ fontSize: 20, fontWeight: 900, color: barColor }}>
                  {isExact ? "✅ Parfait !" : (diff > 0 ? "+" : "") + fmt(diff) + " DH"}
                </div>
                {!isExact && (
                  <div style={{ fontSize: 12, color: "#6b7280", marginTop: 4 }}>
                    {diff < 0 ? `Il manque ${fmt(Math.abs(diff))} DH` : `Vous dépassez de ${fmt(diff)} DH`}
                  </div>
                )}
              </div>
            )}
          </div>

          {lines.length > 0 && target > 0 && diff !== null && !isExact && (
            <div style={{ ...CARD, background: "#fffbeb", border: "1px solid #fcd34d", padding: "14px 16px" }}>
              <div style={{ fontSize: 13, fontWeight: 700, color: "#92400e", marginBottom: 6 }}>💡 Astuce</div>
              <div style={{ fontSize: 12, color: "#78350f", lineHeight: 1.7 }}>
                {diff < 0
                  ? <>Il manque <b>{fmt(Math.abs(diff))} DH</b>.<br/>Augmentez les quantités ou ajoutez un produit.</>
                  : <>Dépassement de <b>{fmt(diff)} DH</b>.<br/>Réduisez les quantités ou les prix.</>
                }
              </div>
            </div>
          )}

          {lines.length > 0 && (() => {
            const groups = {};
            lines.forEach(l => {
              const r = l.prod.tva || 0;
              const ht = (parseFloat(l.prixHT) || 0) * (parseFloat(l.qte) || 0);
              if (!groups[r]) groups[r] = { base: 0, tva: 0 };
              groups[r].base += ht;
              groups[r].tva  += ht * r / 100;
            });
            const entries = Object.entries(groups).sort(([a],[b]) => parseFloat(b)-parseFloat(a));
            if (entries.length < 2) return null;
            return (
              <div style={CARD}>
                <div style={{ fontSize: 12, fontWeight: 700, color: "#374151", textTransform: "uppercase", letterSpacing: "0.06em", marginBottom: 10 }}>Détail par taux TVA</div>
                {entries.map(([rate, g]) => (
                  <div key={rate} style={{ display: "flex", justifyContent: "space-between", padding: "5px 0", borderBottom: "1px solid #f5f5f3", fontSize: 12, gap: 8 }}>
                    <span style={{ color: "#6b7280" }}>Base {rate}%</span>
                    <span style={{ fontWeight: 600 }}>{fmt(g.base)} DH</span>
                    <span style={{ color: "#92400e" }}>+{fmt(g.tva)} DH</span>
                  </div>
                ))}
              </div>
            );
          })()}
        </div>
      </div>

      {/* ── Modal catalogue multi-sélection ── */}
      {showCatalog && (
        <div style={{ position: "fixed", inset: 0, background: "#000000bb", zIndex: 3000, display: "flex", alignItems: "center", justifyContent: "center" }}>
          <div style={{ background: "#fff", borderRadius: 18, width: 680, maxWidth: "95vw", maxHeight: "88vh", display: "flex", flexDirection: "column", boxShadow: "0 20px 60px #00000040" }}>
            {/* Header */}
            <div style={{ padding: "20px 24px", borderBottom: "1px solid #f0f0f0", display: "flex", alignItems: "center", gap: 12 }}>
              <div style={{ background: GOLD + "20", borderRadius: 8, padding: "6px 9px", fontSize: 18 }}>📦</div>
              <h3 style={{ margin: 0, fontSize: 16, fontWeight: 800, color: DARK }}>Sélectionner des produits</h3>
              <div style={{ marginLeft: "auto", fontSize: 13, color: "#6b7280" }}>{products.length} en stock</div>
              <button onClick={() => { setShowCatalog(false); setPendingIds(new Set()); setSearch(""); }}
                style={{ background: "#f3f4f6", border: "none", borderRadius: 8, width: 32, height: 32, cursor: "pointer", fontSize: 16, color: "#6b7280", lineHeight: 1 }}>✕</button>
            </div>
            {/* Filtres */}
            <div style={{ padding: "12px 24px", borderBottom: "1px solid #f0f0f0", display: "flex", gap: 10 }}>
              <input autoFocus value={search} onChange={e => setSearch(e.target.value)}
                placeholder="Rechercher un produit..."
                style={{ flex: 1, border: "1.5px solid #d1d5db", borderRadius: 9, padding: "9px 14px", fontSize: 14, outline: "none", fontFamily: "inherit" }} />
              <select value={catFilter} onChange={e => setCatFilter(e.target.value)}
                style={{ border: "1.5px solid #d1d5db", borderRadius: 9, padding: "9px 12px", fontSize: 13, outline: "none", cursor: "pointer", fontFamily: "inherit", background: "#fff" }}>
                {cats.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>
            {/* Instructions multi-select */}
            <div style={{ padding: "8px 24px", background: "#fffbeb", borderBottom: "1px solid #fef3c7", display: "flex", alignItems: "center", gap: 8 }}>
              <span style={{ fontSize: 14 }}>💡</span>
              <span style={{ fontSize: 12, color: "#92400e" }}>Cliquez sur les produits pour les sélectionner, puis confirmez en bas.</span>
              {pendingIds.size > 0 && (
                <span style={{ marginLeft: "auto", background: GOLD, color: "#fff", borderRadius: 20, padding: "2px 10px", fontSize: 12, fontWeight: 700 }}>{pendingIds.size} sélectionné(s)</span>
              )}
            </div>
            {/* Liste */}
            <div style={{ flex: 1, overflowY: "auto" }}>
              {filteredProds.length === 0 ? (
                <div style={{ textAlign: "center", padding: 40, color: "#9ca3af" }}>Aucun produit trouvé</div>
              ) : filteredProds.map(p => {
                const isPending = pendingIds.has(p.id);
                return (
                  <div key={p.id} onClick={() => togglePending(p)}
                    style={{ display: "flex", alignItems: "center", gap: 14, padding: "12px 24px", cursor: "pointer", borderBottom: "1px solid #f5f5f3", transition: "background .1s", background: isPending ? GOLD + "12" : "transparent", borderLeft: isPending ? "3px solid " + GOLD : "3px solid transparent" }}>
                    {/* Checkbox visuelle */}
                    <div style={{ width: 20, height: 20, borderRadius: 6, border: "2px solid " + (isPending ? GOLD : "#d1d5db"), background: isPending ? GOLD : "#fff", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, transition: "all .15s" }}>
                      {isPending && <span style={{ color: "#fff", fontSize: 12, fontWeight: 900, lineHeight: 1 }}>✓</span>}
                    </div>
                    <div style={{ background: GOLD + "18", borderRadius: 8, padding: "5px 8px", fontSize: 11, fontWeight: 700, color: GOLD, fontFamily: "monospace", flexShrink: 0 }}>{p.id}</div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontWeight: 600, color: DARK, fontSize: 14, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{p.description}</div>
                      {p.categorie && <div style={{ fontSize: 11, color: "#9ca3af", marginTop: 2 }}>{p.categorie}</div>}
                    </div>
                    <div style={{ textAlign: "right", flexShrink: 0 }}>
                      <div style={{ fontWeight: 800, color: "#166534", fontSize: 14 }}>{fmt(p.prixHT * (1 + p.tva / 100))} DH TTC</div>
                      <div style={{ fontSize: 11, color: "#6b7280" }}>{fmt(p.prixHT)} HT · TVA {p.tva}%</div>
                    </div>
                  </div>
                );
              })}
            </div>
            {/* Footer confirm */}
            <div style={{ padding: "16px 24px", borderTop: "1px solid #f0f0f0", display: "flex", justifyContent: "space-between", alignItems: "center", background: "#fafaf8" }}>
              <div style={{ fontSize: 13, color: "#6b7280" }}>
                {pendingIds.size === 0 ? "Aucun produit sélectionné" : <><b style={{ color: DARK }}>{pendingIds.size} produit(s)</b> sélectionné(s)</>}
              </div>
              <div style={{ display: "flex", gap: 10 }}>
                <button onClick={() => { setShowCatalog(false); setPendingIds(new Set()); setSearch(""); }} style={BTN_SECONDARY}>Annuler</button>
                <button onClick={confirmSelection} disabled={pendingIds.size === 0}
                  style={{ ...BTN_PRIMARY, opacity: pendingIds.size === 0 ? 0.4 : 1 }}>
                  Ajouter {pendingIds.size > 0 ? pendingIds.size + " produit(s)" : ""}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

// ── Auth Context & Components ─────────────────────────────────────────────────

// Page de connexion
function LoginPage({ onLogin, error, loading }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPwd, setShowPwd] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!email.trim() || !password) return;
    onLogin(email.trim(), password);
  };

  return (
    <div style={{
      minHeight: "100vh", background: "#1a1a2e",
      display: "flex", alignItems: "center", justifyContent: "center",
      fontFamily: "'Segoe UI', system-ui, sans-serif",
    }}>
      <style>{`
        @keyframes fadeIn { from { opacity:0; transform:translateY(20px); } to { opacity:1; transform:translateY(0); } }
        .login-input:focus { border-color: #C8A84B !important; box-shadow: 0 0 0 3px #C8A84B22; outline: none; }
        .login-btn:hover { background: #b8943a !important; }
      `}</style>

      <div style={{
        background: "#252540", borderRadius: 20, padding: "48px 40px",
        width: "100%", maxWidth: 420, boxShadow: "0 24px 64px #00000088",
        animation: "fadeIn .4s ease",
      }}>
        {/* Logo */}
        <div style={{ textAlign: "center", marginBottom: 36 }}>
          <div style={{ fontSize: 44, marginBottom: 10 }}>⚡</div>
          <div style={{ color: "#C8A84B", fontSize: 24, fontWeight: 800, letterSpacing: 1 }}>ZK MAROC</div>
          <div style={{ color: "#8888bb", fontSize: 12, marginTop: 4, letterSpacing: 2, textTransform: "uppercase" }}>Invoice Manager</div>
        </div>

        <div style={{ color: "#ccccee", fontSize: 16, fontWeight: 700, marginBottom: 24, textAlign: "center" }}>
          Connectez-vous à votre compte
        </div>

        <form onSubmit={handleSubmit}>
          {/* Email */}
          <div style={{ marginBottom: 16 }}>
            <label style={{ display: "block", fontSize: 12, color: "#8888bb", fontWeight: 600, marginBottom: 7, textTransform: "uppercase", letterSpacing: 0.8 }}>
              Adresse e-mail
            </label>
            <input
              className="login-input"
              type="email"
              value={email}
              onChange={e => setEmail(e.target.value)}
              placeholder="exemple@zkmaroc.com"
              autoComplete="email"
              style={{
                width: "100%", padding: "12px 16px", background: "#1a1a2e",
                border: "1.5px solid #3a3a5a", borderRadius: 10, color: "#fff",
                fontSize: 14, boxSizing: "border-box", transition: "border .2s, box-shadow .2s",
                fontFamily: "inherit",
              }}
            />
          </div>

          {/* Mot de passe */}
          <div style={{ marginBottom: 24 }}>
            <label style={{ display: "block", fontSize: 12, color: "#8888bb", fontWeight: 600, marginBottom: 7, textTransform: "uppercase", letterSpacing: 0.8 }}>
              Mot de passe
            </label>
            <div style={{ position: "relative" }}>
              <input
                className="login-input"
                type={showPwd ? "text" : "password"}
                value={password}
                onChange={e => setPassword(e.target.value)}
                placeholder="••••••••"
                autoComplete="current-password"
                style={{
                  width: "100%", padding: "12px 44px 12px 16px", background: "#1a1a2e",
                  border: "1.5px solid #3a3a5a", borderRadius: 10, color: "#fff",
                  fontSize: 14, boxSizing: "border-box", transition: "border .2s, box-shadow .2s",
                  fontFamily: "inherit",
                }}
              />
              <button
                type="button"
                onClick={() => setShowPwd(p => !p)}
                style={{
                  position: "absolute", right: 12, top: "50%", transform: "translateY(-50%)",
                  background: "none", border: "none", cursor: "pointer",
                  color: "#6666aa", fontSize: 16, lineHeight: 1, padding: 4,
                }}
              >
                {showPwd ? "🙈" : "👁️"}
              </button>
            </div>
          </div>

          {/* Erreur */}
          {error && (
            <div style={{
              background: "#fee2e2", border: "1px solid #fca5a5", borderRadius: 10,
              padding: "10px 14px", marginBottom: 16, color: "#991b1b", fontSize: 13, fontWeight: 600,
            }}>
              ⚠️ {error}
            </div>
          )}

          {/* Bouton */}
          <button
            type="submit"
            className="login-btn"
            disabled={loading || !email || !password}
            style={{
              width: "100%", background: "#C8A84B", color: "#1a1a2e", border: "none",
              borderRadius: 10, padding: "13px", fontSize: 15, fontWeight: 800,
              cursor: loading || !email || !password ? "not-allowed" : "pointer",
              opacity: loading || !email || !password ? 0.7 : 1,
              transition: "background .2s", fontFamily: "inherit",
            }}
          >
            {loading ? "Connexion..." : "Se connecter"}
          </button>
        </form>

        <div style={{ textAlign: "center", marginTop: 24, color: "#555577", fontSize: 12 }}>
          Accès réservé aux utilisateurs autorisés
        </div>
      </div>
    </div>
  );
}

// Panel de gestion des utilisateurs (Admin uniquement)
function UsersPanel({ currentUser, onClose }) {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [form, setForm] = useState({ email: "", password: "", role: "lecture", nom: "" });
  const [creating, setCreating] = useState(false);
  const [createError, setCreateError] = useState("");
  const [createSuccess, setCreateSuccess] = useState("");
  const [showForm, setShowForm] = useState(false);

  const ROLES = [
    { id: "admin",            label: "Administrateur",       desc: "Accès total + gestion des utilisateurs",  color: "#991b1b", bg: "#fee2e2", icon: "👑" },
    { id: "ecriture_lecture", label: "Écriture & Lecture",   desc: "Peut créer, modifier, supprimer",          color: "#1e40af", bg: "#eff6ff", icon: "✏️" },
    { id: "lecture",          label: "Lecture seule",        desc: "Visualisation uniquement, sans modification", color: "#065f46", bg: "#d1fae5", icon: "👁️" },
  ];

  const loadUsers = async () => {
    setLoading(true);
    try {
      const snap = await getDocs(USERS_COL);
      const list = snap.docs.map(d => ({ id: d.id, ...d.data() }));
      setUsers(list.sort((a, b) => (a.email || "").localeCompare(b.email || "")));
    } catch (e) {
      console.error("Erreur chargement utilisateurs:", e);
    }
    setLoading(false);
  };

  useEffect(() => { loadUsers(); }, []);

  const createUser = async () => {
    setCreateError("");
    setCreateSuccess("");
    if (!form.email.trim() || !form.password || form.password.length < 6) {
      setCreateError("Email valide et mot de passe (6+ caractères) requis.");
      return;
    }
    setCreating(true);
    try {
      // Créer dans Firebase Auth via l'API Admin (via callable function ou directement)
      // On stocke dans Firestore les infos de rôle (l'UID sera l'email hashé en clé)
      const userId = btoa(form.email.trim().toLowerCase()).replace(/[^a-zA-Z0-9]/g, "_");
      await setDoc(doc(db, "zkm_users", userId), {
        email: form.email.trim().toLowerCase(),
        nom: form.nom.trim() || form.email.split("@")[0],
        role: form.role,
        createdAt: new Date().toISOString(),
        createdBy: currentUser.email,
        password: form.password, // stocké temporairement pour provisioning
      });
      setCreateSuccess("✅ Utilisateur créé avec succès !");
      setForm({ email: "", password: "", role: "lecture", nom: "" });
      setShowForm(false);
      loadUsers();
    } catch (e) {
      setCreateError("Erreur : " + e.message);
    }
    setCreating(false);
  };

  const updateRole = async (userId, newRole) => {
    try {
      await setDoc(doc(db, "zkm_users", userId), { role: newRole }, { merge: true });
      setUsers(prev => prev.map(u => u.id === userId ? { ...u, role: newRole } : u));
    } catch (e) {
      alert("Erreur lors de la mise à jour : " + e.message);
    }
  };

  const deleteUser = async (userId, userEmail) => {
    if (!window.confirm(`Supprimer l'accès de ${userEmail} ?`)) return;
    if (userEmail === currentUser.email) { alert("Vous ne pouvez pas supprimer votre propre compte."); return; }
    try {
      await deleteDoc(doc(db, "zkm_users", userId));
      setUsers(prev => prev.filter(u => u.id !== userId));
    } catch (e) {
      alert("Erreur : " + e.message);
    }
  };

  const getRoleBadge = (role) => {
    const r = ROLES.find(r => r.id === role) || ROLES[2];
    return (
      <span style={{ background: r.bg, color: r.color, border: "1px solid " + r.color + "40", borderRadius: 20, padding: "3px 10px", fontSize: 11, fontWeight: 700 }}>
        {r.icon} {r.label}
      </span>
    );
  };

  return (
    <div style={{
      position: "fixed", inset: 0, background: "#00000080", zIndex: 2000,
      display: "flex", alignItems: "center", justifyContent: "center",
      fontFamily: "'Segoe UI', system-ui, sans-serif",
    }}>
      <div style={{
        background: "#fff", borderRadius: 20, width: "100%", maxWidth: 780,
        maxHeight: "90vh", overflow: "hidden", display: "flex", flexDirection: "column",
        boxShadow: "0 24px 64px #00000050",
      }}>
        {/* Header */}
        <div style={{ padding: "24px 28px 20px", borderBottom: "1px solid #f0f0f0", display: "flex", alignItems: "center", gap: 12 }}>
          <div style={{ background: "#fee2e280", borderRadius: 10, padding: "8px 10px", fontSize: 20 }}>👥</div>
          <div>
            <h2 style={{ margin: 0, fontSize: 18, fontWeight: 800, color: "#1a1a2e" }}>Gestion des utilisateurs</h2>
            <div style={{ fontSize: 12, color: "#6b7280", marginTop: 2 }}>Créez et gérez les accès à l'application</div>
          </div>
          <div style={{ marginLeft: "auto", display: "flex", gap: 10 }}>
            <button
              onClick={() => { setShowForm(p => !p); setCreateError(""); setCreateSuccess(""); }}
              style={{ background: "#C8A84B", color: "#1a1a2e", border: "none", borderRadius: 10, padding: "9px 18px", cursor: "pointer", fontWeight: 700, fontSize: 13 }}>
              {showForm ? "Annuler" : "+ Nouvel utilisateur"}
            </button>
            <button onClick={onClose}
              style={{ background: "#f3f4f6", color: "#374151", border: "1px solid #e5e7eb", borderRadius: 10, padding: "9px 16px", cursor: "pointer", fontSize: 14 }}>
              ✕
            </button>
          </div>
        </div>

        <div style={{ flex: 1, overflowY: "auto", padding: "20px 28px" }}>

          {/* Formulaire création */}
          {showForm && (
            <div style={{ background: "#fffbeb", border: "1.5px solid #fde68a", borderRadius: 14, padding: "20px 24px", marginBottom: 20 }}>
              <div style={{ fontSize: 14, fontWeight: 800, color: "#92400e", marginBottom: 16 }}>➕ Créer un nouvel utilisateur</div>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14, marginBottom: 14 }}>
                <div>
                  <label style={{ display: "block", fontSize: 11, fontWeight: 700, color: "#6b7280", marginBottom: 5, textTransform: "uppercase" }}>Nom affiché</label>
                  <input value={form.nom} onChange={e => setForm(p => ({ ...p, nom: e.target.value }))}
                    placeholder="Ex: Ahmed Bennani"
                    style={{ width: "100%", padding: "10px 12px", border: "1.5px solid #d1d5db", borderRadius: 9, fontSize: 13, boxSizing: "border-box", fontFamily: "inherit", outline: "none" }} />
                </div>
                <div>
                  <label style={{ display: "block", fontSize: 11, fontWeight: 700, color: "#6b7280", marginBottom: 5, textTransform: "uppercase" }}>Adresse e-mail</label>
                  <input value={form.email} onChange={e => setForm(p => ({ ...p, email: e.target.value }))}
                    type="email" placeholder="utilisateur@zkmaroc.com"
                    style={{ width: "100%", padding: "10px 12px", border: "1.5px solid #d1d5db", borderRadius: 9, fontSize: 13, boxSizing: "border-box", fontFamily: "inherit", outline: "none" }} />
                </div>
                <div>
                  <label style={{ display: "block", fontSize: 11, fontWeight: 700, color: "#6b7280", marginBottom: 5, textTransform: "uppercase" }}>Mot de passe</label>
                  <input value={form.password} onChange={e => setForm(p => ({ ...p, password: e.target.value }))}
                    type="password" placeholder="Minimum 6 caractères"
                    style={{ width: "100%", padding: "10px 12px", border: "1.5px solid #d1d5db", borderRadius: 9, fontSize: 13, boxSizing: "border-box", fontFamily: "inherit", outline: "none" }} />
                </div>
                <div>
                  <label style={{ display: "block", fontSize: 11, fontWeight: 700, color: "#6b7280", marginBottom: 5, textTransform: "uppercase" }}>Rôle</label>
                  <select value={form.role} onChange={e => setForm(p => ({ ...p, role: e.target.value }))}
                    style={{ width: "100%", padding: "10px 12px", border: "1.5px solid #d1d5db", borderRadius: 9, fontSize: 13, boxSizing: "border-box", fontFamily: "inherit", outline: "none", background: "#fff", cursor: "pointer" }}>
                    {ROLES.map(r => <option key={r.id} value={r.id}>{r.icon} {r.label}</option>)}
                  </select>
                </div>
              </div>

              {/* Description du rôle */}
              {(() => { const r = ROLES.find(x => x.id === form.role); return r ? (
                <div style={{ background: r.bg, border: "1px solid " + r.color + "30", borderRadius: 8, padding: "8px 12px", marginBottom: 14, fontSize: 12, color: r.color }}>
                  {r.icon} <b>{r.label}</b> — {r.desc}
                </div>
              ) : null; })()}

              {createError && <div style={{ background: "#fee2e2", border: "1px solid #fca5a5", borderRadius: 8, padding: "8px 12px", marginBottom: 12, color: "#991b1b", fontSize: 12 }}>{createError}</div>}
              {createSuccess && <div style={{ background: "#d1fae5", border: "1px solid #6ee7b7", borderRadius: 8, padding: "8px 12px", marginBottom: 12, color: "#065f46", fontSize: 12 }}>{createSuccess}</div>}

              <button onClick={createUser} disabled={creating}
                style={{ background: "#1a1a2e", color: "#C8A84B", border: "none", borderRadius: 10, padding: "10px 22px", cursor: creating ? "not-allowed" : "pointer", fontWeight: 700, fontSize: 13, opacity: creating ? 0.7 : 1 }}>
                {creating ? "Création..." : "✓ Créer l'utilisateur"}
              </button>
            </div>
          )}

          {/* Liste des rôles */}
          <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 10, marginBottom: 20 }}>
            {ROLES.map(r => (
              <div key={r.id} style={{ background: r.bg, border: "1px solid " + r.color + "30", borderRadius: 12, padding: "12px 16px" }}>
                <div style={{ fontSize: 18, marginBottom: 4 }}>{r.icon}</div>
                <div style={{ fontSize: 13, fontWeight: 700, color: r.color }}>{r.label}</div>
                <div style={{ fontSize: 11, color: "#6b7280", marginTop: 3 }}>{r.desc}</div>
              </div>
            ))}
          </div>

          {/* Table utilisateurs */}
          {loading ? (
            <div style={{ textAlign: "center", padding: 40, color: "#9ca3af" }}>Chargement...</div>
          ) : users.length === 0 ? (
            <div style={{ textAlign: "center", padding: 40, color: "#9ca3af" }}>
              <div style={{ fontSize: 40, marginBottom: 12 }}>👤</div>
              Aucun utilisateur créé pour l'instant.
            </div>
          ) : (
            <div style={{ border: "1px solid #f0f0f0", borderRadius: 14, overflow: "hidden" }}>
              <table style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead>
                  <tr style={{ background: "#1a1a2e" }}>
                    {["Utilisateur", "E-mail", "Rôle", "Créé le", "Actions"].map(h => (
                      <th key={h} style={{ padding: "11px 16px", textAlign: "left", fontSize: 11, fontWeight: 700, color: "#8888bb", textTransform: "uppercase", letterSpacing: "0.05em" }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {users.map((u, i) => (
                    <tr key={u.id} style={{ background: i % 2 === 0 ? "#fff" : "#fafaf8", borderBottom: "1px solid #f3f4f6" }}>
                      <td style={{ padding: "12px 16px", fontWeight: 700, color: "#1a1a2e", fontSize: 14 }}>
                        {u.nom || u.email?.split("@")[0]}
                        {u.email === currentUser.email && <span style={{ marginLeft: 6, background: "#C8A84B20", color: "#C8A84B", borderRadius: 20, padding: "2px 8px", fontSize: 10, fontWeight: 700 }}>Vous</span>}
                      </td>
                      <td style={{ padding: "12px 16px", color: "#6b7280", fontSize: 13 }}>{u.email}</td>
                      <td style={{ padding: "12px 16px" }}>
                        {u.email === currentUser.email ? getRoleBadge(u.role) : (
                          <select
                            value={u.role}
                            onChange={e => updateRole(u.id, e.target.value)}
                            style={{ border: "1.5px solid #e5e7eb", borderRadius: 8, padding: "5px 10px", fontSize: 12, cursor: "pointer", fontFamily: "inherit", outline: "none", background: "#fff" }}>
                            {ROLES.map(r => <option key={r.id} value={r.id}>{r.icon} {r.label}</option>)}
                          </select>
                        )}
                      </td>
                      <td style={{ padding: "12px 16px", color: "#9ca3af", fontSize: 12 }}>
                        {u.createdAt ? new Date(u.createdAt).toLocaleDateString("fr-MA") : "—"}
                      </td>
                      <td style={{ padding: "12px 16px" }}>
                        {u.email !== currentUser.email && (
                          <button onClick={() => deleteUser(u.id, u.email)}
                            style={{ background: "#fee2e2", color: "#991b1b", border: "none", borderRadius: 8, padding: "6px 12px", cursor: "pointer", fontSize: 12, fontWeight: 600 }}>
                            🗑️ Supprimer
                          </button>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default function App() {
  const [page, setPage] = useState("factures");

  // ── Authentification ──────────────────────────────────────────────────────
  const [authUser, setAuthUser]       = useState(null);   // Firebase Auth user
  const [userRole, setUserRole]       = useState(null);   // "admin" | "ecriture_lecture" | "lecture"
  const [userName, setUserName]       = useState("");     // Nom affiché
  const [authReady, setAuthReady]     = useState(false);  // Firebase Auth initialisé
  const [loginError, setLoginError]   = useState("");
  const [loginLoading, setLoginLoading] = useState(false);
  const [showUsersPanel, setShowUsersPanel] = useState(false);

  // Écouter l'état de connexion Firebase
  useEffect(() => {
    const unsub = onAuthStateChanged(auth, async (user) => {
      if (user) {
        setAuthUser(user);
        // Chercher le rôle dans Firestore
        try {
          const userId = btoa(user.email.toLowerCase()).replace(/[^a-zA-Z0-9]/g, "_");
          const snap = await getDocs(USERS_COL);
          const found = snap.docs.map(d => ({ id: d.id, ...d.data() })).find(u => u.email === user.email.toLowerCase());
          if (found) {
            setUserRole(found.role || "lecture");
            setUserName(found.nom || user.email.split("@")[0]);
          } else {
            // Utilisateur Firebase mais sans fiche Firestore → lecture par défaut
            setUserRole("lecture");
            setUserName(user.email.split("@")[0]);
          }
        } catch {
          setUserRole("lecture");
          setUserName(user.email.split("@")[0]);
        }
      } else {
        setAuthUser(null);
        setUserRole(null);
        setUserName("");
      }
      setAuthReady(true);
    });
    return unsub;
  }, []);

  const handleLogin = async (email, password) => {
    setLoginLoading(true);
    setLoginError("");
    try {
      await signInWithEmailAndPassword(auth, email, password);
      // onAuthStateChanged s'occupera du reste
    } catch (e) {
      const msgs = {
        "auth/user-not-found":  "Aucun compte trouvé avec cet e-mail.",
        "auth/wrong-password":  "Mot de passe incorrect.",
        "auth/invalid-email":   "Adresse e-mail invalide.",
        "auth/too-many-requests": "Trop de tentatives. Réessayez plus tard.",
        "auth/invalid-credential": "E-mail ou mot de passe incorrect.",
      };
      setLoginError(msgs[e.code] || "Erreur de connexion. Vérifiez vos identifiants.");
    }
    setLoginLoading(false);
  };

  const handleLogout = () => {
    if (!window.confirm("Se déconnecter ?")) return;
    signOut(auth);
  };

  // Helpers de permission
  const canWrite = userRole === "admin" || userRole === "ecriture_lecture";
  const isAdmin  = userRole === "admin";

  // ── Écran de chargement Auth ──────────────────────────────────────────────
  if (!authReady) {
    return (
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", height: "100vh", background: "#1a1a2e", gap: 24 }}>
        <style>{`@keyframes zkm-slide { 0% { transform: translateX(-100%); } 100% { transform: translateX(280%); } }`}</style>
        <div style={{ textAlign: "center" }}>
          <div style={{ fontSize: 48, marginBottom: 8 }}>⚡</div>
          <div style={{ color: "#C8A84B", fontSize: 26, fontWeight: 800 }}>ZK MAROC</div>
        </div>
        <div style={{ width: 240, height: 5, background: "#2a2a4a", borderRadius: 3, overflow: "hidden", position: "relative" }}>
          <div style={{ width: "50%", height: "100%", background: "linear-gradient(90deg, transparent, #C8A84B, transparent)", borderRadius: 3, position: "absolute", animation: "zkm-slide 1.3s ease-in-out infinite" }} />
        </div>
      </div>
    );
  }

  // ── Page de connexion si non connecté ─────────────────────────────────────
  if (!authUser) {
    return <LoginPage onLogin={handleLogin} error={loginError} loading={loginLoading} />;
  }

  // ── Chargement Firestore : on attend la 1ère réponse avant d'afficher l'app ──
  // Si localStorage a déjà des données → pas besoin d'attendre
  const [firestoreReady, setFirestoreReady] = useState(
    () => !!localStorage.getItem("zkm_fa4_all") || !!localStorage.getItem("zkm_profils")
  );

  useEffect(() => {
    if (firestoreReady) return; // déjà prêt via cache local
    const unsub = onSnapshot(DATA_DOC, (snap) => {
      setFirestoreReady(true); // Firestore a répondu → on affiche
    });
    // Fallback 5s : si Firestore ne répond pas, on affiche quand même
    const timer = setTimeout(() => setFirestoreReady(true), 5000);
    return () => { unsub(); clearTimeout(timer); };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  // ── Multi-profils ─────────────────────────────────────────────────────────
  const [profils, setProfils] = useStorage("zkm_profils", DEFAULT_PROFILS);
  const [profilActifId, setProfilActifId] = useLocalStorage("zkm_profil_actif", "p1"); // local: chaque PC garde son propre profil actif
  const [showProfilMenu, setShowProfilMenu] = useState(false);
  const [editProfilModal, setEditProfilModal] = useState(null);
  const profilRef = useRef(null);

  // ── Migration: mise à jour automatique des profils p2/p3/p4 si encore aux valeurs par défaut ──
  useEffect(() => {
    setProfils(prev => prev.map(p => {
      const def = DEFAULT_PROFILS.find(d => d.id === p.id);
      if (!def) return p;
      // Si le nom est encore "Entreprise X" (jamais personnalisé), on force les nouvelles valeurs
      if (p.nom === "Entreprise 2" || p.nom === "Entreprise 3" || p.nom === "Entreprise 4") {
        return { ...p, nom: def.nom, couleur: def.couleur, companyInfo: def.companyInfo };
      }
      return p;
    }));
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    const h = (e) => { if (profilRef.current && !profilRef.current.contains(e.target)) setShowProfilMenu(false); };
    document.addEventListener("mousedown", h);
    return () => document.removeEventListener("mousedown", h);
  }, []);

  const profilActif = profils.find(p => p.id === profilActifId) || profils[0];

  // Helpers profil actif
  const companyInfo = profilActif?.companyInfo || {};
  const setCompanyInfo = (val) => setProfils(prev => prev.map(p => p.id === profilActif.id ? { ...p, companyInfo: val } : p));
  const logoUrl = profilActif?.logoUrl || null;
  const setLogoUrl = (val) => setProfils(prev => prev.map(p => p.id === profilActif.id ? { ...p, logoUrl: val } : p));
  const config = profilActif?.config || { prefixe: String(CUR_YEAR), separateur: "_", digits: 5, compteurDepart: 1 };
  const setConfig = (val) => setProfils(prev => prev.map(p => p.id === profilActif.id ? { ...p, config: val } : p));

  // Factures séparées par profil
  const [allFactures, setAllFactures] = useStorage("zkm_fa4_all", {});
  const factures = allFactures[profilActif?.id] || [];
  const setFactures = (valOrFn) => {
    setAllFactures(prev => {
      const current = prev[profilActif.id] || [];
      const next = typeof valOrFn === "function" ? valOrFn(current) : valOrFn;
      return { ...prev, [profilActif.id]: next };
    });
  };

  // ── Données partagées (clients + produits) ────────────────────────────────
  const [clients, setClients] = useStorage("zkm_cl3", INIT_CLIENTS);
  const [products, setProducts] = useStorage("zkm_pr3", INIT_PRODUCTS);
  const [previewFact, setPreviewFact] = useState(null);
  const [allFactTags, setAllFactTags] = useStorage("zkm_factTags4", {});
  const factTags = allFactTags[profilActif?.id] || {};
  const setFactTags = (valOrFn) => setAllFactTags(prev => { const current = prev[profilActif.id] || {}; const next = typeof valOrFn === "function" ? valOrFn(current) : valOrFn; return { ...prev, [profilActif.id]: next }; });
  const [editingFact, setEditingFact] = useState(null); // id of facture being edited
  const [clientsPerPage, setClientsPerPage] = useLocalStorage("zkm_cPP", 10); // local: préférence par appareil
  const [prodsPerPage, setProdsPerPage] = useLocalStorage("zkm_pPP", 10); // local: préférence par appareil
  const [customRowTags, setCustomRowTags] = useStorage("zkm_rowTags", DEFAULT_ROW_TAGS);
  const [customCategories, setCustomCategories] = useStorage("zkm_cats", INITIAL_CATEGORIES);
  const allCategories = customCategories;
  // Client column visibility
  const ALL_CLIENT_COLS = ["ID", "Nom / Raison Sociale", "ICE", "Adresse", "Ville", "Telephone", "Email"];
  const [visibleClientCols, setVisibleClientCols] = useLocalStorage("zkm_clCols", ALL_CLIENT_COLS); // local: préférence par appareil
  const [showClientColMenu, setShowClientColMenu] = useState(false);
  const clientColMenuRef = useRef(null);
  useEffect(() => {
    const h = (e) => { if (clientColMenuRef.current && !clientColMenuRef.current.contains(e.target)) setShowClientColMenu(false); };
    document.addEventListener("mousedown", h);
    return () => document.removeEventListener("mousedown", h);
  }, []);
  const [importModal, setImportModal] = useState(null);
  const [dlStatus, setDlStatus] = useState(null); // null | "generating" | "done" | "error"
  const [dlFact, setDlFact] = useState(null);     // facture en cours de capture PDF
  const [dlDirNames, setDlDirNames] = useLocalStorage("zkm_dldir_names", {}); // local: chemin propre à chaque PC
  const dlDirHandle = dlDirNames[profilActif?.id] || "";
  const dirHandlesRef = useRef({});  // { profilId: FileSystemDirectoryHandle }
  const dlContainerRef = useRef(null);             // ref vers le div caché dans le DOM

  // ── Colonnes visibles ────────────────────────────────────────────────────────
  const ALL_COLS = ["N° Facture", "Client", "Date", "Total HT", "TVA", "Total TTC", "Reglement", "Statut", "Actions"];
  const [visibleCols, setVisibleCols] = useLocalStorage("zkm_cols", ["N° Facture", "Client", "Date", "Total HT", "TVA", "Total TTC", "Reglement", "Statut"]); // local: préférence par appareil
  const [showColMenu, setShowColMenu] = useState(false);
  const colMenuRef = useRef(null);
  useEffect(() => {
    const h = (e) => { if (colMenuRef.current && !colMenuRef.current.contains(e.target)) setShowColMenu(false); };
    document.addEventListener("mousedown", h);
    return () => document.removeEventListener("mousedown", h);
  }, []);

  // ── Téléchargement PDF — déclenché après rendu du div caché ──────────────────
  const dlFileNameRef = useRef("");

  const downloadPDF = (f) => {
    const cl = clients.find((c) => c.id === f.clientId);
    dlFileNameRef.current = (f.numero + "_" + (cl?.nom || "Client"))
      .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
      .replace(/[^a-zA-Z0-9_\-]/g, "_")
      .replace(/_+/g, "_") + ".pdf";
    setDlStatus("generating");
    setDlFact(f); // provoque le rendu du div caché, puis useEffect capture
  };

  useEffect(() => {
    if (!dlFact || !dlContainerRef.current) return;
    const fileName = dlFileNameRef.current;

    const capture = async () => {
      // Attendre que le rendu React soit complet
      await new Promise((r) => setTimeout(r, 700));
      const el = dlContainerRef.current.querySelector("#invoice-doc") || dlContainerRef.current.firstChild;
      if (!el) { setDlStatus("error"); setDlFact(null); return; }

      try {
        const canvas = await html2canvas(el, {
          scale: 2,
          useCORS: true,
          allowTaint: true,
          backgroundColor: "#ffffff",
          width: 794,
          height: 1123,
          logging: false,
        });

        const imgData = canvas.toDataURL("image/jpeg", 0.95);
        const pdf = new jsPDF({ orientation: "portrait", unit: "mm", format: "a4" });
        pdf.addImage(imgData, "JPEG", 0, 0, 210, 297);

        // Electron: sauvegarde directe via IPC (chemin complet persisté)
        const activeFolderPath = dlDirNames[profilActif?.id];
        if (window.electronAPI?.savePDF && activeFolderPath) {
          const base64Data = pdf.output("datauristring").split(",")[1];
          const result = await window.electronAPI.savePDF({ folderPath: activeFolderPath, fileName, base64Data });
          if (result.success) {
            setDlStatus("done");
            setTimeout(() => setDlStatus(null), 3000);
            setDlFact(null);
            return;
          } else {
            console.warn("Electron savePDF échoué:", result.error);
          }
        }

        // Dossier personnalisé via File System Access API (Web)
        const activeDirHandle = dirHandlesRef.current[profilActif?.id];
        if (activeDirHandle) {
          try {
            const fileHandle = await activeDirHandle.getFileHandle(fileName, { create: true });
            const writable = await fileHandle.createWritable();
            await writable.write(pdf.output("blob"));
            await writable.close();
            setDlStatus("done");
            setTimeout(() => setDlStatus(null), 3000);
            setDlFact(null);
            return;
          } catch (e) {
            console.warn("Écriture dossier échouée, fallback", e);
          }
        }

        // Fallback téléchargement navigateur
        pdf.save(fileName);
        setDlStatus("done");
        setTimeout(() => setDlStatus(null), 3000);
      } catch (err) {
        console.error("Erreur PDF:", err);
        setDlStatus("error");
        setTimeout(() => setDlStatus(null), 4000);
      } finally {
        setDlFact(null);
      }
    };

    capture();
  }, [dlFact]);

  const chooseDlFolder = async () => {
    try {
      // Electron: utilise le dialog natif et retourne le chemin complet
      if (window.electronAPI?.chooseFolder) {
        const folderPath = await window.electronAPI.chooseFolder();
        if (!folderPath) return;
        const pid = profilActif?.id;
        setDlDirNames(prev => ({ ...prev, [pid]: folderPath }));
        return;
      }
      // Fallback Web: File System Access API
      const handle = await window.showDirectoryPicker({ mode: "readwrite" });
      const pid = profilActif?.id;
      dirHandlesRef.current[pid] = handle;
      setDlDirNames(prev => ({ ...prev, [pid]: handle.name }));
    } catch (e) {
      if (e.name !== "AbortError") alert("Impossible d'accéder au dossier : " + e.message);
    }
  };

  // ── Clients ──────────────────────────────────────────────────────────────────
  const [clientModal, setClientModal] = useState(null);
  const [clientSearch, setClientSearch] = useState("");
  const [clientPage, setClientPage] = useState(1);
  const [cForm, setCForm] = useState({ id: "", type: "", nom: "", ice: "", adresse: "", ville: "", tel: "", email: "" });
  const filteredClients = clients.filter((c) =>
    !clientSearch || normalise(c.nom).includes(normalise(clientSearch)) || (c.ice || "").includes(clientSearch) || c.id.includes(clientSearch)
  );
  const pagedClients = filteredClients.slice((clientPage - 1) * clientsPerPage, clientPage * clientsPerPage);
  const nextCId = () => { const ns = clients.map((c) => parseInt(c.id.replace("C", ""))).filter(Boolean); return "C" + padNum(Math.max(0, ...ns) + 1); };
  const saveClient = () => {
    if (!cForm.nom.trim()) { alert("Le nom est obligatoire"); return; }
    if (clientModal === "add") setClients([...clients, { ...cForm, id: nextCId() }]);
    else setClients(clients.map((c) => (c.id === cForm.id ? cForm : c)));
    setClientModal(null);
  };

  // ── Products ─────────────────────────────────────────────────────────────────
  const [prodModal, setProdModal] = useState(null);
  const [prodSearch, setProdSearch] = useState("");
  const [prodPage, setProdPage] = useState(1);
  const [prodCatFilter, setProdCatFilter] = useState("Tous");
  const [pForm, setPForm] = useState({ id: "", description: "", prixHT: "", tva: 20, categorie: "" });
  const [pFormTTC, setPFormTTC] = useState("");
  const filteredProds = products.filter((p) => {
    const matchSearch = !prodSearch || normalise(p.description).includes(normalise(prodSearch)) || p.id.includes(prodSearch);
    const matchCat = prodCatFilter === "Tous" || (p.categorie || "") === prodCatFilter;
    return matchSearch && matchCat;
  });
  const pagedProds = filteredProds.slice((prodPage - 1) * prodsPerPage, prodPage * prodsPerPage);
  const nextPId = () => { const ns = products.map((p) => parseInt(p.id.replace("P", ""))).filter(Boolean); return "P" + padNum(Math.max(0, ...ns) + 1); };
  const saveProd = () => {
    if (!pForm.prixHT) { alert("Le prix HT est obligatoire"); return; }
    const p = { ...pForm, prixHT: parseFloat(pForm.prixHT), tva: parseFloat(pForm.tva) };
    if (prodModal === "add") setProducts([...products, { ...p, id: nextPId() }]);
    else setProducts(products.map((pr) => (pr.id === pForm.id ? p : pr)));
    setProdModal(null);
  };

  const handleImport = (items, mode) => {
    if (importModal === "clients") {
      const base = mode === "replace" ? [] : clients;
      const existing = new Set(base.map((c) => c.nom?.toLowerCase()));
      const maxNum = base.map((c) => parseInt(c.id?.replace("C","") || 0)).filter(Boolean);
      let counter = maxNum.length ? Math.max(...maxNum) + 1 : 1;
      const newItems = items
        .filter((item) => mode === "replace" || !existing.has(item.nom?.toLowerCase()))
        .map((item) => ({ ...item, id: "C" + padNum(counter++) }));
      setClients(mode === "replace" ? newItems : [...base, ...newItems]);
    } else {
      const base = mode === "replace" ? [] : products;
      const maxNum = base.map((p) => parseInt(p.id?.replace("P","") || 0)).filter(Boolean);
      let counter = maxNum.length ? Math.max(...maxNum) + 1 : 1;
      const newItems = items.map((item) => ({ ...item, id: "P" + padNum(counter++) }));
      setProducts(mode === "replace" ? newItems : [...base, ...newItems]);
      // Auto-register new categories from imported products
      const importedCats = [...new Set(items.map((i) => i.categorie?.trim()).filter(Boolean))];
      if (importedCats.length > 0) {
        setCustomCategories((prev) => {
          const existingSet = new Set(prev.map((c) => c.toLowerCase()));
          const toAdd = importedCats.filter((c) => !existingSet.has(c.toLowerCase()));
          return toAdd.length > 0 ? [...prev, ...toAdd] : prev;
        });
      }
    }
  };

  // ── Factures ─────────────────────────────────────────────────────────────────
  const [factModal, setFactModal] = useState(false);
  const [simulatorLines, setSimulatorLines] = useState(null);
  const [factSearch, setFactSearch] = useState("");
  const [factPage, setFactPage] = useState(1);
  const [fForm, setFForm] = useState({ numero: "", date: todayStr(), clientId: "", reglement: "virement", lignes: [] });
  const [selProd, setSelProd] = useState("");
  const [prodQte, setProdQte] = useState(1);
  const [cSearch, setCSearch] = useState("");
  const [pSearch, setPSearch] = useState("");
  const [showCDD, setShowCDD] = useState(false);
  const [showPDD, setShowPDD] = useState(false);
  const cDDRef = useRef(null);
  const pDDRef = useRef(null);

  useEffect(() => {
    const h = (e) => {
      if (cDDRef.current && !cDDRef.current.contains(e.target)) setShowCDD(false);
      if (pDDRef.current && !pDDRef.current.contains(e.target)) setShowPDD(false);
    };
    document.addEventListener("mousedown", h);
    return () => document.removeEventListener("mousedown", h);
  }, []);

  const filteredFacts = factures.filter((f) =>
    !factSearch || (f.numero || "").includes(factSearch) || normalise(clients.find((c) => c.id === f.clientId)?.nom).includes(normalise(factSearch))
  );
  const pagedFacts = filteredFacts.slice((factPage - 1) * PER_PAGE, factPage * PER_PAGE);

  const buildNum = (seq) => config.prefixe + config.separateur + padNum(seq, config.digits);
  const nextFNum = () => {
    const sep = config.separateur;
    const ns = factures.map((f) => {
      const parts = (f.numero || "").split(sep);
      return parseInt(parts[parts.length - 1] || 0);
    }).filter(Boolean);
    const maxExisting = ns.length ? Math.max(...ns) : 0;
    const startFrom = Math.max(maxExisting + 1, config.compteurDepart || 1);
    // Find first unused number (skip gaps that might already be taken)
    const existingNums = new Set(factures.map((f) => f.numero));
    let seq = startFrom;
    while (existingNums.has(buildNum(seq))) seq++;
    return buildNum(seq);
  };

  const openNewFact = () => {
    setFForm({ numero: nextFNum(), date: todayStr(), clientId: "", reglement: "virement", lignes: [] });
    setCSearch(""); setPSearch(""); setSelProd(""); setProdQte(1); setShowCDD(false); setShowPDD(false);
    setEditingFact(null);
    setFactModal(true);
  };

  const openFromSimulator = (lignes) => {
    setFForm({ numero: nextFNum(), date: todayStr(), clientId: "", reglement: "virement", lignes });
    setCSearch(""); setPSearch(""); setSelProd(""); setProdQte(1); setShowCDD(false); setShowPDD(false);
    setEditingFact(null);
    setSimulatorLines(lignes);
    setFactModal(true);
    setPage("factures");
  };

  const addLine = () => {
    const p = products.find((x) => x.id === selProd);
    if (!p) return;
    const idx = fForm.lignes.findIndex((l) => l.ref === p.id);
    if (idx >= 0) {
      const u = [...fForm.lignes];
      u[idx] = { ...u[idx], qte: u[idx].qte + prodQte };
      setFForm({ ...fForm, lignes: u });
    } else {
      setFForm({ ...fForm, lignes: [...fForm.lignes, { ref: p.id, description: p.description, prixHT: p.prixHT, tva: p.tva, qte: prodQte }] });
    }
    setSelProd(""); setPSearch(""); setProdQte(1); setShowPDD(false);
  };

  const saveFact = () => {
    if (!fForm.numero.trim()) { alert("Le numéro de facture est obligatoire"); return; }
    if (!fForm.clientId) { alert("Veuillez selectionner un client"); return; }
    if (!fForm.lignes.length) { alert("Ajoutez au moins un produit"); return; }
    const isDuplicate = factures.some((f) =>
      f.numero.trim() === fForm.numero.trim() && f.id !== editingFact
    );
    if (isDuplicate) {
      alert(`Le numéro de facture "${fForm.numero}" existe déjà. Veuillez utiliser un numéro différent.`);
      return;
    }
    if (editingFact) {
      setFactures(factures.map((f) => f.id === editingFact ? { ...fForm, id: f.id } : f));
      setEditingFact(null);
    } else {
      setFactures([...factures, { ...fForm, id: Date.now() }]);
    }
    setFactModal(false);
  };

  const openEditFact = (f) => {
    setFForm({ numero: f.numero, date: f.date, clientId: f.clientId, reglement: f.reglement, lignes: [...f.lignes] });
    setCSearch(""); setPSearch(""); setSelProd(""); setProdQte(1); setShowCDD(false); setShowPDD(false);
    setEditingFact(f.id);
    setFactModal(true);
  };

  const totHT = fForm.lignes.reduce((s, l) => s + l.prixHT * l.qte, 0);
  const totTVA = fForm.lignes.reduce((s, l) => s + l.prixHT * l.qte * (l.tva / 100), 0);
  const totTTC = totHT + totTVA;

  const ddClients = clients.filter((c) => !cSearch || normalise(c.nom).includes(normalise(cSearch)) || c.id.includes(cSearch));
  const ddProds = products.filter((p) => !pSearch || normalise(p.description).includes(normalise(pSearch)) || p.id.includes(pSearch));

  // Logo
  const logoRef = useRef();
  const handleLogo = (e) => {
    const f = e.target.files[0];
    if (!f) return;
    const r = new FileReader();
    r.onload = (ev) => setLogoUrl(ev.target.result);
    r.readAsDataURL(f);
  };

  // Nav items
  const NAV = [
    { id: "factures",    icon: "🧾", label: "Factures" },
    { id: "clients",     icon: "👥", label: "Clients" },
    { id: "products",    icon: "📦", label: "Produits" },
    { id: "declaration", icon: "📋", label: "Déclaration" },
    { id: "settings",   icon: "⚙️", label: "Parametres" },
    { id: "calcul",     icon: "🧮", label: "Calcul" },
  ];

  // ── Écran de chargement Firestore ─────────────────────────────────────────
  if (!firestoreReady) {
    return (
      <div style={{
        display: "flex", flexDirection: "column", alignItems: "center",
        justifyContent: "center", height: "100vh", background: "#1a1a2e", gap: 24,
      }}>
        <style>{`
          @keyframes zkm-slide2 { 0% { transform: translateX(-100%); } 100% { transform: translateX(280%); } }
          @keyframes zkm-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.5; } }
        `}</style>
        <div style={{ textAlign: "center", marginBottom: 8 }}>
          <div style={{ fontSize: 48, marginBottom: 8 }}>⚡</div>
          <div style={{ color: "#C8A84B", fontSize: 26, fontWeight: 800, letterSpacing: 1 }}>ZK MAROC</div>
          <div style={{ color: "#aaaacc", fontSize: 13, marginTop: 4, letterSpacing: 2, textTransform: "uppercase" }}>Invoice Manager</div>
        </div>
        <div style={{ color: "#ccccee", fontSize: 15, fontWeight: 500, animation: "zkm-pulse 1.6s ease-in-out infinite" }}>
          Synchronisation en cours…
        </div>
        <div style={{ width: 240, height: 5, background: "#2a2a4a", borderRadius: 3, overflow: "hidden", position: "relative" }}>
          <div style={{ width: "50%", height: "100%", background: "linear-gradient(90deg, transparent, #C8A84B, transparent)", borderRadius: 3, position: "absolute", top: 0, left: 0, animation: "zkm-slide2 1.3s ease-in-out infinite" }} />
        </div>
        <div style={{ color: "#555577", fontSize: 12, marginTop: 4 }}>Connexion à la base de données Firebase…</div>
      </div>
    );
  }

  return (
    <div style={{ fontFamily: "'Segoe UI', system-ui, sans-serif", background: "#f5f4ef", minHeight: "100vh", display: "flex" }}>

      {/* ── Panel utilisateurs (admin) ── */}
      {showUsersPanel && (
        <UsersPanel currentUser={authUser} onClose={() => setShowUsersPanel(false)} />
      )}

      {/* ── Sidebar ── */}
      <div style={{ width: 240, background: DARK, minHeight: "100vh", position: "fixed", top: 0, left: 0, bottom: 0, display: "flex", flexDirection: "column", zIndex: 100 }}>
        {/* Header profil */}
        <div style={{ padding: "20px 16px 16px", borderBottom: "1px solid #ffffff14" }}>
          <div style={{ fontSize: 11, color: "#5555aa", textTransform: "uppercase", letterSpacing: 1, marginBottom: 8 }}>Profil actif</div>
          <div ref={profilRef} style={{ position: "relative" }}>
            <button onClick={() => setShowProfilMenu(p => !p)}
              style={{ width: "100%", background: (profilActif?.couleur || GOLD) + "22", border: "1.5px solid " + (profilActif?.couleur || GOLD) + "55", borderRadius: 10, padding: "10px 12px", cursor: "pointer", display: "flex", alignItems: "center", gap: 8, textAlign: "left" }}>
              <div style={{ width: 10, height: 10, borderRadius: "50%", background: profilActif?.couleur || GOLD, flexShrink: 0 }} />
              <div style={{ flex: 1, overflow: "hidden" }}>
                <div style={{ fontSize: 13, fontWeight: 700, color: "#fff", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{profilActif?.nom || "Entreprise"}</div>
                <div style={{ fontSize: 10, color: "#8888bb", marginTop: 1, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{profilActif?.companyInfo?.ice || "ICE non défini"}</div>
              </div>
              <span style={{ color: "#8888bb", fontSize: 10 }}>▼</span>
            </button>
            {showProfilMenu && (
              <div style={{ position: "absolute", top: "110%", left: 0, right: 0, background: "#252540", border: "1px solid #ffffff18", borderRadius: 12, zIndex: 500, overflow: "hidden", boxShadow: "0 10px 30px #00000050" }}>
                {profils.map(p => (
                  <div key={p.id}
                    style={{ display: "flex", alignItems: "center", gap: 8, padding: "10px 12px", cursor: "pointer", background: p.id === profilActif.id ? (p.couleur || GOLD) + "22" : "transparent", borderBottom: "1px solid #ffffff08", transition: "background .1s" }}
                    onMouseEnter={e => { if (p.id !== profilActif.id) e.currentTarget.style.background = "#ffffff0a"; }}
                    onMouseLeave={e => { e.currentTarget.style.background = p.id === profilActif.id ? (p.couleur || GOLD) + "22" : "transparent"; }}>
                    <div style={{ width: 9, height: 9, borderRadius: "50%", background: p.couleur || GOLD, flexShrink: 0 }} />
                    <div style={{ flex: 1, overflow: "hidden" }} onClick={() => { setProfilActifId(p.id); setShowProfilMenu(false); setPage("factures"); }}>
                      <div style={{ fontSize: 12, fontWeight: 600, color: "#fff", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{p.nom}</div>
                    </div>
                    <button onClick={e => { e.stopPropagation(); setEditProfilModal(p); setShowProfilMenu(false); }}
                      style={{ background: "transparent", border: "none", color: "#8888bb", cursor: "pointer", fontSize: 13, padding: "2px 4px", borderRadius: 4 }}
                      title="Modifier">
                      ✎
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
        <nav style={{ padding: "18px 12px", flex: 1 }}>
          {NAV.map((item) => (
            <button key={item.id} onClick={() => setPage(item.id)}
              style={{ display: "flex", alignItems: "center", gap: 10, padding: "11px 14px", borderRadius: 10, cursor: "pointer", marginBottom: 4, background: page === item.id ? (profilActif?.couleur || GOLD) : "transparent", color: page === item.id ? "#fff" : "#8888bb", fontWeight: page === item.id ? 700 : 400, fontSize: 14, border: "none", width: "100%", textAlign: "left", transition: "all .15s" }}>
              <span style={{ fontSize: 16 }}>{item.icon}</span>{item.label}
            </button>
          ))}
        </nav>
        <div style={{ padding: "12px 16px", borderTop: "1px solid #ffffff10", fontSize: 11, color: "#3333aa" }}>
          {clients.length} clients · {products.length} produits
        </div>

        {/* ── Utilisateur connecté ── */}
        <div style={{ padding: "12px 16px", borderTop: "1px solid #ffffff10" }}>
          {/* Badge rôle */}
          {(() => {
            const roleInfo = {
              admin:            { label: "Administrateur", color: "#fcd34d", bg: "#92400e40", icon: "👑" },
              ecriture_lecture: { label: "Écriture & Lecture", color: "#93c5fd", bg: "#1e40af40", icon: "✏️" },
              lecture:          { label: "Lecture seule", color: "#6ee7b7", bg: "#065f4640", icon: "👁️" },
            };
            const r = roleInfo[userRole] || roleInfo.lecture;
            return (
              <div style={{ background: r.bg, border: "1px solid " + r.color + "40", borderRadius: 8, padding: "6px 10px", marginBottom: 8 }}>
                <div style={{ fontSize: 10, color: r.color, fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.5 }}>
                  {r.icon} {r.label}
                </div>
                <div style={{ fontSize: 11, color: "#ccccee", marginTop: 2, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                  {userName}
                </div>
              </div>
            );
          })()}

          {/* Bouton gestion utilisateurs (admin only) */}
          {isAdmin && (
            <button
              onClick={() => setShowUsersPanel(true)}
              style={{ width: "100%", background: "#ffffff0a", border: "1px solid #ffffff15", borderRadius: 8, padding: "7px 10px", cursor: "pointer", color: "#aaaacc", fontSize: 12, fontWeight: 600, marginBottom: 6, textAlign: "left", display: "flex", alignItems: "center", gap: 6 }}>
              👥 Gérer les utilisateurs
            </button>
          )}

          {/* Bouton déconnexion */}
          <button
            onClick={handleLogout}
            style={{ width: "100%", background: "#fee2e210", border: "1px solid #991b1b30", borderRadius: 8, padding: "7px 10px", cursor: "pointer", color: "#fca5a5", fontSize: 12, fontWeight: 600, textAlign: "left", display: "flex", alignItems: "center", gap: 6 }}>
            🚪 Se déconnecter
          </button>
        </div>
      </div>

      {/* ── Content ── */}
      <div style={{ marginLeft: 240, flex: 1, padding: "32px 36px" }}>

        {/* ═ FACTURES ═ */}
        {page === "factures" && (
          <>
            {/* ── En-tête ── */}
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 24 }}>
              <div>
                <h1 style={{ margin: 0, fontSize: 26, fontWeight: 900, color: DARK }}>Factures</h1>
                <div style={{ display: "flex", alignItems: "center", gap: 10, marginTop: 4 }}>
                  <span style={{ color: "#6b7280", fontSize: 14 }}>{factures.length} facture(s)</span>
                  <span style={{ background: (profilActif?.couleur || GOLD) + "20", color: profilActif?.couleur || GOLD, border: "1px solid " + (profilActif?.couleur || GOLD) + "40", borderRadius: 20, padding: "2px 10px", fontSize: 12, fontWeight: 700 }}>{profilActif?.nom}</span>
                </div>
              </div>
              <button style={BTN_PRIMARY} onClick={openNewFact} disabled={!canWrite} title={!canWrite ? "Accès en lecture seule" : ""}>+ Nouvelle Facture</button>
            </div>

            {/* ── Cartes stats ── */}
            <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 16, marginBottom: 24 }}>
              {[
                { icon: "🧾", label: "Nb. Factures", val: factures.length },
                { icon: "💰", label: "CA Total HT", val: fmt(factures.reduce((s, f) => s + f.lignes.reduce((ss, l) => ss + l.prixHT * l.qte, 0), 0)) + " DH" },
                { icon: "📊", label: "CA Total TTC", val: fmt(factures.reduce((s, f) => s + f.lignes.reduce((ss, l) => ss + l.prixHT * l.qte * (1 + l.tva / 100), 0), 0)) + " DH" },
              ].map((s) => (
                <div key={s.label} style={{ ...CARD, display: "flex", alignItems: "center", gap: 16 }}>
                  <div style={{ fontSize: 28 }}>{s.icon}</div>
                  <div>
                    <div style={{ fontSize: 22, fontWeight: 900, color: DARK }}>{s.val}</div>
                    <div style={{ fontSize: 12, color: "#6b7280", marginTop: 2 }}>{s.label}</div>
                  </div>
                </div>
              ))}
            </div>

            {/* ── Synthèse mensuelle ── */}
            {factures.length > 0 && (() => {
              const MONTHS = ["Jan","Fév","Mar","Avr","Mai","Jun","Jul","Aoû","Sep","Oct","Nov","Déc"];
              const byMonth = {};
              factures.forEach((f) => {
                const d = new Date(f.date);
                const key = d.getFullYear() + "-" + String(d.getMonth()).padStart(2,"0");
                const label = MONTHS[d.getMonth()] + " " + d.getFullYear();
                if (!byMonth[key]) byMonth[key] = { label, ht: 0, ttc: 0, nb: 0 };
                const ht = f.lignes.reduce((s, l) => s + l.prixHT * l.qte, 0);
                const ttc = f.lignes.reduce((s, l) => s + l.prixHT * l.qte * (1 + l.tva / 100), 0);
                byMonth[key].ht += ht;
                byMonth[key].ttc += ttc;
                byMonth[key].nb += 1;
              });
              const months = Object.entries(byMonth).sort(([a],[b]) => a.localeCompare(b)).map(([,v]) => v);
              const maxTTC = Math.max(...months.map(m => m.ttc), 1);
              const BAR_H = 120;
              return (
                <div style={{ ...CARD, marginBottom: 24 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 18 }}>
                    <span style={{ fontSize: 20 }}>📅</span>
                    <h3 style={{ margin: 0, fontSize: 16, fontWeight: 800, color: DARK }}>Synthèse mensuelle</h3>
                  </div>
                  <div style={{ display: "flex", alignItems: "flex-end", gap: 10, overflowX: "auto", paddingBottom: 8 }}>
                    {months.map((m) => {
                      const barH = Math.max(6, Math.round((m.ttc / maxTTC) * BAR_H));
                      return (
                        <div key={m.label} style={{ display: "flex", flexDirection: "column", alignItems: "center", minWidth: 72, gap: 4 }}>
                          <div style={{ fontSize: 11, fontWeight: 700, color: "#166534" }}>{fmt(m.ttc).split(",")[0]} DH</div>
                          <div style={{ position: "relative", width: 44 }}>
                            <div title={"TTC: " + fmt(m.ttc) + " DH"} style={{ width: 44, height: barH, background: "linear-gradient(180deg," + GOLD + "," + GOLD + "99)", borderRadius: "5px 5px 0 0", transition: "height .3s" }} />
                          </div>
                          <div style={{ fontSize: 10, color: "#374151", fontWeight: 600, textAlign: "center", lineHeight: 1.3 }}>{m.label}</div>
                          <div style={{ fontSize: 10, color: "#9ca3af" }}>{m.nb} fact.</div>
                        </div>
                      );
                    })}
                  </div>
                  {months.length > 1 && (
                    <div style={{ marginTop: 14, paddingTop: 14, borderTop: "1px solid #f0f0f0", display: "flex", gap: 24, flexWrap: "wrap" }}>
                      {months.map((m) => (
                        <div key={m.label} style={{ fontSize: 12 }}>
                          <span style={{ fontWeight: 700, color: DARK }}>{m.label}</span>
                          <span style={{ color: "#6b7280", marginLeft: 8 }}>{m.nb} fact. · HT {fmt(m.ht)} DH · TTC {fmt(m.ttc)} DH</span>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              );
            })()}

            {/* ── Tableau des factures ── */}
            <div style={CARD}>
              <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 16, flexWrap: "wrap" }}>
                {/* Recherche */}
                <div style={{ position: "relative", flex: 1, minWidth: 220 }}>
                  <span style={{ position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)", color: "#9ca3af", fontSize: 14 }}>🔍</span>
                  <input value={factSearch} onChange={(e) => { setFactSearch(e.target.value); setFactPage(1); }} placeholder="Rechercher..." style={{ ...SEARCH_INPUT, width: "100%", boxSizing: "border-box" }} />
                </div>
                {/* Bouton colonnes */}
                <div style={{ position: "relative" }} ref={colMenuRef}>
                  <button onClick={() => setShowColMenu(!showColMenu)}
                    style={{ ...BTN_SECONDARY, display: "flex", alignItems: "center", gap: 6, fontSize: 13 }}>
                    <span>⚙</span> Colonnes <span style={{ background: GOLD, color: "#fff", borderRadius: 10, padding: "1px 7px", fontSize: 11, fontWeight: 700 }}>{visibleCols.length}</span>
                  </button>
                  {showColMenu && (
                    <div style={{ position: "absolute", right: 0, top: "110%", background: "#fff", border: "1px solid #e5e7eb", borderRadius: 12, padding: "12px 16px", zIndex: 500, boxShadow: "0 10px 30px #0002", minWidth: 200 }}>
                      <div style={{ fontSize: 11, fontWeight: 700, color: "#6b7280", textTransform: "uppercase", letterSpacing: "0.05em", marginBottom: 10 }}>Afficher / Masquer</div>
                      {ALL_COLS.filter(c => c !== "Actions").map((col) => (
                        <label key={col} style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8, cursor: "pointer", fontSize: 13, color: "#374151" }}>
                          <input type="checkbox"
                            checked={visibleCols.includes(col)}
                            onChange={() => {
                              if (visibleCols.includes(col)) {
                                setVisibleCols(visibleCols.filter(c => c !== col));
                              } else {
                                setVisibleCols(ALL_COLS.filter(c => [...visibleCols, col].includes(c)));
                              }
                            }}
                            style={{ width: 16, height: 16, accentColor: GOLD, cursor: "pointer" }}
                          />
                          {col}
                        </label>
                      ))}
                      <div style={{ borderTop: "1px solid #f0f0f0", marginTop: 8, paddingTop: 8 }}>
                        <button onClick={() => setVisibleCols(ALL_COLS)} style={{ fontSize: 11, color: GOLD, background: "none", border: "none", cursor: "pointer", fontWeight: 700 }}>Tout afficher</button>
                      </div>
                    </div>
                  )}
                </div>
              </div>

              <table style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead>
                  <tr>
                    {[...visibleCols, "Actions"].filter((v,i,a) => a.indexOf(v) === i).map((h) => (
                      <th key={h} style={TH}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {pagedFacts.length === 0 && (
                    <tr><td colSpan={visibleCols.length + 1} style={{ ...TD, textAlign: "center", color: "#9ca3af", padding: 48 }}>
                      Aucune facture. Cliquez sur "+ Nouvelle Facture" pour commencer.
                    </td></tr>
                  )}
                  {pagedFacts.map((f) => {
                    const cl = clients.find((c) => c.id === f.clientId);
                    const ht = f.lignes.reduce((s, l) => s + l.prixHT * l.qte, 0);
                    const tva = f.lignes.reduce((s, l) => s + l.prixHT * l.qte * (l.tva / 100), 0);
                    const ftag = factTags[f.id];
                    const FACT_PAY_TAGS = [
                      { id: "paye",    label: "Payé",     bg: "#dcfce7", color: "#166534", dot: "#22c55e" },
                      { id: "partiel", label: "Partiel",  bg: "#fef9c3", color: "#854d0e", dot: "#eab308" },
                      { id: "nonpaye", label: "Non payé", bg: "#fee2e2", color: "#991b1b", dot: "#ef4444" },
                    ];
                    const ftagDef = FACT_PAY_TAGS.find(t => t.id === ftag);
                    const colMap = {
                      "N° Facture": <td style={{ ...TD, fontWeight: 800, color: GOLD, fontFamily: "monospace" }}>{f.numero}</td>,
                      "Client":     <td style={TD}><div style={{ fontWeight: 600 }}>{cl?.nom || "—"}</div><div style={{ fontSize: 11, color: "#9ca3af" }}>{cl?.id}</div></td>,
                      "Date":       <td style={TD}>{new Date(f.date).toLocaleDateString("fr-MA")}</td>,
                      "Total HT":   <td style={TD}>{fmt(ht)} DH</td>,
                      "TVA":        <td style={TD}>{fmt(tva)} DH</td>,
                      "Total TTC":  <td style={{ ...TD, fontWeight: 800 }}>{fmt(ht + tva)} DH</td>,
                      "Reglement":  <td style={TD}><Badge text={f.reglement} color="blue" /></td>,
                      "Statut": (
                        <td style={TD}>
                          <select value={ftag || ""} onChange={(e) => setFactTags(prev => ({ ...prev, [f.id]: e.target.value || undefined }))}
                            style={{ border: "1.5px solid " + (ftagDef ? ftagDef.bg : "#e5e7eb"), background: ftagDef ? ftagDef.bg : "#f9fafb", color: ftagDef ? ftagDef.color : "#6b7280", borderRadius: 20, padding: "3px 10px", fontSize: 11, fontWeight: 700, cursor: "pointer", outline: "none" }}>
                            <option value="">— Statut —</option>
                            {[{id:"paye",label:"Payé"},{id:"partiel",label:"Partiel"},{id:"nonpaye",label:"Non payé"}].map(t => <option key={t.id} value={t.id}>{t.label}</option>)}
                          </select>
                        </td>
                      ),
                    };
                    return (
                      <tr key={f.id} onMouseEnter={(e) => e.currentTarget.style.background = "#fafaf8"} onMouseLeave={(e) => e.currentTarget.style.background = ""}>
                        {[...visibleCols, "Actions"].filter((v,i,a) => a.indexOf(v) === i).map((col) =>
                          col === "Actions" ? (
                            <td key="actions" style={TD}>
                              <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
                                {/* Icône Edit */}
                                {canWrite && <button title="Modifier" onClick={() => openEditFact(f)}
                                  style={{ background: "#eff6ff", border: "none", borderRadius: 7, width: 32, height: 32, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 16 }}>
                                  ✏️
                                </button>}
                              {/* Icône Aperçu */}
                                <button title="Aperçu" onClick={() => setPreviewFact(f)}
                                  style={{ background: "#fef3c7", border: "none", borderRadius: 7, width: 32, height: 32, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 16 }}>
                                  👁
                                </button>
                                {/* Icône Télécharger PDF */}
                                <button title={"Télécharger PDF — " + f.numero} onClick={() => downloadPDF(f)}
                                  style={{ background: "#eff6ff", border: "none", borderRadius: 7, width: 32, height: 32, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 16 }}>
                                  ⬇
                                </button>
                                {/* Supprimer */}
                                {canWrite && <button title="Supprimer" onClick={() => { if (window.confirm("Supprimer cette facture ?")) setFactures(factures.filter((x) => x.id !== f.id)); }}
                                  style={{ background: "#fee2e2", border: "none", borderRadius: 7, width: 32, height: 32, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 15, color: "#991b1b", fontWeight: 900 }}>
                                  ✕
                                </button>}
                              </div>
                            </td>
                          ) : (
                            <React.Fragment key={col}>{colMap[col]}</React.Fragment>
                          )
                        )}
                      </tr>
                    );
                  })}
                </tbody>
              </table>
              <Pagination total={filteredFacts.length} page={factPage} perPage={PER_PAGE} onChange={setFactPage} />
            </div>
          </>
        )}

        {/* ═ CLIENTS ═ */}
        {page === "clients" && (
          <>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 24 }}>
              <div>
                <h1 style={{ margin: 0, fontSize: 26, fontWeight: 900, color: DARK }}>Clients</h1>
                <div style={{ color: "#6b7280", fontSize: 14, marginTop: 4 }}>{clients.length} client(s)</div>
              </div>
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                {canWrite && <button style={{ ...BTN_PRIMARY, background: "#1d4ed8" }} onClick={() => setImportModal("clients")}>📥 Importer Excel</button>}
                {canWrite && <button style={BTN_PRIMARY} onClick={() => { setCForm({ id: "", type: "", nom: "", ice: "", adresse: "", ville: "", tel: "", email: "" }); setClientModal("add"); }}>+ Ajouter Client</button>}
              </div>
            </div>
            <div style={CARD}>
              <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 14, flexWrap: "wrap" }}>
                <div style={{ position: "relative", flex: 1, minWidth: 200 }}>
                  <span style={{ position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)", color: "#9ca3af", fontSize: 14 }}>🔍</span>
                  <input value={clientSearch} onChange={(e) => { setClientSearch(e.target.value); setClientPage(1); }} placeholder="Nom, ICE, ID..." style={{ ...SEARCH_INPUT, width: "100%", boxSizing: "border-box" }} />
                </div>
              </div>
              {/* Toolbar: col menu + per page */}
              <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 14, flexWrap: "wrap", borderTop: "1px solid #f3f4f6", paddingTop: 10 }}>
                <div style={{ position: "relative" }} ref={clientColMenuRef}>
                  <button onClick={() => setShowClientColMenu(!showClientColMenu)}
                    style={{ ...BTN_SECONDARY, display: "flex", alignItems: "center", gap: 6, fontSize: 13 }}>
                    <span>⚙</span> Colonnes <span style={{ background: GOLD, color: "#fff", borderRadius: 10, padding: "1px 7px", fontSize: 11, fontWeight: 700 }}>{visibleClientCols.length}</span>
                  </button>
                  {showClientColMenu && (
                    <div style={{ position: "absolute", left: 0, top: "110%", background: "#fff", border: "1px solid #e5e7eb", borderRadius: 12, padding: "12px 16px", zIndex: 500, boxShadow: "0 10px 30px #0002", minWidth: 200 }}>
                      <div style={{ fontSize: 11, fontWeight: 700, color: "#6b7280", textTransform: "uppercase", letterSpacing: "0.05em", marginBottom: 10 }}>Afficher / Masquer</div>
                      {ALL_CLIENT_COLS.map((col) => (
                        <label key={col} style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8, cursor: "pointer", fontSize: 13, color: "#374151" }}>
                          <input type="checkbox"
                            checked={visibleClientCols.includes(col)}
                            onChange={() => {
                              if (visibleClientCols.includes(col)) setVisibleClientCols(visibleClientCols.filter(c => c !== col));
                              else setVisibleClientCols(ALL_CLIENT_COLS.filter(c => [...visibleClientCols, col].includes(c)));
                            }}
                            style={{ width: 16, height: 16, accentColor: GOLD, cursor: "pointer" }} />
                          {col}
                        </label>
                      ))}
                      <div style={{ borderTop: "1px solid #f0f0f0", marginTop: 8, paddingTop: 8 }}>
                        <button onClick={() => setVisibleClientCols(ALL_CLIENT_COLS)} style={{ fontSize: 11, color: GOLD, background: "none", border: "none", cursor: "pointer", fontWeight: 700 }}>Tout afficher</button>
                      </div>
                    </div>
                  )}
                </div>
                <div style={{ marginLeft: "auto", display: "flex", alignItems: "center", gap: 8, fontSize: 13, color: "#6b7280" }}>
                  Par page :
                  {[10, 25, 50].map(n => (
                    <button key={n} onClick={() => { setClientsPerPage(n); setClientPage(1); }}
                      style={{ border: "1.5px solid " + (clientsPerPage === n ? GOLD : "#e5e7eb"), background: clientsPerPage === n ? GOLD : "#fff", color: clientsPerPage === n ? "#fff" : "#374151", borderRadius: 8, padding: "3px 10px", cursor: "pointer", fontWeight: clientsPerPage === n ? 700 : 400, fontSize: 13 }}>
                      {n}
                    </button>
                  ))}
                </div>
              </div>
              <table style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead>
                  <tr>
                    {[...visibleClientCols, "Actions"].map((h) => <th key={h} style={TH}>{h}</th>)}
                  </tr>
                </thead>
                <tbody>
                  {pagedClients.length === 0 && <tr><td colSpan={visibleClientCols.length + 1} style={{ ...TD, textAlign: "center", color: "#9ca3af", padding: 40 }}>Aucun client trouve.</td></tr>}
                  {pagedClients.map((c) => {
                    const clientColMap = {
                      "ID":                   <td key="id" style={{ ...TD, fontWeight: 700, color: GOLD, fontFamily: "monospace" }}>{c.id}</td>,
                      "Nom / Raison Sociale": <td key="nom" style={TD}><div style={{ fontWeight: 600 }}>{c.nom}</div>{c.type && <Badge text={c.type} color="gray" />}</td>,
                      "ICE":                  <td key="ice" style={{ ...TD, fontFamily: "monospace", fontSize: 12 }}>{c.ice}</td>,
                      "Adresse":              <td key="adr" style={TD}>{c.adresse}</td>,
                      "Ville":               <td key="vil" style={TD}>{c.ville}</td>,
                      "Telephone":            <td key="tel" style={TD}>{c.tel}</td>,
                      "Email":               <td key="email" style={TD}>{c.email}</td>,
                    };
                    return (
                      <tr key={c.id} onMouseEnter={(e) => e.currentTarget.style.background = "#fafaf8"} onMouseLeave={(e) => e.currentTarget.style.background = ""}>
                        {[...visibleClientCols, "Actions"].map((col) => col === "Actions" ? (
                          <td key="actions" style={TD}>
                            <div style={{ display: "flex", gap: 6 }}>
                              {canWrite && <SmallBtn label="Modifier" bg="#eff6ff" color="#1d4ed8" onClick={() => { setCForm({ ...c }); setClientModal("edit"); }} />}
                              {canWrite && <SmallBtn label="X" bg="#fee2e2" color="#991b1b" onClick={() => { if (window.confirm("Supprimer ?")) setClients(clients.filter((x) => x.id !== c.id)); }} />}
                            </div>
                          </td>
                        ) : clientColMap[col])}
                      </tr>
                    );
                  })}
                </tbody>
              </table>
              <Pagination total={filteredClients.length} page={clientPage} perPage={clientsPerPage} onChange={setClientPage} />
            </div>
          </>
        )}

        {/* ═ PRODUITS ═ */}
        {page === "products" && (
          <>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 24 }}>
              <div>
                <h1 style={{ margin: 0, fontSize: 26, fontWeight: 900, color: DARK }}>Produits et Services</h1>
                <div style={{ color: "#6b7280", fontSize: 14, marginTop: 4 }}>{products.length} produit(s)</div>
              </div>
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                {canWrite && <button style={{ ...BTN_PRIMARY, background: "#1d4ed8" }} onClick={() => setImportModal("products")}>📥 Importer Excel</button>}
                {canWrite && <button style={BTN_PRIMARY} onClick={() => { setPForm({ id: "", description: "", prixHT: "", tva: 20, categorie: "" }); setPFormTTC(""); setProdModal("add"); }}>+ Ajouter Produit</button>}
              </div>
            </div>
            <div style={CARD}>
              {/* Search + category chips */}
              <div style={{ display: "flex", gap: 12, alignItems: "center", marginBottom: 14, flexWrap: "wrap" }}>
                <div style={{ position: "relative" }}>
                  <span style={{ position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)", color: "#9ca3af", fontSize: 14 }}>🔍</span>
                  <input value={prodSearch} onChange={(e) => { setProdSearch(e.target.value); setProdPage(1); }} placeholder="Description, reference..." style={SEARCH_INPUT} />
                </div>
                <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                  {["Tous", ...allCategories.filter((c) => products.some((p) => p.categorie === c))].map((cat) => (
                    <button key={cat} onClick={() => { setProdCatFilter(cat); setProdPage(1); }}
                      style={{ border: "1.5px solid " + (prodCatFilter === cat ? GOLD : "#e5e7eb"), background: prodCatFilter === cat ? GOLD : "#fff", color: prodCatFilter === cat ? "#fff" : "#374151", borderRadius: 20, padding: "5px 14px", cursor: "pointer", fontWeight: prodCatFilter === cat ? 700 : 500, fontSize: 12, whiteSpace: "nowrap" }}>
                      {cat}{cat !== "Tous" && <span style={{ marginLeft: 5, opacity: 0.7 }}>({products.filter(p => p.categorie === cat).length})</span>}
                    </button>
                  ))}
                </div>
              </div>
              <table style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead>
                  <tr>{["Référence", "Catégorie", "Description", "Prix HT", "TVA", "Prix TTC", "Actions"].map((h) => <th key={h} style={TH}>{h}</th>)}</tr>
                </thead>
                <tbody>
                  {pagedProds.length === 0 && <tr><td colSpan={7} style={{ ...TD, textAlign: "center", color: "#9ca3af", padding: 40 }}>Aucun produit trouvé.</td></tr>}
                  {pagedProds.map((p) => {
                    const cs = catStyle(p.categorie);
                    return (
                      <tr key={p.id} onMouseEnter={(e) => e.currentTarget.style.background = "#fafaf8"} onMouseLeave={(e) => e.currentTarget.style.background = ""}>
                        <td style={{ ...TD, fontWeight: 700, color: GOLD, fontFamily: "monospace" }}>{p.id}</td>
                        <td style={TD}>
                          {p.categorie
                            ? <span style={{ background: cs.bg, color: cs.color, borderRadius: 20, padding: "3px 10px", fontSize: 11, fontWeight: 700, whiteSpace: "nowrap" }}>{p.categorie}</span>
                            : <span style={{ color: "#d1d5db", fontSize: 11 }}>—</span>}
                        </td>
                        <td style={TD}>{p.description}</td>
                        <td style={{ ...TD, fontWeight: 600 }}>{fmt(p.prixHT)} DH</td>
                        <td style={TD}><Badge text={p.tva + "%"} color="orange" /></td>
                        <td style={{ ...TD, fontWeight: 800, color: "#166534" }}>{fmt(p.prixHT * (1 + p.tva / 100))} DH</td>
                        <td style={TD}>
                          <div style={{ display: "flex", gap: 6 }}>
                            {canWrite && <SmallBtn label="Modifier" bg="#eff6ff" color="#1d4ed8" onClick={() => { setPForm({ ...p, categorie: p.categorie || "" }); setPFormTTC(p.prixHT ? String(parseFloat((p.prixHT * (1 + p.tva / 100)).toFixed(2))) : ""); setProdModal("edit"); }} />}
                            {canWrite && <SmallBtn label="X" bg="#fee2e2" color="#991b1b" onClick={() => { if (window.confirm("Supprimer ?")) setProducts(products.filter((x) => x.id !== p.id)); }} />}
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
              <div style={{ display: "flex", justifyContent: "flex-end", alignItems: "center", gap: 8, marginBottom: 10, fontSize: 13, color: "#6b7280" }}>
                Par page :
                {[10, 25, 50].map(n => (
                  <button key={n} onClick={() => { setProdsPerPage(n); setProdPage(1); }}
                    style={{ border: "1.5px solid " + (prodsPerPage === n ? GOLD : "#e5e7eb"), background: prodsPerPage === n ? GOLD : "#fff", color: prodsPerPage === n ? "#fff" : "#374151", borderRadius: 8, padding: "3px 10px", cursor: "pointer", fontWeight: prodsPerPage === n ? 700 : 400, fontSize: 13 }}>
                    {n}
                  </button>
                ))}
              </div>
              <Pagination total={filteredProds.length} page={prodPage} perPage={prodsPerPage} onChange={setProdPage} />
            </div>
          </>
        )}

        {/* ═ DÉCLARATION TVA ═ */}
        {page === "declaration" && (
          <DeclarationPage factures={factures} clients={clients} customRowTags={customRowTags} setCustomRowTags={setCustomRowTags} />
        )}

        {/* ═ CALCUL ═ */}
        {page === "calcul" && (
          <CalculPage products={products} onCreateFacture={openFromSimulator} />
        )}

        {/* ═ SETTINGS ═ */}
        {page === "settings" && !canWrite && (
          <div style={{ textAlign: "center", padding: "80px 40px" }}>
            <div style={{ fontSize: 64, marginBottom: 16 }}>🔒</div>
            <h2 style={{ color: "#1a1a2e", fontSize: 22, fontWeight: 800, marginBottom: 8 }}>Accès restreint</h2>
            <p style={{ color: "#6b7280", fontSize: 14 }}>La page Paramètres est réservée aux utilisateurs avec droits d'écriture.</p>
          </div>
        )}
        {page === "settings" && canWrite && (
          <SettingsPage
            config={config}
            setConfig={setConfig}
            factures={factures}
            clients={clients}
            logoUrl={logoUrl}
            setLogoUrl={setLogoUrl}
            logoRef={logoRef}
            handleLogo={handleLogo}
            nextFNum={nextFNum}
            setPreviewFact={setPreviewFact}
            companyInfo={companyInfo}
            setCompanyInfo={setCompanyInfo}
            dlDirHandle={dlDirHandle}
            chooseDlFolder={chooseDlFolder}
            customCategories={customCategories}
            setCustomCategories={setCustomCategories}
            allCategories={allCategories}
          />
        )}
      </div>

      {/* ═══ MODAL : NOUVELLE FACTURE ═══ */}
      {factModal && (
        <div style={{ position: "fixed", inset: 0, background: "#000000bb", zIndex: 2000, display: "flex", alignItems: "flex-start", justifyContent: "center", padding: "20px", overflowY: "auto" }}>
          <div style={{ background: "#fff", borderRadius: 16, width: "100%", maxWidth: 860, boxShadow: "0 25px 60px #0006", marginTop: 20, marginBottom: 20 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "22px 28px 18px", borderBottom: "1px solid #e5e7eb" }}>
              <h3 style={{ margin: 0, fontSize: 20, fontWeight: 800, color: DARK }}>{editingFact ? "Modifier la Facture" : "Nouvelle Facture"}</h3>
              <button onClick={() => { setFactModal(false); setSimulatorLines(null); }} style={{ border: "none", background: "#f3f4f6", borderRadius: 8, width: 34, height: 34, cursor: "pointer", fontSize: 16, color: "#6b7280" }}>X</button>
            </div>
            {simulatorLines && fForm.lignes.length > 0 && !editingFact && (
              <div style={{ margin: "14px 28px 0", background: "#f0fdf4", border: "1.5px solid #86efac", borderRadius: 10, padding: "11px 16px", display: "flex", alignItems: "center", gap: 12 }}>
                <span style={{ fontSize: 18 }}>🧮</span>
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 13, fontWeight: 700, color: "#166534" }}>{simulatorLines.length} produit(s) importé(s) depuis le Simulateur</div>
                  <div style={{ fontSize: 11, color: "#4ade80" }}>Choisissez un client et enregistrez pour finaliser.</div>
                </div>
                <button onClick={() => { setFForm(f => ({ ...f, lignes: [] })); setSimulatorLines(null); }}
                  style={{ background: "#fee2e2", border: "none", borderRadius: 7, padding: "5px 10px", cursor: "pointer", color: "#991b1b", fontSize: 12, fontWeight: 600 }}>
                  Effacer
                </button>
              </div>
            )}
            <div style={{ padding: "22px 28px" }}>
              {/* Row 1 */}
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 16, marginBottom: 0 }}>
                <div>
                  <FieldLabel text="N° Facture" required />
                  {(() => {
                    const numDuplicate = fForm.numero.trim() && factures.some((f) =>
                      f.numero.trim() === fForm.numero.trim() && f.id !== editingFact
                    );
                    return (
                      <>
                        <input value={fForm.numero} onChange={(e) => setFForm({ ...fForm, numero: e.target.value })}
                          style={{ width: "100%", border: "1.5px solid " + (numDuplicate ? "#ef4444" : "#d1d5db"), borderRadius: 8, padding: "9px 12px", fontSize: 14, outline: "none", boxSizing: "border-box", fontFamily: "monospace", fontWeight: 700, color: numDuplicate ? "#ef4444" : GOLD, background: numDuplicate ? "#fef2f2" : "#fff", transition: "border-color .15s" }} />
                        {numDuplicate && (
                          <div style={{ fontSize: 11, color: "#ef4444", marginTop: 4, fontWeight: 600 }}>
                            ⚠ Ce numéro existe déjà
                          </div>
                        )}
                      </>
                    );
                  })()}
                </div>
                <div>
                  <FieldLabel text="Date" required />
                  <input type="date" value={fForm.date} onChange={(e) => setFForm({ ...fForm, date: e.target.value })}
                    style={{ width: "100%", border: "1.5px solid #d1d5db", borderRadius: 8, padding: "9px 12px", fontSize: 14, outline: "none", boxSizing: "border-box", fontFamily: "inherit" }} />
                </div>
                <SelectInput label="Reglement" value={fForm.reglement} onChange={(v) => setFForm({ ...fForm, reglement: v })}
                  options={["virement", "cheque", "especes", "carte bancaire"]} />
              </div>

              {/* Client dropdown */}
              <div style={{ marginBottom: 16, marginTop: 8 }} ref={cDDRef}>
                <FieldLabel text="Client" required />
                {fForm.clientId ? (
                  <div style={{ display: "flex", alignItems: "center", gap: 12, background: "#f0fdf4", border: "1.5px solid #86efac", borderRadius: 8, padding: "10px 14px" }}>
                    <div style={{ flex: 1 }}>
                      <div style={{ fontWeight: 700, color: "#166534" }}>{clients.find((c) => c.id === fForm.clientId)?.nom}</div>
                      <div style={{ fontSize: 11, color: "#4ade80" }}>{fForm.clientId} — ICE : {clients.find((c) => c.id === fForm.clientId)?.ice}</div>
                    </div>
                    <SmallBtn label="X" bg="#fee2e2" color="#991b1b" onClick={() => { setFForm({ ...fForm, clientId: "" }); setCSearch(""); }} />
                  </div>
                ) : (
                  <div style={{ position: "relative" }}>
                    <span style={{ position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)", color: "#9ca3af", pointerEvents: "none" }}>🔍</span>
                    <input value={cSearch} onChange={(e) => { setCSearch(e.target.value); setShowCDD(true); }} onFocus={() => setShowCDD(true)}
                      placeholder="Rechercher un client..." style={{ ...SEARCH_INPUT, width: "100%", boxSizing: "border-box" }} />
                    {showCDD && (
                      <div style={{ position: "absolute", zIndex: 300, background: "#fff", border: "1px solid #e5e7eb", borderRadius: 10, maxHeight: 210, overflowY: "auto", boxShadow: "0 10px 30px #0003", width: "100%", top: "110%" }}>
                        {ddClients.slice(0, 12).map((c) => (
                          <div key={c.id} onClick={() => { setFForm({ ...fForm, clientId: c.id }); setCSearch(""); setShowCDD(false); }}
                            style={{ padding: "10px 14px", cursor: "pointer", borderBottom: "1px solid #f3f4f6" }}
                            onMouseEnter={(e) => e.currentTarget.style.background = "#f9fafb"} onMouseLeave={(e) => e.currentTarget.style.background = "#fff"}>
                            <div style={{ fontWeight: 600, fontSize: 13 }}>{c.nom}</div>
                            <div style={{ fontSize: 11, color: "#9ca3af" }}>{c.id} — ICE : {c.ice}</div>
                          </div>
                        ))}
                        {ddClients.length === 0 && <div style={{ padding: 14, color: "#9ca3af", fontSize: 13 }}>Aucun client trouve</div>}
                      </div>
                    )}
                  </div>
                )}
              </div>

              {/* Product dropdown */}
              <div style={{ background: "#f8f8f6", borderRadius: 12, padding: "16px 18px", marginBottom: 20 }} ref={pDDRef}>
                <FieldLabel text="Ajouter un produit / service" />
                <div style={{ display: "flex", gap: 10, alignItems: "flex-end" }}>
                  <div style={{ flex: 1 }}>
                    {selProd ? (
                      <div style={{ display: "flex", alignItems: "center", gap: 8, background: "#eff6ff", border: "1.5px solid #93c5fd", borderRadius: 8, padding: "9px 12px" }}>
                        <div style={{ flex: 1, fontSize: 13 }}>
                          <span style={{ fontWeight: 800, color: "#1d4ed8", fontFamily: "monospace" }}>{selProd}</span>
                          <span style={{ color: "#374151", marginLeft: 8 }}>{products.find((p) => p.id === selProd)?.description?.slice(0, 55)}</span>
                        </div>
                        <button onClick={() => { setSelProd(""); setPSearch(""); }} style={{ border: "none", background: "none", cursor: "pointer", color: "#6b7280", fontSize: 16 }}>X</button>
                      </div>
                    ) : (
                      <div style={{ position: "relative" }}>
                        <span style={{ position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)", color: "#9ca3af", pointerEvents: "none" }}>🔍</span>
                        <input value={pSearch} onChange={(e) => { setPSearch(e.target.value); setShowPDD(true); }} onFocus={() => setShowPDD(true)}
                          placeholder="Rechercher un produit..." style={{ ...SEARCH_INPUT, width: "100%", boxSizing: "border-box" }} />
                        {showPDD && (
                          <div style={{ position: "absolute", zIndex: 300, background: "#fff", border: "1px solid #e5e7eb", borderRadius: 10, maxHeight: 200, overflowY: "auto", boxShadow: "0 10px 30px #0003", width: "100%", top: "110%" }}>
                            {ddProds.slice(0, 10).map((p) => (
                              <div key={p.id} onClick={() => { setSelProd(p.id); setPSearch(""); setShowPDD(false); }}
                                style={{ padding: "10px 14px", cursor: "pointer", borderBottom: "1px solid #f3f4f6" }}
                                onMouseEnter={(e) => e.currentTarget.style.background = "#f9fafb"} onMouseLeave={(e) => e.currentTarget.style.background = "#fff"}>
                                <div style={{ fontWeight: 600, fontSize: 13 }}>{p.description}</div>
                                <div style={{ fontSize: 11, color: "#9ca3af" }}>{p.id} — {fmt(p.prixHT)} DH HT — TVA {p.tva}%</div>
                              </div>
                            ))}
                            {ddProds.length === 0 && <div style={{ padding: 14, color: "#9ca3af", fontSize: 13 }}>Aucun produit trouve</div>}
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                  <div style={{ width: 110 }}>
                    <label style={{ display: "block", fontSize: 11, fontWeight: 600, color: "#6b7280", marginBottom: 5 }}>QUANTITE</label>
                    <input type="number" min="0.01" step="0.01" value={prodQte} onChange={(e) => setProdQte(parseFloat(e.target.value) || 1)}
                      style={{ width: "100%", border: "1.5px solid #d1d5db", borderRadius: 8, padding: "9px 12px", fontSize: 14, outline: "none", boxSizing: "border-box", textAlign: "center", fontWeight: 700 }} />
                  </div>
                  <button onClick={addLine} disabled={!selProd}
                    style={{ ...BTN_PRIMARY, opacity: selProd ? 1 : 0.4, height: 40, padding: "0 20px" }}>
                    + Ajouter
                  </button>
                </div>
              </div>

              {/* Lines table */}
              {fForm.lignes.length > 0 && (
                <div style={{ marginBottom: 20 }}>
                  <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
                    <thead>
                      <tr>{["Ref.", "Description", "PU HT", "Qte", "TVA", "Montant HT", ""].map((h) => <th key={h} style={{ ...TH, fontSize: 10 }}>{h}</th>)}</tr>
                    </thead>
                    <tbody>
                      {fForm.lignes.map((l, i) => (
                        <tr key={i}>
                          <td style={{ ...TD, fontFamily: "monospace", color: GOLD, fontWeight: 700, fontSize: 12 }}>{l.ref}</td>
                          <td style={{ ...TD, maxWidth: 220 }}><div style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{l.description}</div></td>
                          <td style={TD}>{fmt(l.prixHT)}</td>
                          <td style={{ ...TD, textAlign: "center" }}>
                            <input type="number" min="0.01" step="0.01" value={l.qte}
                              onChange={(e) => { const u = [...fForm.lignes]; u[i] = { ...u[i], qte: parseFloat(e.target.value) || 1 }; setFForm({ ...fForm, lignes: u }); }}
                              style={{ width: 66, border: "1px solid #d1d5db", borderRadius: 6, padding: "4px 8px", textAlign: "center", fontWeight: 700, fontSize: 13 }} />
                          </td>
                          <td style={TD}>{l.tva}%</td>
                          <td style={{ ...TD, fontWeight: 700 }}>{fmt(l.prixHT * l.qte)} DH</td>
                          <td style={TD}><SmallBtn label="X" bg="#fee2e2" color="#991b1b" onClick={() => setFForm({ ...fForm, lignes: fForm.lignes.filter((_, idx) => idx !== i) })} /></td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  <div style={{ display: "flex", justifyContent: "flex-end", marginTop: 12 }}>
                    <div style={{ minWidth: 270, border: "1px solid #e5e7eb", borderRadius: 10, overflow: "hidden" }}>
                      {[["Total HT", fmt(totHT) + " DH"], ["Total TVA", fmt(totTVA) + " DH"]].map(([l, v]) => (
                        <div key={l} style={{ display: "flex", justifyContent: "space-between", padding: "9px 16px", borderBottom: "1px solid #e5e7eb", background: "#fafaf8" }}>
                          <span style={{ color: "#6b7280", fontSize: 13 }}>{l}</span>
                          <span style={{ fontWeight: 700, fontSize: 13 }}>{v}</span>
                        </div>
                      ))}
                      <div style={{ display: "flex", justifyContent: "space-between", padding: "12px 16px", background: DARK }}>
                        <span style={{ color: "#aaa", fontWeight: 700, fontSize: 13 }}>Total TTC</span>
                        <span style={{ color: GOLD, fontWeight: 900, fontSize: 16 }}>{fmt(totTTC)} DH</span>
                      </div>
                    </div>
                  </div>
                </div>
              )}

              <div style={{ display: "flex", justifyContent: "flex-end", gap: 10, paddingTop: 16, borderTop: "1px solid #e5e7eb" }}>
                <button onClick={() => { setFactModal(false); setSimulatorLines(null); }} style={BTN_SECONDARY}>Annuler</button>
                <button onClick={saveFact} style={BTN_PRIMARY}>{editingFact ? "Mettre à jour" : "Enregistrer la Facture"}</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ═══ MODAL : CLIENT ═══ */}
      {clientModal && (
        <OverlayModal title={clientModal === "add" ? "Nouveau Client" : "Modifier Client"} onClose={() => setClientModal(null)}>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0 16px" }}>
            <TextInput label="Nom / Raison Sociale" value={cForm.nom} onChange={(v) => setCForm({ ...cForm, nom: v })} required style={{ gridColumn: "1 / -1" }} />
            <SelectInput label="Type" value={cForm.type} onChange={(v) => setCForm({ ...cForm, type: v })} options={["Particulier", "Professionnel"]} placeholder="Selectionner..." />
            <TextInput label="ICE" value={cForm.ice} onChange={(v) => setCForm({ ...cForm, ice: v })} placeholder="000000000000000" />
            <TextInput label="Adresse" value={cForm.adresse} onChange={(v) => setCForm({ ...cForm, adresse: v })} style={{ gridColumn: "1 / -1" }} />
            <TextInput label="Ville" value={cForm.ville} onChange={(v) => setCForm({ ...cForm, ville: v })} />
            <TextInput label="Telephone" value={cForm.tel} onChange={(v) => setCForm({ ...cForm, tel: v })} />
            <TextInput label="Email" value={cForm.email} onChange={(v) => setCForm({ ...cForm, email: v })} type="email" style={{ gridColumn: "1 / -1" }} />
          </div>
          <div style={{ display: "flex", justifyContent: "flex-end", gap: 10, marginTop: 6 }}>
            <button onClick={() => setClientModal(null)} style={BTN_SECONDARY}>Annuler</button>
            <button onClick={saveClient} style={BTN_PRIMARY}>Enregistrer</button>
          </div>
        </OverlayModal>
      )}

      {/* ═══ MODAL : PRODUIT ═══ */}
      {prodModal && (
        <OverlayModal title={prodModal === "add" ? "Nouveau Produit" : "Modifier Produit"} onClose={() => setProdModal(null)}>
          <TextInput label="Description" value={pForm.description} onChange={(v) => setPForm({ ...pForm, description: v })} required placeholder="Description du produit ou service" />
          <SelectInput label="Catégorie" value={pForm.categorie || ""} onChange={(v) => setPForm({ ...pForm, categorie: v })}
            options={[{ value: "", label: "— Sans catégorie —" }, ...allCategories.map((c) => ({ value: c, label: c }))]} />
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: "0 16px" }}>
            <div>
              <label style={{ display: "block", fontSize: 11, fontWeight: 700, color: "#374151", marginBottom: 5, textTransform: "uppercase", letterSpacing: "0.05em" }}>
                Prix HT (DH) <span style={{ color: "#ef4444" }}>*</span>
              </label>
              <input type="number" step="0.01" value={String(pForm.prixHT)}
                onChange={(e) => {
                  const ht = e.target.value;
                  setPForm(prev => ({ ...prev, prixHT: ht }));
                  const ttc = parseFloat(ht) ? parseFloat(ht) * (1 + pForm.tva / 100) : "";
                  setPFormTTC(ttc ? String(parseFloat(ttc.toFixed(4))) : "");
                }}
                placeholder="0.00"
                style={{ width: "100%", border: "1.5px solid #d1d5db", borderRadius: 8, padding: "9px 12px", fontSize: 14, outline: "none", boxSizing: "border-box" }} />
            </div>
            <SelectInput label="Taux TVA" value={String(pForm.tva)} onChange={(v) => {
                const newTva = parseFloat(v);
                setPForm(prev => ({ ...prev, tva: newTva }));
                if (pForm.prixHT) {
                  const ttc = parseFloat(pForm.prixHT) * (1 + newTva / 100);
                  setPFormTTC(String(parseFloat(ttc.toFixed(4))));
                }
              }}
              options={[{ value: "0", label: "0%" }, { value: "10", label: "10%" }, { value: "14", label: "14%" }, { value: "20", label: "20%" }]} />
            <div>
              <label style={{ display: "block", fontSize: 11, fontWeight: 700, color: "#374151", marginBottom: 5, textTransform: "uppercase", letterSpacing: "0.05em" }}>
                Prix TTC (DH) <span style={{ fontSize: 10, color: "#6b7280", fontWeight: 400 }}>(auto↔HT)</span>
              </label>
              <input type="number" step="0.01"
                value={pFormTTC}
                onChange={(e) => {
                  const raw = e.target.value;
                  setPFormTTC(raw);
                  const ttc = parseFloat(raw) || 0;
                  const ht = pForm.tva ? ttc / (1 + pForm.tva / 100) : ttc;
                  setPForm(prev => ({ ...prev, prixHT: ttc ? ht.toFixed(4) : "" }));
                }}
                placeholder="0.00"
                style={{ width: "100%", border: "1.5px solid #86efac", borderRadius: 8, padding: "9px 12px", fontSize: 14, outline: "none", boxSizing: "border-box", background: "#f0fdf4" }} />
            </div>
          </div>
          {pForm.prixHT && (
            <div style={{ background: "#f0fdf4", border: "1px solid #86efac", borderRadius: 8, padding: "10px 14px", marginBottom: 0, display: "flex", justifyContent: "space-between" }}>
              <span style={{ color: "#166534", fontSize: 13 }}>HT : <b>{fmt(parseFloat(pForm.prixHT || 0))} DH</b> → TTC :</span>
              <span style={{ fontWeight: 900, color: "#166534", fontSize: 15 }}>{fmt(parseFloat(pForm.prixHT || 0) * (1 + pForm.tva / 100))} DH</span>
            </div>
          )}
          <div style={{ display: "flex", justifyContent: "flex-end", gap: 10 }}>
            <button onClick={() => setProdModal(null)} style={BTN_SECONDARY}>Annuler</button>
            <button onClick={saveProd} style={BTN_PRIMARY}>Enregistrer</button>
          </div>
        </OverlayModal>
      )}

      {/* ═══ APERCU FACTURE ═══ */}
      {previewFact && (
        <InvoicePreview facture={previewFact} clients={clients} logoUrl={logoUrl} companyInfo={companyInfo} profilId={profilActif?.id} onClose={() => setPreviewFact(null)} />
      )}

      {/* ═══ DIV CACHÉ POUR GÉNÉRATION PDF ═══ */}
      <div ref={dlContainerRef} style={{ position: "fixed", left: "-9999px", top: 0, width: "794px", height: "1123px", overflow: "hidden", background: "#fff", pointerEvents: "none", zIndex: -999 }}>
        {dlFact && (
          <InvoiceDoc
            facture={dlFact}
            clients={clients}
            logoUrl={logoUrl}
            companyInfo={companyInfo}
            profilId={profilActif?.id}
          />
        )}
      </div>

      {/* ═══ TOAST STATUT TÉLÉCHARGEMENT ═══ */}
      {dlStatus && (
        <div style={{
          position: "fixed", bottom: 28, right: 28, zIndex: 9999,
          background: dlStatus === "generating" ? DARK : dlStatus === "done" ? "#166534" : "#991b1b",
          color: "#fff", borderRadius: 12, padding: "14px 22px",
          display: "flex", alignItems: "center", gap: 12,
          boxShadow: "0 8px 30px #0004", fontSize: 14, fontWeight: 600,
          animation: "fadeIn .3s ease",
        }}>
          <span style={{ fontSize: 22 }}>
            {dlStatus === "generating" ? "⏳" : dlStatus === "done" ? "✅" : "❌"}
          </span>
          <div>
            {dlStatus === "generating" && <><div>Génération du PDF en cours...</div><div style={{ fontSize: 11, color: "#aaa", marginTop: 2 }}>Veuillez patienter</div></>}
            {dlStatus === "done" && <><div>PDF téléchargé avec succès !</div><div style={{ fontSize: 11, color: "#86efac", marginTop: 2 }}>Fichier enregistré dans votre dossier</div></>}
            {dlStatus === "error" && <><div>Erreur lors de la génération</div><div style={{ fontSize: 11, color: "#fca5a5", marginTop: 2 }}>Vérifiez la console pour plus de détails</div></>}
          </div>
        </div>
      )}

      {/* ═══ IMPORT EXCEL ═══ */}
      {importModal && (
        <ImportModal
          type={importModal}
          existingCount={importModal === "clients" ? clients.length : products.length}
          onClose={() => setImportModal(null)}
          onImport={(items, mode) => { handleImport(items, mode); }}
        />
      )}

      {/* ╔══ MODAL : ÉDITION PROFIL ══╗ */}
      {editProfilModal && (
        <div style={{ position: "fixed", inset: 0, background: "#000000cc", zIndex: 4000, display: "flex", alignItems: "center", justifyContent: "center" }}>
          <div style={{ background: "#fff", borderRadius: 18, padding: "28px 32px", width: 480, maxWidth: "95vw", boxShadow: "0 20px 60px #00000040" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 22, paddingBottom: 16, borderBottom: "1px solid #f0f0f0" }}>
              <div style={{ width: 14, height: 14, borderRadius: "50%", background: editProfilModal.couleur || GOLD }} />
              <h3 style={{ margin: 0, fontSize: 17, fontWeight: 800, color: DARK }}>Modifier le profil</h3>
              <button onClick={() => setEditProfilModal(null)} style={{ marginLeft: "auto", background: "#f3f4f6", border: "none", borderRadius: 8, width: 32, height: 32, cursor: "pointer", fontSize: 16, color: "#6b7280" }}>✕</button>
            </div>

            <div style={{ display: "grid", gridTemplateColumns: "1fr auto", gap: 12, marginBottom: 14 }}>
              <div>
                <label style={{ display: "block", fontSize: 11, fontWeight: 700, color: "#374151", marginBottom: 5, textTransform: "uppercase", letterSpacing: "0.05em" }}>Nom du profil</label>
                <input value={editProfilModal.nom}
                  onChange={e => setEditProfilModal({ ...editProfilModal, nom: e.target.value })}
                  style={{ width: "100%", border: "1.5px solid #d1d5db", borderRadius: 8, padding: "9px 12px", fontSize: 14, outline: "none", boxSizing: "border-box", fontFamily: "inherit" }} />
              </div>
              <div>
                <label style={{ display: "block", fontSize: 11, fontWeight: 700, color: "#374151", marginBottom: 5, textTransform: "uppercase", letterSpacing: "0.05em" }}>Couleur</label>
                <input type="color" value={editProfilModal.couleur || GOLD}
                  onChange={e => setEditProfilModal({ ...editProfilModal, couleur: e.target.value })}
                  style={{ width: 50, height: 40, border: "1.5px solid #d1d5db", borderRadius: 8, cursor: "pointer", padding: 2 }} />
              </div>
            </div>

            <div style={{ fontSize: 12, fontWeight: 700, color: "#374151", textTransform: "uppercase", letterSpacing: "0.05em", marginBottom: 10, marginTop: 4 }}>Informations de l'entreprise</div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0 14px" }}>
              {[
                { key: "nom",     label: "Nom / Raison Sociale", full: true },
                { key: "adresse", label: "Adresse (pied de page)", full: true },
                { key: "rc",      label: "RC",    full: false },
                { key: "if_",     label: "IF",    full: false },
                { key: "tp",      label: "TP",    full: false },
                { key: "ice",     label: "ICE",   full: false },
                { key: "email",   label: "Email", full: true },
              ].map(f => (
                <div key={f.key} style={{ marginBottom: 10, gridColumn: f.full ? "1 / -1" : "auto" }}>
                  <label style={{ display: "block", fontSize: 11, fontWeight: 700, color: "#374151", marginBottom: 4, textTransform: "uppercase", letterSpacing: "0.05em" }}>{f.label}</label>
                  <input
                    value={editProfilModal.companyInfo?.[f.key] || ""}
                    onChange={e => setEditProfilModal({ ...editProfilModal, companyInfo: { ...editProfilModal.companyInfo, [f.key]: e.target.value } })}
                    style={{ width: "100%", border: "1.5px solid #d1d5db", borderRadius: 8, padding: "8px 11px", fontSize: 13, outline: "none", boxSizing: "border-box", fontFamily: "inherit" }}
                  />
                </div>
              ))}
            </div>

            <div style={{ display: "flex", justifyContent: "flex-end", gap: 10, marginTop: 16, paddingTop: 16, borderTop: "1px solid #f0f0f0" }}>
              <button onClick={() => setEditProfilModal(null)}
                style={{ background: "#f3f4f6", color: "#374151", border: "1px solid #e5e7eb", borderRadius: 10, padding: "10px 20px", cursor: "pointer", fontWeight: 600, fontSize: 14 }}>
                Annuler
              </button>
              <button
                onClick={() => {
                  setProfils(prev => prev.map(p => p.id === editProfilModal.id ? editProfilModal : p));
                  setEditProfilModal(null);
                }}
                style={{ background: editProfilModal.couleur || GOLD, color: "#fff", border: "none", borderRadius: 10, padding: "10px 22px", cursor: "pointer", fontWeight: 700, fontSize: 14 }}>
                Enregistrer
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
